INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88999, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "综合艺术是把唱歌、跳舞、说话等放在一起的表演。", "primary_collocate": null, "pronunciation": "zōng hé yì shù", "ipa": "t͡sʊŋ˥ xɤ˧˥ i˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "这个综合艺术节目有唱歌，也有跳舞。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "综合艺术里，有人唱歌，有人跳舞，有人说话。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末学校有一场综合艺术表演，我想去看。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在综合艺术表演中又唱又跳。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢综合艺术，因为可以看到很多表演。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班准备了一个综合艺术节目。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场综合艺术表演里，大家唱歌也说话。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带我去看了一场综合艺术表演。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "综合艺术让晚会更有意思。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在综合艺术节目里唱了一首歌。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场综合艺术", "label": "量词"}, {"form": "綜合藝術", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把唱歌、跳舞、说话等放在一起的表演", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '268e5b45-593e-400a-8278-6d6dad741940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88999, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "综合艺术", "is_correct": true, "explanation": "正确。综合艺术节目指把唱歌、跳舞等放在一起的表演节目，句意通顺。"}, {"text": "新闻", "is_correct": false, "explanation": "语义：新闻节目不会有唱歌和跳舞的内容，与句意冲突。"}, {"text": "学术", "is_correct": false, "explanation": "语域：“学术”是书面的专业用语，与口语化的唱歌跳舞节目不协调。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪节目讲的是做菜，不会有唱歌和跳舞。"}], "explanations": {"综合艺术": "正确。综合艺术节目指把唱歌、跳舞等放在一起的表演节目，句意通顺。", "新闻": "语义：新闻节目不会有唱歌和跳舞的内容，与句意冲突。", "学术": "语域：“学术”是书面的专业用语，与口语化的唱歌跳舞节目不协调。", "烹饪": "语义：烹饪节目讲的是做菜，不会有唱歌和跳舞。"}, "sentence_index": 0, "correct_answer": "综合艺术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天吃三次综合艺术。", "explanation": "这里应该用〈饭〉。综合艺术是表演形式，不是食物，不能吃。"}, {"text": "我的综合艺术坏了，需要修理。", "explanation": "这里应该用〈机器〉。综合艺术是表演形式，不是机器，不会坏，也不用修理。"}, {"text": "他在台上跳综合艺术，大家都鼓掌。", "explanation": "这里应该用〈舞蹈〉。“跳”的宾语应是舞蹈，综合艺术不能作“跳”的宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "综合艺术", "is_correct": true, "explanation": "正确。综合艺术表演里大家既唱歌又说话，句意通顺。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球比赛里不会有唱歌和说话的表演内容，与句意冲突。"}, {"text": "演讲", "is_correct": false, "explanation": "语义：演讲以说话为主，句中的“唱歌”无法放入演讲的内容。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“比赛表演”不是常用搭配，比赛也不是唱歌和说话并存的表演。"}], "explanations": {"综合艺术": "正确。综合艺术表演里大家既唱歌又说话，句意通顺。", "足球": "语义：足球比赛里不会有唱歌和说话的表演内容，与句意冲突。", "演讲": "语义：演讲以说话为主，句中的“唱歌”无法放入演讲的内容。", "比赛": "搭配：“比赛表演”不是常用搭配，比赛也不是唱歌和说话并存的表演。"}, "sentence_index": 6, "correct_answer": "综合艺术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下班后去综合艺术买菜。", "explanation": "这里应该用〈超市〉。综合艺术是表演形式，不是商店，不能去那里买菜。"}, {"text": "我的综合艺术生病了，要去看医生。", "explanation": "这里应该用〈宠物〉。综合艺术是表演形式，不是动物，不会生病，也不用看医生。"}, {"text": "他在台上变综合艺术，大家都鼓掌。", "explanation": "这里应该用〈魔术〉。“变”的宾语应是魔术，综合艺术不能作“变”的宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天我们班去看了一张综合艺术表演。", "corrected_sentence": "昨天我们班去看了一场综合艺术表演。", "error_description": "量词错误：错误形式为“一张综合艺术表演”，正确形式为“一场综合艺术表演”。“张”用于纸张、票据，表演应用“场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班准备了一场综合艺术地表演。", "corrected_sentence": "我们班准备了一场综合艺术表演。", "error_description": "结构助词错误：名词性的“综合艺术”后不能直接加“地”，错误形式为“综合艺术地表演”，正确形式为“综合艺术表演”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
