INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "融合多种艺术形式于一体的艺术，如戏剧、电影。", "primary_collocate": null, "pronunciation": "zōng hé yì shù", "ipa": "t͡sʊŋ˥ xɤ˧˥ i˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "戏剧是一种综合艺术，有故事，也有音乐。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影是综合艺术，需要很多人一起工作。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌剧是把音乐和表演放在一起的综合艺术。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人说电影是最受欢迎的综合艺术。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台剧里有灯光、音乐和舞蹈，是综合艺术。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对综合艺术很感兴趣，想以后拍电影。", "target_word": "综合艺术", "complexity_tier": "T3", "furigana": "tā duì zōng hé yì shù hěn gǎn xìng qù, xiǎng yǐ hòu pāi diàn yǐng。", "sentence_source": "generated"}, {"text": "综合艺术需要导演、演员和音乐家合作。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常带学生去剧院，让他们了解综合艺术。", "target_word": "综合艺术", "complexity_tier": "T3", "furigana": "lǎo shī cháng dài xué shēng qù jù yuàn, ràng tā men liǎo jiě zōng hé yì shù。", "sentence_source": "generated"}, {"text": "京剧也是综合艺术，有唱、念、做、打。", "target_word": "综合艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "综合艺术里，音乐特别重要，它能让戏剧更动人。", "target_word": "综合艺术", "complexity_tier": "T3", "furigana": "zōng hé yì shù lǐ, yīn yuè tè bié zhòng yào, tā néng ràng xì jù gèng dòng rén。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种综合艺术", "label": "量词"}, {"form": "綜合藝術", "label": "繁体"}], "register": "中性", "sense_fingerprint": "融合戏剧、电影等多种艺术形式的艺术门类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '268e5b45-593e-400a-8278-6d6dad741940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "综合艺术", "is_correct": true, "explanation": "正确。戏剧属于融合多种艺术形式的综合艺术，句意通顺。"}, {"text": "体育", "is_correct": false, "explanation": "语义：体育不是有故事、有音乐的艺术形式，“戏剧是一种体育”与句意不符。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：下文“也有音乐”把音乐当作与戏剧并列的成分，“戏剧是一种音乐”与之自相矛盾。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是纯文字的叙事作品，没有表演，也没有音乐，“戏剧是一种小说”与句中的“也有音乐”不符。"}], "explanations": {"综合艺术": "正确。戏剧属于融合多种艺术形式的综合艺术，句意通顺。", "体育": "语义：体育不是有故事、有音乐的艺术形式，“戏剧是一种体育”与句意不符。", "音乐": "语义：下文“也有音乐”把音乐当作与戏剧并列的成分，“戏剧是一种音乐”与之自相矛盾。", "小说": "语义：小说是纯文字的叙事作品，没有表演，也没有音乐，“戏剧是一种小说”与句中的“也有音乐”不符。"}, "sentence_index": 0, "correct_answer": "综合艺术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的朋友是综合艺术。", "explanation": "这里应该用〈艺术家〉。综合艺术是艺术门类，不能指人，说人时要用艺术家。"}, {"text": "他的综合艺术很强，各科成绩都不错。", "explanation": "这里应该用〈综合能力〉。综合艺术是艺术门类，不能用来形容人的能力。"}, {"text": "我今天买了两斤综合艺术。", "explanation": "这里应该用〈苹果〉。综合艺术是艺术门类，不是可以称重买卖的实物，说“买两斤”的应是苹果等食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "综合艺术", "is_correct": true, "explanation": "正确。综合艺术需要导演、演员和音乐家共同合作，句意通顺。"}, {"text": "农业", "is_correct": false, "explanation": "语义：农业活动与导演、演员无关，不需要这类合作。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“需要……合作”的主语应是多人合作完成的作品或活动，“乐器”是单件物品，不能搭配。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是烹饪指南，不需要导演和演员参与。"}], "explanations": {"综合艺术": "正确。综合艺术需要导演、演员和音乐家共同合作，句意通顺。", "农业": "语义：农业活动与导演、演员无关，不需要这类合作。", "乐器": "搭配：“需要……合作”的主语应是多人合作完成的作品或活动，“乐器”是单件物品，不能搭配。", "食谱": "语义：食谱是烹饪指南，不需要导演和演员参与。"}, "sentence_index": 6, "correct_answer": "综合艺术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部综合艺术很有名，讲了一个爱情故事。", "explanation": "这里应该用〈名著〉。综合艺术指艺术门类，不是某一部具体的作品。"}, {"text": "我用这个综合艺术擦桌子。", "explanation": "这里应该用〈抹布〉。综合艺术是艺术门类，不是用具，不能用来擦桌子。"}, {"text": "那个综合艺术很好喝，大家都喜欢。", "explanation": "这里应该用〈果汁〉。综合艺术不是饮料，不能说好喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电影是一只综合艺术，需要很多人一起合作。", "corrected_sentence": "电影是一门综合艺术，需要很多人一起合作。", "error_description": "量词错误：错误形式为“一只综合艺术”，正确形式为“一门综合艺术”。“只”用于动物或小物件，综合艺术作为艺术门类应用“门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想了解一门的综合艺术，它把音乐和表演放在一起。", "corrected_sentence": "我想了解一门综合艺术，它把音乐和表演放在一起。", "error_description": "结构助词错误：“一门”后面不能直接加“的”，错误形式为“一门的综合艺术”，正确形式为“一门综合艺术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00a4cb34-12ff-4c17-98e5-8f51c2a66def') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
