INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89003, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "常识是大家都应该知道的最简单的事。", "primary_collocate": null, "pronunciation": "cháng shí", "ipa": "ʈʂʰaŋ˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "水往低处流是常识。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是生活常识，大家都应该知道。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他连这样的常识都不懂。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路要看红绿灯，这是最基本的常识。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了很多安全常识。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天不穿厚衣服会感冒，这是常识。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么会不知道？这是常识啊！", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很聪明，但是缺少生活常识。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "常识告诉我们，火是很危险的。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点常识大家都有，不用别人提醒。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生活常识", "label": "复合"}, {"form": "安全常识", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家都应该知道的最简单的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01aef012-b953-4027-8c37-cd1db6afc7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89003, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "常识", "is_correct": true, "explanation": "常识：大家都应该知道的最简单的事，正确答案。"}, {"text": "诚实", "is_correct": false, "explanation": "ng（chéng）与 ang（cháng）的韵母不同（eng／ang），诚实指真实、不说假话。"}, {"text": "尝试", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，尝试指试一试。"}, {"text": "常事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，常事指平常的事。"}], "explanations": {"常识": "常识：大家都应该知道的最简单的事，正确答案。", "诚实": "ng（chéng）与 ang（cháng）的韵母不同（eng／ang），诚实指真实、不说假话。", "尝试": "shì（第四声）与 shí（第二声）声调不同，尝试指试一试。", "常事": "shì（第四声）与 shí（第二声）声调不同，常事指平常的事。"}, "sentence_index": null, "correct_answer": "常识"}, "level_3": {"options": [{"text": "常识", "is_correct": true, "explanation": "“水往低处流”是大家都知道的道理，属于常识。"}, {"text": "故事", "is_correct": false, "explanation": "语义：“水往低处流”是自然规律，不是故事。"}, {"text": "游戏", "is_correct": false, "explanation": "搭配：“是游戏”指一种活动，不用来说明自然现象。"}, {"text": "秘密", "is_correct": false, "explanation": "语义：水往低处流是人人都知道的道理，不是秘密。"}], "explanations": {"常识": "“水往低处流”是大家都知道的道理，属于常识。", "故事": "语义：“水往低处流”是自然规律，不是故事。", "游戏": "搭配：“是游戏”指一种活动，不用来说明自然现象。", "秘密": "语义：水往低处流是人人都知道的道理，不是秘密。"}, "sentence_index": 0, "correct_answer": "常识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位工程师对这个问题的常识很独到。", "explanation": "这里应该用〈见解〉。常识指人人都该知道的简单道理，不能说“独到”；个人独特的看法要说见解。"}, {"text": "他专门研究历史常识，已经写了好几本书。", "explanation": "这里应该用〈知识〉。常识不是学科，不能作为专门研究的对象。"}, {"text": "他的常识非常高，能解决最难的数学题。", "explanation": "这里应该用〈水平〉。常识是人人都知道的简单道理，不能说“高”，数学能力要说水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常识", "is_correct": true, "explanation": "“这是常识啊”正好回应“你怎么会不知道”，说明这是人人都该知道的道理。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“礼物”不是大家都该知道的道理，与问话语境不符。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“这是乐器啊”无法回应“你怎么会不知道”，搭配不通。"}, {"text": "遗憾", "is_correct": false, "explanation": "语义：“遗憾”是心情，与“你怎么会不知道”的语境不合。"}], "explanations": {"常识": "“这是常识啊”正好回应“你怎么会不知道”，说明这是人人都该知道的道理。", "礼物": "语义：“礼物”不是大家都该知道的道理，与问话语境不符。", "乐器": "搭配：“这是乐器啊”无法回应“你怎么会不知道”，搭配不通。", "遗憾": "语义：“遗憾”是心情，与“你怎么会不知道”的语境不合。"}, "sentence_index": 6, "correct_answer": "常识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的常识很熟练，修理汽车又快又好。", "explanation": "这里应该用〈技术〉。常识指一般人都该知道的简单道理，不能形容熟练程度；修车的本领要说技术。"}, {"text": "这台电脑的常识很好，能运行大型软件。", "explanation": "这里应该用〈性能〉。常识是人的基本认识，不能用来形容机器的好坏。"}, {"text": "这一瓶常识很重要，大家都要学。", "explanation": "量词错误：“瓶”用于装液体的容器，计量抽象的常识应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
