INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一般人都应该知道的知识。", "primary_collocate": null, "pronunciation": "cháng shí", "ipa": "ʈʂʰaŋ˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他读了很多书，常识很丰富。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题考的是历史常识。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷懂很多农业常识。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要多学一点医药常识。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了很多天文常识。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对电脑常识了解得不多。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他缺乏法律常识，所以吃了亏。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，老师让我们复习一下地理常识。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些都是普通人应该知道的常识。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有一点常识的人，很容易上当。", "target_word": "常识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生活常识", "label": "复合"}, {"form": "安全常识", "label": "复合"}], "register": "中性", "sense_fingerprint": "一般人都应该知道的知识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01aef012-b953-4027-8c37-cd1db6afc7eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89004, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "常识", "is_correct": true, "explanation": "常识：一般人都应该知道的知识，正确答案。"}, {"text": "诚实", "is_correct": false, "explanation": "ng（chéng）与 ang（cháng）的韵母不同（eng／ang），诚实指真实、不说假话。"}, {"text": "尝试", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，尝试指试一试。"}, {"text": "常事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，常事指平常的事。"}], "explanations": {"常识": "常识：一般人都应该知道的知识，正确答案。", "诚实": "ng（chéng）与 ang（cháng）的韵母不同（eng／ang），诚实指真实、不说假话。", "尝试": "shì（第四声）与 shí（第二声）声调不同，尝试指试一试。", "常事": "shì（第四声）与 shí（第二声）声调不同，常事指平常的事。"}, "sentence_index": null, "correct_answer": "常识"}, "level_3": {"options": [{"text": "常识", "is_correct": true, "explanation": "“常识很丰富”说明读书积累的是一般人都该知道的知识。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气很丰富”说不通，且与读书的语境无关。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”不和“丰富”搭配，“脾气很丰富”不成立。"}, {"text": "身体", "is_correct": false, "explanation": "语义：读书增加的是知识，“身体很丰富”与语境冲突。"}], "explanations": {"常识": "“常识很丰富”说明读书积累的是一般人都该知道的知识。", "天气": "语义：“天气很丰富”说不通，且与读书的语境无关。", "脾气": "搭配：“脾气”不和“丰富”搭配，“脾气很丰富”不成立。", "身体": "语义：读书增加的是知识，“身体很丰富”与语境冲突。"}, "sentence_index": 0, "correct_answer": "常识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他专门研究量子力学常识，已经写了三本书。", "explanation": "这里应该用〈知识〉。常识指人人都该知道的基本道理，量子力学这类专门内容要说知识。"}, {"text": "他的常识很精湛，做出的家具很漂亮。", "explanation": "这里应该用〈技艺〉。常识指一般人都该知道的知识，不能用“精湛”形容；做家具的手艺要说技艺。"}, {"text": "这一把常识很有用，大家都要学。", "explanation": "量词错误：“把”多用于有柄的器具，常识要用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常识", "is_correct": true, "explanation": "“缺乏法律常识”是指缺少一般人都该知道的法律基本知识，正确。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”指平面的大小，与“缺乏法律”不搭。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：“花朵”与法律无关，语义不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“法律颜色”搭配不通，“缺乏颜色”也说不通。"}], "explanations": {"常识": "“缺乏法律常识”是指缺少一般人都该知道的法律基本知识，正确。", "面积": "语义：“面积”指平面的大小，与“缺乏法律”不搭。", "花朵": "语义：“花朵”与法律无关，语义不通。", "颜色": "搭配：“法律颜色”搭配不通，“缺乏颜色”也说不通。"}, "sentence_index": 6, "correct_answer": "常识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的常识很好，跑得很快。", "explanation": "这里应该用〈性能〉。常识是人的基本认识，不能用来形容车辆的好坏。"}, {"text": "这本书的常识写得很深，适合研究者看。", "explanation": "常识指一般人都该知道的知识，不能用“写得很深”来形容，这里应该说〈专业知识〉。"}, {"text": "他的常识很厚，有三百多页。", "explanation": "常识是抽象的知识，不能用“厚”来形容，这里应该说〈书〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子应该学一只常识。", "corrected_sentence": "孩子应该学常识。", "error_description": "错误在量词：“只”用于动物或单个物件，不能修饰“常识”，应说“学常识”（也可说“学一点常识”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597f79dc-b735-4df8-90df-c77d93635d1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
