INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89005, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "维基是一种网站。很多人都可以在上面写东西。", "primary_collocate": null, "pronunciation": "wéi jī", "ipa": "weɪ˧˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "我常在维基上查资料。", "target_word": "维基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个维基是大家一起写的。", "target_word": "维基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在维基上写了一篇文章。", "target_word": "维基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们用维基做小组作业。", "target_word": "维基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个维基里有很多有用的东西。", "target_word": "维基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司有一个自己的维基。", "target_word": "维基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以在维基上改错字。", "target_word": "维基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的班级维基每天都有新内容。", "target_word": "维基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个维基不用花钱。", "target_word": "维基", "complexity_tier": "T3", "furigana": "zhè ge wéijī bú yòng huā qián.", "sentence_source": "generated"}, {"text": "他把旅行经验写到了维基上。", "target_word": "维基", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "維基", "label": "繁体"}, {"form": "维基百科", "label": "复合"}], "register": "通用", "sense_fingerprint": "很多人都能在上面写内容的网站", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '572e04e2-6b86-4c93-ad0e-9ef951c337f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89005, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "危机", "is_correct": false, "explanation": "wēi（第一声）与 wéi（第二声）声调不同，意思是危险的紧要关头。"}, {"text": "危急", "is_correct": false, "explanation": "wēi 与 wéi 声调不同，jí 与 jī 声调也不同，意思是情况紧急。"}, {"text": "维基", "is_correct": true, "explanation": "正确答案：维基（wéi jī），指多人可以共同编辑内容的网站。"}, {"text": "伟绩", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是伟大的功绩。"}], "explanations": {"危机": "wēi（第一声）与 wéi（第二声）声调不同，意思是危险的紧要关头。", "危急": "wēi 与 wéi 声调不同，jí 与 jī 声调也不同，意思是情况紧急。", "维基": "正确答案：维基（wéi jī），指多人可以共同编辑内容的网站。", "伟绩": "wěi（第三声）与 wéi（第二声）声调不同，意思是伟大的功绩。"}, "sentence_index": null, "correct_answer": "维基"}, "level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱上没法查资料，与句意矛盾。"}, {"text": "维基", "is_correct": true, "explanation": "正确答案：“在维基上”指在这个网站上查找信息，与“查资料”相符。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯不是查资料的地方，与句意矛盾。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "搭配：“在垃圾桶上”不是表示查资料地点的常见说法。"}], "explanations": {"冰箱": "语义：冰箱上没法查资料，与句意矛盾。", "维基": "正确答案：“在维基上”指在这个网站上查找信息，与“查资料”相符。", "电梯": "语义：电梯不是查资料的地方，与句意矛盾。", "垃圾桶": "搭配：“在垃圾桶上”不是表示查资料地点的常见说法。"}, "sentence_index": 0, "correct_answer": "维基"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都去维基里取报纸。", "explanation": "这里应该用〈报箱〉。维基是网站，不能像报箱一样用来取报纸。"}, {"text": "他在维基里做了一锅好菜。", "explanation": "这里应该用〈厨房〉。维基是网站，不能用来做菜。"}, {"text": "他把全部积蓄存在维基里，准备买车。", "explanation": "这里应该用〈银行〉。维基是网站，不能用来存钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空上无法改错字，与句意矛盾。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能用来改错字，与句意矛盾。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“在树叶上改错字”不符合常规说法，树叶也不是可以修改文字的载体。"}, {"text": "维基", "is_correct": true, "explanation": "正确答案：“在维基上改错字”指在多人可编辑的网站上修改内容。"}], "explanations": {"天空": "语义：天空上无法改错字，与句意矛盾。", "河流": "语义：河流不能用来改错字，与句意矛盾。", "树叶": "搭配：“在树叶上改错字”不符合常规说法，树叶也不是可以修改文字的载体。", "维基": "正确答案：“在维基上改错字”指在多人可编辑的网站上修改内容。"}, "sentence_index": 6, "correct_answer": "维基"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把私人邮件存在维基里。", "explanation": "这里应该用〈邮箱〉。维基是多人共同编辑的网站，不用来存放私人邮件。"}, {"text": "他把照片拷进维基里备份。", "explanation": "这里应该用〈U盘〉。维基是网站，不能用来拷贝和备份个人照片。"}, {"text": "他把钥匙挂在维基上。", "explanation": "这里应该用〈墙壁〉。维基是网站，不能用来挂东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班有一座维基，大家都可以修改。", "corrected_sentence": "我们班有一个维基，大家都可以修改。", "error_description": "错误形式：“一座维基”；正确形式：“一个维基”。维基是网站或系统，量词应用“个”，“座”多用于建筑物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我用了过维基查资料。", "corrected_sentence": "我用过维基查资料。", "error_description": "错误形式：“用了过维基”；正确形式：“用过维基”。表示经历的“过”紧跟动词“用”即可，不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
