INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89007, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "干部是在政府或单位里做事、管事的人。", "primary_collocate": null, "pronunciation": "gàn bù", "ipa": "kan˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "她爸爸是政府的干部。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个干部很会管事。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们单位新来了一位干部。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干部带着大家一起种树。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位干部每天都来得很早。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干部跟村民坐在一起聊天。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当干部。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位干部对人很热情。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "区里的干部来学校看孩子们。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识一位在街道工作的干部。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "领导干部", "label": "复合"}, {"form": "一位干部", "label": "量词"}, {"form": "一名干部", "label": "量词"}, {"form": "幹部", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在政府或单位里做事、管事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '216324cd-0d1f-4db4-b00d-b0895e448e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89007, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生是在学校读书的人，“政府的学生”句意不通。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不在政府任职，与“政府的”搭配冲突。"}, {"text": "干部", "is_correct": true, "explanation": "正确：干部指在政府或单位里做事、管事的人，符合“政府的”。"}, {"text": "老爷", "is_correct": false, "explanation": "语域：“老爷”是旧时用语，用于现代中性的叙述语境不合适。"}], "explanations": {"学生": "语义：学生是在学校读书的人，“政府的学生”句意不通。", "病人": "语义：病人不在政府任职，与“政府的”搭配冲突。", "干部": "正确：干部指在政府或单位里做事、管事的人，符合“政府的”。", "老爷": "语域：“老爷”是旧时用语，用于现代中性的叙述语境不合适。"}, "sentence_index": 0, "correct_answer": "干部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食堂里的干部正在炒菜。", "explanation": "这里应该用〈厨师〉。干部指担任领导或管理工作的人员，不指炒菜的人。"}, {"text": "理发店里的干部正在给客人洗头。", "explanation": "这里应该用〈理发师〉。干部指在政府或单位里管事的人，不指给客人洗头、理发的人。"}, {"text": "病房里的干部正在打针。", "explanation": "这里应该用〈护士〉。干部指担任领导或管理工作的人员，不指给病人打针的护理人员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房子", "is_correct": false, "explanation": "语义：房子不能被“想当”，句意不通。"}, {"text": "干部", "is_correct": true, "explanation": "正确：“想当干部”表示希望担任干部职务，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能被“当”，“想当石头”句意不通。"}, {"text": "岗位", "is_correct": false, "explanation": "搭配：“当”后接人或职位，“想当岗位”不成立。"}], "explanations": {"房子": "语义：房子不能被“想当”，句意不通。", "干部": "正确：“想当干部”表示希望担任干部职务，符合语境。", "石头": "语义：石头不能被“当”，“想当石头”句意不通。", "岗位": "搭配：“当”后接人或职位，“想当岗位”不成立。"}, "sentence_index": 6, "correct_answer": "干部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院里的干部正在给病人看病。", "explanation": "这里应该用〈医生〉。干部指领导或管理人员，不指看病的医务人员。"}, {"text": "剧院里的干部正在表演节目。", "explanation": "这里应该用〈演员〉。干部不指在剧院表演的人。"}, {"text": "驾驶舱里的干部正在操作仪表。", "explanation": "这里应该用〈飞行员〉。干部指担任领导或管理工作的人员，不指驾驶飞机的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她姐姐是一只区里的干部。", "corrected_sentence": "她姐姐是一位区里的干部。", "error_description": "量词错误：“干部”指人，应用“位”或“名”，不能用“只”。正确应说“一位区里的干部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经当十年干部。", "corrected_sentence": "他已经当了十年干部。", "error_description": "“了”漏用：“已经”表示动作已完成，应说“当了十年干部”，不能省略“了”说成“当十年干部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
