INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89008, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家机关、团体、企业等单位中担任领导或管理工作的人员。", "primary_collocate": null, "pronunciation": "gàn bù", "ipa": "kan˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这位干部在县政府工作。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的干部每天都很忙。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一名工厂的干部。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干部们正在开会。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校来了一位新干部。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个干部管着全村的事。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了二十年干部。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干部要认真听大家的意见。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的干部明天要去北京。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老干部很受人尊重。", "target_word": "干部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "领导干部", "label": "复合"}, {"form": "一位干部", "label": "量词"}, {"form": "一名干部", "label": "量词"}, {"form": "幹部", "label": "繁体"}], "register": "中性", "sense_fingerprint": "单位中担任领导或管理工作的人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '216324cd-0d1f-4db4-b00d-b0895e448e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生在学校读书，不在县政府工作，与“在县政府工作”冲突。"}, {"text": "干部", "is_correct": true, "explanation": "正确：干部指在单位中担任领导或管理工作的人员，符合“在县政府工作”。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是人，不能在县政府工作，与句子主语冲突。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不在政府工作，与“在县政府工作”冲突。"}], "explanations": {"学生": "语义：学生在学校读书，不在县政府工作，与“在县政府工作”冲突。", "干部": "正确：干部指在单位中担任领导或管理工作的人员，符合“在县政府工作”。", "椅子": "语义：椅子不是人，不能在县政府工作，与句子主语冲突。", "病人": "语义：病人不在政府工作，与“在县政府工作”冲突。"}, "sentence_index": 0, "correct_answer": "干部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医院的干部正在给病人看病。", "explanation": "这里应该用〈医生〉。干部指担任领导或管理工作的人员，不指从事医疗工作的人。"}, {"text": "舞台上的干部正在表演。", "explanation": "这里应该用〈演员〉。干部指领导或管理人员，不指在舞台上表演的人。"}, {"text": "理发店里的干部正在给客人剪头发。", "explanation": "这里应该用〈理发师〉。干部指担任领导或管理工作的人员，不指给客人剪头发的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房子", "is_correct": false, "explanation": "语义：房子不能被“当”，“他当了二十年房子”句意不通。"}, {"text": "干部", "is_correct": true, "explanation": "正确：“当了二十年干部”表示担任干部职务二十年，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能被“当了二十年”，句意不通。"}, {"text": "岗位", "is_correct": false, "explanation": "搭配：“当”后接人或职位，“岗位”不能说“当了二十年岗位”。"}], "explanations": {"房子": "语义：房子不能被“当”，“他当了二十年房子”句意不通。", "干部": "正确：“当了二十年干部”表示担任干部职务二十年，符合语境。", "石头": "语义：石头不能被“当了二十年”，句意不通。", "岗位": "搭配：“当”后接人或职位，“岗位”不能说“当了二十年岗位”。"}, "sentence_index": 6, "correct_answer": "干部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饭店里的干部正在做菜。", "explanation": "这里应该用〈厨师〉。干部指担任领导或管理工作的人员，不指做菜的人。"}, {"text": "公交车上的干部正在开车。", "explanation": "这里应该用〈司机〉。干部指领导或管理人员，不指驾驶车辆的人。"}, {"text": "超市里的干部正在收银。", "explanation": "这里应该用〈收银员〉。干部指担任领导或管理工作的人员，不指在收银台结账的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "单位新调来了一只干部。", "corrected_sentence": "单位新调来了一位干部。", "error_description": "量词错误：“干部”指人，应用“位”或“名”，不能用“只”（“只”多用于动物或成对的物件）。正确应说“一位干部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们单位有三只年轻干部。", "corrected_sentence": "我们单位有三名年轻干部。", "error_description": "错误形式：“三只干部”。正确形式：“三名干部”。“干部”指人，应用“名”或“位”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
