INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89009, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "形势是事情现在发展的情况和样子。", "primary_collocate": null, "pronunciation": "xíng shì", "ipa": "ɕiŋ˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "今年的就业形势不太好。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情的形势已经稳定下来了。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "形势发展得比我们想的快。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很了解市场的形势。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到比赛形势不好，教练叫了暂停。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目前的形势对年轻人很有利。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当前形势下，我们要多存钱。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内外形势都在变化。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板根据形势改变了计划。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理向大家介绍了公司的形势。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "形勢", "label": "繁体"}, {"form": "就业形势", "label": "复合"}, {"form": "国际形势", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情当前发展的情况和样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b474a69-16b8-4d65-b10a-8b191cf12514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89009, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "形势", "is_correct": true, "explanation": "正确答案：形势（xíng shì）指事情当前发展的情况和样子。"}, {"text": "幸事", "is_correct": false, "explanation": "xìng 与 xíng 声调不同，意思是令人高兴的事。"}, {"text": "省视", "is_correct": false, "explanation": "xǐng 与 xíng 声调不同，意思是探望、察看（书面语）。"}, {"text": "行驶", "is_correct": false, "explanation": "shǐ 与 shì 声调不同，意思是车辆等前进。"}, {"text": "名士", "is_correct": false, "explanation": "míng 与 xíng 声母不同（m/x），意思是有名望的人。"}], "explanations": {"形势": "正确答案：形势（xíng shì）指事情当前发展的情况和样子。", "幸事": "xìng 与 xíng 声调不同，意思是令人高兴的事。", "省视": "xǐng 与 xíng 声调不同，意思是探望、察看（书面语）。", "行驶": "shǐ 与 shì 声调不同，意思是车辆等前进。", "名士": "míng 与 xíng 声母不同（m/x），意思是有名望的人。"}, "sentence_index": null, "correct_answer": "形势"}, "level_3": {"options": [{"text": "形势", "is_correct": true, "explanation": "形势：指就业的发展情况，与“今年的就业……不太好”相符。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，就业不能说“脾气”。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”指饮食的味道偏好，不能说“就业口味”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人或动物身体的温度，与就业无关。"}], "explanations": {"形势": "形势：指就业的发展情况，与“今年的就业……不太好”相符。", "脾气": "语义：“脾气”指人的性情，就业不能说“脾气”。", "口味": "搭配：“口味”指饮食的味道偏好，不能说“就业口味”。", "体温": "语义：“体温”指人或动物身体的温度，与就业无关。"}, "sentence_index": 0, "correct_answer": "形势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个商品的形势很便宜。", "explanation": "这里应该用〈价格〉。形势指事情发展的情况和样子，商品的价钱要说价格。"}, {"text": "这种动物的形势很特别。", "explanation": "这里应该用〈形态〉。形势指发展的情况，动物的外形和结构要说形态。"}, {"text": "他对工作的形势很认真。", "explanation": "这里应该用〈态度〉。形势指发展的情况，对待工作的看法和做法要说态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89009, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "形势", "is_correct": true, "explanation": "正确答案：形势（xíng shì）指事情当前发展的情况和样子。"}, {"text": "姓氏", "is_correct": false, "explanation": "xìng 与 xíng 声调不同，意思是姓的名称。"}, {"text": "情事", "is_correct": false, "explanation": "qíng 与 xíng 声母不同（q/x），意思是情感方面的事。"}, {"text": "省视", "is_correct": false, "explanation": "xǐng 与 xíng 声调不同，意思是探望、察看（书面语）。"}, {"text": "行使", "is_correct": false, "explanation": "shǐ 与 shì 声调不同，意思是按权力去做。"}], "explanations": {"形势": "正确答案：形势（xíng shì）指事情当前发展的情况和样子。", "姓氏": "xìng 与 xíng 声调不同，意思是姓的名称。", "情事": "qíng 与 xíng 声母不同（q/x），意思是情感方面的事。", "省视": "xǐng 与 xíng 声调不同，意思是探望、察看（书面语）。", "行使": "shǐ 与 shì 声调不同，意思是按权力去做。"}, "sentence_index": null, "correct_answer": "形势"}, "level_3": {"options": [{"text": "形势", "is_correct": true, "explanation": "形势：指当前的发展情况，与“当前……下”的结构相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能用于“当前……下”的情况判断。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“当前声音下”不成立，“声音”不能用于这种情境。"}, {"text": "身材", "is_correct": false, "explanation": "语义：“身材”指人的体形，与“当前……下”的情况无关。"}], "explanations": {"形势": "形势：指当前的发展情况，与“当前……下”的结构相符。", "颜色": "语义：“颜色”指色彩，不能用于“当前……下”的情况判断。", "声音": "搭配：“当前声音下”不成立，“声音”不能用于这种情境。", "身材": "语义：“身材”指人的体形，与“当前……下”的情况无关。"}, "sentence_index": 6, "correct_answer": "形势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告以图表的形势呈现。", "explanation": "这里应该用〈形式〉。形势指事情发展的情况和样子，表示表现方式要用形式。"}, {"text": "他把形势装进了箱子。", "explanation": "形势是抽象的发展状况，不是有形的东西，不能“装进”箱子。"}, {"text": "我们面对一把复杂的形势。", "explanation": "这里应该用〈种〉。“把”用于有柄的物品，形势要用量词“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份形势对小公司很不利。", "corrected_sentence": "这种形势对小公司很不利。", "error_description": "错误：这份形势。正确：这种形势。“份”多用于文件、饭菜等，形势是抽象名词，应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本形势让大家很担心。", "corrected_sentence": "这种形势让大家很担心。", "error_description": "错误：这本形势。正确：这种形势。“本”用于书本等，形势是抽象名词，应用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
