INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物发展的状况；情势。", "primary_collocate": null, "pronunciation": "xíng shì", "ipa": "ɕiŋ˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "现在的经济形势很好。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际形势变化得很快。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的形势越来越好了。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对严峻的形势，大家都很冷静。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我们要看清形势再做决定。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的形势对我们很有利。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争的形势每天都在变化。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "形势紧张，士兵们不敢休息。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据现在的形势，今年的工作要调整。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他分析了当前的形势。", "target_word": "形势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "形勢", "label": "繁体"}, {"form": "国际形势", "label": "复合"}, {"form": "经济形势", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物发展的状况、情势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b474a69-16b8-4d65-b10a-8b191cf12514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89010, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "形势", "is_correct": true, "explanation": "正确答案：形势（xíng shì）指事物发展的状况。"}, {"text": "幸事", "is_correct": false, "explanation": "xìng 与 xíng 声调不同，意思是令人高兴的事。"}, {"text": "省视", "is_correct": false, "explanation": "xǐng 与 xíng 声调不同，意思是探望、察看（书面语）。"}, {"text": "行驶", "is_correct": false, "explanation": "shǐ 与 shì 声调不同，意思是车辆等前进。"}, {"text": "名士", "is_correct": false, "explanation": "míng 与 xíng 声母不同（m/x），意思是有名望的人。"}], "explanations": {"形势": "正确答案：形势（xíng shì）指事物发展的状况。", "幸事": "xìng 与 xíng 声调不同，意思是令人高兴的事。", "省视": "xǐng 与 xíng 声调不同，意思是探望、察看（书面语）。", "行驶": "shǐ 与 shì 声调不同，意思是车辆等前进。", "名士": "míng 与 xíng 声母不同（m/x），意思是有名望的人。"}, "sentence_index": null, "correct_answer": "形势"}, "level_3": {"options": [{"text": "形势", "is_correct": true, "explanation": "形势：指经济的发展状况，与“经济”搭配，“形势很好”符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指冷暖晴雨等自然状况，不能说“经济天气”。"}, {"text": "身体", "is_correct": false, "explanation": "搭配：“身体”指人或动物的健康，经济不能说“身体很好”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是视觉上的色彩，与经济状况无关。"}], "explanations": {"形势": "形势：指经济的发展状况，与“经济”搭配，“形势很好”符合语境。", "天气": "语义：“天气”指冷暖晴雨等自然状况，不能说“经济天气”。", "身体": "搭配：“身体”指人或动物的健康，经济不能说“身体很好”。", "颜色": "语义：“颜色”是视觉上的色彩，与经济状况无关。"}, "sentence_index": 0, "correct_answer": "形势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在大家心中的形势很好。", "explanation": "这里应该用〈形象〉。形势指事物发展的状况，别人心中的印象要说形象。"}, {"text": "这个盒子的形势很特别。", "explanation": "这里应该用〈形状〉。形势指发展的情况，物体的外形要说形状。"}, {"text": "他的身体形势很差。", "explanation": "这里应该用〈状态〉。形势指事物发展的状况，身体的健康情况要说状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89010, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "形势", "is_correct": true, "explanation": "正确答案：形势（xíng shì）指事物发展的状况。"}, {"text": "姓氏", "is_correct": false, "explanation": "xìng 与 xíng 声调不同，意思是姓的名称。"}, {"text": "情事", "is_correct": false, "explanation": "qíng 与 xíng 声母不同（q/x），意思是情感方面的事。"}, {"text": "省视", "is_correct": false, "explanation": "xǐng 与 xíng 声调不同，意思是探望、察看（书面语）。"}, {"text": "行使", "is_correct": false, "explanation": "shǐ 与 shì 声调不同，意思是按权力去做。"}], "explanations": {"形势": "正确答案：形势（xíng shì）指事物发展的状况。", "姓氏": "xìng 与 xíng 声调不同，意思是姓的名称。", "情事": "qíng 与 xíng 声母不同（q/x），意思是情感方面的事。", "省视": "xǐng 与 xíng 声调不同，意思是探望、察看（书面语）。", "行使": "shǐ 与 shì 声调不同，意思是按权力去做。"}, "sentence_index": null, "correct_answer": "形势"}, "level_3": {"options": [{"text": "形势", "is_correct": true, "explanation": "形势：指战争的发展状况，与“每天都在变化”相符。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的性情特点，不能用于战争。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或物的重量，不能说“战争的体重”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或生物存在的时间，不能用于战争。"}], "explanations": {"形势": "形势：指战争的发展状况，与“每天都在变化”相符。", "性格": "语义：“性格”指人的性情特点，不能用于战争。", "体重": "搭配：“体重”指人或物的重量，不能说“战争的体重”。", "年龄": "语义：“年龄”指人或生物存在的时间，不能用于战争。"}, "sentence_index": 6, "correct_answer": "形势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书采用了新的排版形势。", "explanation": "这里应该用〈形式〉。形势指事物发展的状况，书籍的排版方式要用形式。"}, {"text": "这道菜的形势很好看。", "explanation": "这里应该用〈样子〉。形势指事物发展的状况，食物的外观要说样子。"}, {"text": "我们把形势放进了箱子。", "explanation": "形势是抽象的发展状况，不是有形的东西，不能“放进”箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid