INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条形势让大家有点着急。", "corrected_sentence": "这种形势让大家有点着急。", "error_description": "错误：这条形势。正确：这种形势。“条”用于细长的东西，形势是抽象名词，应用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
