INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89011, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "影子是光被挡住以后，地上出现的黑黑的样子。", "primary_collocate": null, "pronunciation": "yǐng zi", "ipa": "iŋ˨˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "阳光照在树上，地上有一片影子。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我站在路灯下，影子比我高很多。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "傍晚的时候，影子会变得很长。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲下来，看地上小鸟的影子。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯在我后面，影子在我前面。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在操场上互相踩对方的影子。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来了，墙上有了树的影子。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上月亮很亮，路上有我的影子。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手在墙上做出小狗的影子。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天没有太阳，就看不到影子。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "光被挡住后地面或墙上出现的黑色形状", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90443c19-7a61-476e-90a3-d5c5a7345015') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89011, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "影子", "is_correct": true, "explanation": "影子：yǐng（第三声）加 zi，光被挡住后地面或墙上出现的黑色形状。"}, {"text": "领子", "is_correct": false, "explanation": "lǐng（第三声）与 yǐng（第三声）只差声母（l 与 y），意思是衣领。"}, {"text": "引子", "is_correct": false, "explanation": "yǐn 与 yǐng 韵母不同（-n 与 -ng），声调相同，意思是引子（起头的引导）。"}, {"text": "银子", "is_correct": false, "explanation": "yín（第二声）与 yǐng（第三声）声调不同，韵母也有 -n 与 -ng 之差，意思是银钱。"}], "explanations": {"影子": "影子：yǐng（第三声）加 zi，光被挡住后地面或墙上出现的黑色形状。", "领子": "lǐng（第三声）与 yǐng（第三声）只差声母（l 与 y），意思是衣领。", "引子": "yǐn 与 yǐng 韵母不同（-n 与 -ng），声调相同，意思是引子（起头的引导）。", "银子": "yín（第二声）与 yǐng（第三声）声调不同，韵母也有 -n 与 -ng 之差，意思是银钱。"}, "sentence_index": null, "correct_answer": "影子"}, "level_3": {"options": [{"text": "影子", "is_correct": true, "explanation": "影子：阳光照在树上，地上出现的黑色形状。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：量词要用“阵”，不说“一片雨”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”是冷热的程度，不能铺在地上。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”是抽象概念，不能铺在地上。"}], "explanations": {"影子": "影子：阳光照在树上，地上出现的黑色形状。", "雨": "搭配：量词要用“阵”，不说“一片雨”。", "温度": "语义：“温度”是冷热的程度，不能铺在地上。", "时间": "语义：“时间”是抽象概念，不能铺在地上。"}, "sentence_index": 0, "correct_answer": "影子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤的影子很咸。", "explanation": "这里应该用〈味道〉。影子是光被挡住后地上的黑色样子，说汤咸不咸要用〈味道〉。"}, {"text": "这件衣服的影子很贵。", "explanation": "这里应该用〈价格〉。影子指光被挡住后地上的黑色样子，说东西值多少钱要用〈价格〉。"}, {"text": "这场比赛的影子只有一小时。", "explanation": "这里应该用〈时间〉。影子指光被挡住后地上的黑色样子，说一场比赛花了多久要用〈时间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89011, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "影子", "is_correct": true, "explanation": "影子：太阳出来后，墙上出现的树的黑色形状。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说轻重，不能投在墙上。"}, {"text": "年轮", "is_correct": false, "explanation": "语义：“年轮”是树干里的圈，不会映在墙上。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是人的温度，不会映在墙上。"}], "explanations": {"影子": "影子：太阳出来后，墙上出现的树的黑色形状。", "体重": "搭配：“体重”说轻重，不能投在墙上。", "年轮": "语义：“年轮”是树干里的圈，不会映在墙上。", "体温": "语义：“体温”是人的温度，不会映在墙上。"}, "sentence_index": 6, "correct_answer": "影子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的影子很好听。", "explanation": "这里应该用〈声音〉。影子不能用来形容好听不好听，说好听要用〈声音〉。"}, {"text": "这次事故对他的影子造成了很大的伤害。", "explanation": "这里应该用〈身体〉。影子指光被挡住后地上的黑色样子，受到伤害的是人的身体。"}, {"text": "这块面包的影子很甜。", "explanation": "这里应该用〈味道〉。影子是光被挡住后地上的黑色样子，说面包甜不甜要用〈味道〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地上有一棵影子。", "corrected_sentence": "地上有一片影子。", "error_description": "错误在量词。「影子」可用「片」或「个」计数，「棵」只用于树木等植物，不用于影子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下午，墙上地影子很大。", "corrected_sentence": "下午，墙上的影子很大。", "error_description": "错误在修饰语的助词。修饰名词“影子”要用“的”，说“墙上的影子”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
