INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体挡住光线后在地面或墙上形成的暗影。", "primary_collocate": null, "pronunciation": "yǐng zi", "ipa": "iŋ˨˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "太阳下山了，树的影子变得很长。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在灯下，墙上出现了一个大影子。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗一直跟着自己的影子玩。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午太阳很高，地上的影子特别短。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我走到哪里，我的影子就跟到哪里。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上的影子比中午的长。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，窗外有个影子在动。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的影子落在白墙上。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大树的影子下面很凉快。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云过来了，地上的影子一下子不见了。", "target_word": "影子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "道", "label": "量词"}], "register": "中性", "sense_fingerprint": "物体挡光后形成的暗影", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90443c19-7a61-476e-90a3-d5c5a7345015') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89012, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "影子", "is_correct": true, "explanation": "影子：yǐng（第三声）加 zi，指光被物体挡住后形成的暗影。"}, {"text": "领子", "is_correct": false, "explanation": "lǐng（第三声）与 yǐng（第三声）只差声母（l 与 y），意思是衣领。"}, {"text": "引子", "is_correct": false, "explanation": "yǐn 与 yǐng 韵母不同（-n 与 -ng），声调相同，意思是引子（起头的引导）。"}, {"text": "银子", "is_correct": false, "explanation": "yín（第二声）与 yǐng（第三声）声调不同，韵母也有 -n 与 -ng 之差，意思是银钱。"}], "explanations": {"影子": "影子：yǐng（第三声）加 zi，指光被物体挡住后形成的暗影。", "领子": "lǐng（第三声）与 yǐng（第三声）只差声母（l 与 y），意思是衣领。", "引子": "yǐn 与 yǐng 韵母不同（-n 与 -ng），声调相同，意思是引子（起头的引导）。", "银子": "yín（第二声）与 yǐng（第三声）声调不同，韵母也有 -n 与 -ng 之差，意思是银钱。"}, "sentence_index": null, "correct_answer": "影子"}, "level_3": {"options": [{"text": "影子", "is_correct": true, "explanation": "影子：太阳下山后，树在地上的暗影会变长。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”说高低，不说“变得很长”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”说深浅，不说长短。"}, {"text": "年轮", "is_correct": false, "explanation": "语义：“年轮”是数树龄的圈，不会变长。"}], "explanations": {"影子": "影子：太阳下山后，树在地上的暗影会变长。", "温度": "搭配：“温度”说高低，不说“变得很长”。", "颜色": "搭配：“颜色”说深浅，不说长短。", "年轮": "语义：“年轮”是数树龄的圈，不会变长。"}, "sentence_index": 0, "correct_answer": "影子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的影子很鲜艳。", "explanation": "这里应该用〈色彩〉。影子指光被挡住后的暗影或模糊形象，说颜色鲜艳要用〈色彩〉。"}, {"text": "这件事对他的影子很大。", "explanation": "这里应该用〈影响〉。影子指暗影或模糊形象，表示作用和效果要用〈影响〉。"}, {"text": "这项工作的影子已经完成了一半。", "explanation": "这里应该用〈进度〉。影子指光被挡住后的暗影或模糊形象，说工作完成到哪一步要用〈进度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "影子", "is_correct": true, "explanation": "影子：天黑后窗外有人影一样的暗影在动。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是存在的年数，不会在窗外动。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”说大小，不说在动。"}, {"text": "身份", "is_correct": false, "explanation": "语义：“身份”是抽象的资格，不能在窗外动。"}], "explanations": {"影子": "影子：天黑后窗外有人影一样的暗影在动。", "年龄": "语义：“年龄”是存在的年数，不会在窗外动。", "面积": "搭配：“面积”说大小，不说在动。", "身份": "语义：“身份”是抽象的资格，不能在窗外动。"}, "sentence_index": 6, "correct_answer": "影子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆花的影子很香。", "explanation": "这里应该用〈气味〉。影子是物体挡光后的暗影，说花的香味要用〈气味〉。"}, {"text": "这个孩子的影子已经十岁了。", "explanation": "这里应该用〈年龄〉。影子指光被挡住后的暗影或模糊形象，说人的岁数要用〈年龄〉。"}, {"text": "这碗面的影子很烫。", "explanation": "这里应该用〈温度〉。影子是物体挡光后的暗影，说食物的冷热要用〈温度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上有一棵影子在晃。", "corrected_sentence": "墙上有一个影子在晃。", "error_description": "错误在量词。「影子」用「个」计数，「棵」只用于树木等植物，不用于影子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵树地影子很长。", "corrected_sentence": "这棵树的影子很长。", "error_description": "错误在修饰语的助词。修饰名词“影子”要用“的”，说“树的影子”，不能用“地”（“地”用于修饰动词、形容词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2a2bbbe-96ec-42e7-b346-2c51b8318667') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
