INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89013, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "后日是明天的后一天。", "primary_collocate": null, "pronunciation": "hòu rì", "ipa": "xoʊ˥˩ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "今天是星期一，后日是星期三。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我后日要坐飞机去北京。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明日有雨，后日天会晴。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说后日带孩子去看电影。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天十号，后日就是十二号了。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明日是我的生日，后日是妹妹的生日。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们后日上午九点在学校门口见。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说后日考试，大家要早点复习。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天星期五，后日是星期天。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后日我请朋友来家里吃饭。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "後日", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "后日：明天的后一天，即后天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8acff1a7-15ec-4016-88fb-91db472ff9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89013, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后日", "is_correct": true, "explanation": "后日指明天的后一天。今天是星期一，后天正是星期三，与句意相合。"}, {"text": "明天", "is_correct": false, "explanation": "语义：今天是星期一，明天应是星期二，不能是星期三。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：昨天在今天之前，应是星期日，不能是星期三。"}, {"text": "今日", "is_correct": false, "explanation": "语义：“今日”与句中“今天”指同一天，即星期一，不能是星期三。"}], "explanations": {"后日": "后日指明天的后一天。今天是星期一，后天正是星期三，与句意相合。", "明天": "语义：今天是星期一，明天应是星期二，不能是星期三。", "昨天": "语义：昨天在今天之前，应是星期日，不能是星期三。", "今日": "语义：“今日”与句中“今天”指同一天，即星期一，不能是星期三。"}, "sentence_index": 0, "correct_answer": "后日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在小村庄住下，后日清晨出发去北京。", "explanation": "这里应该用〈次日〉。后日指以说话时为准的明天的后一天，不能用来指叙述中前面某个时间的第二天。"}, {"text": "他刚开始不喜欢汉语，后日很努力地学习。", "explanation": "这里应该用〈后来〉。后日是以说话时为准的明天的后一天，是具体的日期，不能表示叙述中先后发生的事。"}, {"text": "我后日已经看过这部电影了。", "explanation": "这里应该用〈前日〉。后日指明天的后一天，是将来的时间，不能和“已经……了”表示的过去的事一起用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后日", "is_correct": true, "explanation": "后日是具体的日子，可以作“见”的时间状语，与“上午九点在学校门口见”相合。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指过去，与约定未来见面的“见”不符。"}, {"text": "晚上", "is_correct": false, "explanation": "搭配：“晚上”与“上午九点”的时段冲突，不能同时修饰一个时间。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：“半夜”与“上午九点”的时间矛盾。"}], "explanations": {"后日": "后日是具体的日子，可以作“见”的时间状语，与“上午九点在学校门口见”相合。", "上周": "语义：“上周”指过去，与约定未来见面的“见”不符。", "晚上": "搭配：“晚上”与“上午九点”的时段冲突，不能同时修饰一个时间。", "半夜": "语义：“半夜”与“上午九点”的时间矛盾。"}, "sentence_index": 6, "correct_answer": "后日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "后日我每周末都要去图书馆。", "explanation": "这里应该用〈今后〉。今后泛指从现在起的将来，后日只指具体的一天，与“每周末”的反复时间相矛盾。"}, {"text": "后日我在家里睡了一整天。", "explanation": "这里应该用〈前日〉。后日指明天的后一天，还没有到，不能说已经发生的事。"}, {"text": "后日我们去公园玩得很开心。", "explanation": "这里应该用〈前日〉。后日还没有到，不能用“玩得很开心”叙述已经发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我后日下午两点去了医院。", "corrected_sentence": "我后日下午两点去医院。", "error_description": "错误：“后日”指将来，“去了”表示已经发生，二者冲突，应去掉“了”。正确：“我后日下午两点去医院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我后日的去上海开会。", "corrected_sentence": "我后日去上海开会。", "error_description": "错误：时间词“后日”后多加了结构助词“的”，“后日的去上海开会”成了没有中心语的名词性短语，不能作谓语。正确：“我后日去上海开会”，时间词直接作状语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89014, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
