INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89014, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "泛指以后的日子、将来，不指具体的某一天。", "primary_collocate": null, "pronunciation": "hòu rì", "ipa": "xoʊ˥˩ ɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "今日的努力，是为了后日的好生活。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后日如何，谁也说不准。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在多读书，后日才有好工作。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱存起来，留着后日用。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后日之事，今天不用多想。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愿你我后日再相见。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在就开始努力，为后日打好基础。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别只看眼前，后日的路还长着呢。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事先放一放，等后日再从长计议。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总想着后日的生活，却不肯努力。", "target_word": "后日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "後日", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "后日：泛指以后的日子、将来，不指具体某一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8acff1a7-15ec-4016-88fb-91db472ff9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后日", "is_correct": true, "explanation": "后日泛指以后的日子，与“今日的努力”相对，表示将来的好生活。"}, {"text": "昨日", "is_correct": false, "explanation": "语义：“昨日”指过去，而“为了……的好生活”指向将来的目标，两者矛盾。"}, {"text": "往日", "is_correct": false, "explanation": "语义：“往日”指从前的日子，不能作为努力的目标。"}, {"text": "当初", "is_correct": false, "explanation": "搭配：“为了”要接将来的目的，不能与指过去某时的“当初”搭配。"}], "explanations": {"后日": "后日泛指以后的日子，与“今日的努力”相对，表示将来的好生活。", "昨日": "语义：“昨日”指过去，而“为了……的好生活”指向将来的目标，两者矛盾。", "往日": "语义：“往日”指从前的日子，不能作为努力的目标。", "当初": "搭配：“为了”要接将来的目的，不能与指过去某时的“当初”搭配。"}, "sentence_index": 0, "correct_answer": "后日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们昨天离开家乡，后日就回到了北京。", "explanation": "这里应该用〈第二天〉。后日指以说话时为准的以后的日子，不能用来指叙述中前面某个时间之后的第二天。"}, {"text": "我怀念后日的快乐时光。", "explanation": "这里应该用〈往日〉。怀念针对过去，后日指将来的日子，两者矛盾。"}, {"text": "后日的事情，我还记得清楚。", "explanation": "这里应该用〈以前〉。记得针对过去的事，后日指将来，不能用来回忆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后日", "is_correct": true, "explanation": "后日泛指将来的日子，与“为……打好基础”的将来目的相合。"}, {"text": "后悔", "is_correct": false, "explanation": "语义：“后悔”是心理动词，不表示时间，不能作“为……打好基础”的对象。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”指情绪状态，不表示时间，填入后句子不通。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：“嫉妒”是心理动词，不能作“为……打好基础”的对象。"}], "explanations": {"后日": "后日泛指将来的日子，与“为……打好基础”的将来目的相合。", "后悔": "语义：“后悔”是心理动词，不表示时间，不能作“为……打好基础”的对象。", "冷静": "语义：“冷静”指情绪状态，不表示时间，填入后句子不通。", "嫉妒": "语义：“嫉妒”是心理动词，不能作“为……打好基础”的对象。"}, "sentence_index": 6, "correct_answer": "后日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我还记得后日的小院。", "explanation": "这里应该用〈昔日〉。记得针对过去的事情，后日指将来，两者矛盾。"}, {"text": "我总是回忆后日的快乐。", "explanation": "这里应该用〈昨天〉。回忆针对过去，后日指将来，不能作为回忆的对象。"}, {"text": "后日的老房子，我一直怀念。", "explanation": "这里应该用〈从前〉。怀念针对过去的事物，后日指将来，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "谁也不知道后日会发生了什么。", "corrected_sentence": "谁也不知道后日会发生什么。", "error_description": "错误：“会”表示将来，“发生了”表示已经发生，二者在“后日”的语境中矛盾，应去掉“了”。正确：“谁也不知道后日会发生什么”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该为后日的做准备。", "corrected_sentence": "我们应该为后日做准备。", "error_description": "错误：介词“为”后的时间词“后日”后多加了“的”，“为后日的做准备”不成句。正确：“为后日做准备”，“为……做准备”中间不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
