INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89015, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "彼此是你和我，两个人互相都一样。", "primary_collocate": null, "pronunciation": "bǐ cǐ", "ipa": "pi˨˩˦ tsʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们认识很久了，彼此都很了解。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩彼此看了一眼，都笑了。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间要彼此帮助。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和她彼此没有秘密。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子彼此不说话，谁也不看谁。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们彼此道别后，各自回家了。", "target_word": "彼此", "complexity_tier": "T3", "furigana": "wǒ men bǐ cǐ dào bié hòu gè zì huí jiā le", "sentence_source": "generated"}, {"text": "同学们彼此认识后，很快成了好朋友。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老夫妻彼此照顾了四十年。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们彼此的想法不一样。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们彼此握手，然后开始工作。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "你和我两个人互相都一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89ee32a3-3677-402a-8adc-801a9e813d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89015, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彼此", "is_correct": true, "explanation": "正确：彼此指双方互相，“彼此都很了解”说我们两人互相都了解对方。"}, {"text": "你们", "is_correct": false, "explanation": "语义：“你们”指听话的多人，与句首的“我们”指代冲突，句子变成在说别人。"}, {"text": "她", "is_correct": false, "explanation": "语义：“她”是单数第三人称，与复数的“我们”不一致，不能指双方互相。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“自己”是反身代词，指各人自身，不表示双方互相，不能概括“我们”两人的互相了解。"}], "explanations": {"彼此": "正确：彼此指双方互相，“彼此都很了解”说我们两人互相都了解对方。", "你们": "语义：“你们”指听话的多人，与句首的“我们”指代冲突，句子变成在说别人。", "她": "语义：“她”是单数第三人称，与复数的“我们”不一致，不能指双方互相。", "自己": "搭配：“自己”是反身代词，指各人自身，不表示双方互相，不能概括“我们”两人的互相了解。"}, "sentence_index": 0, "correct_answer": "彼此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明彼此很努力，每天都学到很晚。", "explanation": "这里把“彼此”当成了〈自己〉用，但它只能指双方互相，句中“小明”一人不能用“彼此”。应直接说“很努力”。"}, {"text": "我彼此送了他一份生日礼物。", "explanation": "这里把“彼此”当成了〈自己〉用，但它只表示双方互相做同一件事，“我”单方面送礼不能用“彼此”。应去掉“彼此”。"}, {"text": "这两本书彼此很贵，买一本就够了。", "explanation": "这里把“彼此”当成了〈各自〉用，但它只表示双方互相，不能描述两件物品各自的价格。应改为“这两本书都很贵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彼此", "is_correct": true, "explanation": "正确：彼此指双方互相，“同学们彼此认识后”说同学之间互相认识。"}, {"text": "他", "is_correct": false, "explanation": "语义：“他”是单数第三人称，与复数的“同学们”不一致，句子无法表示互相。"}, {"text": "你", "is_correct": false, "explanation": "搭配：“你”指听话的一人，与“同学们”这一复数主语不搭配。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指事物，不能指人，与“同学们”冲突。"}], "explanations": {"彼此": "正确：彼此指双方互相，“同学们彼此认识后”说同学之间互相认识。", "他": "语义：“他”是单数第三人称，与复数的“同学们”不一致，句子无法表示互相。", "你": "搭配：“你”指听话的一人，与“同学们”这一复数主语不搭配。", "它": "语义：“它”指事物，不能指人，与“同学们”冲突。"}, "sentence_index": 6, "correct_answer": "彼此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚会上他彼此玩得很开心。", "explanation": "这里把“彼此”当成了〈自己〉用，但它表示双方互相，“他”一人玩不能用“彼此”。应去掉“彼此”。"}, {"text": "他把钥匙还给了彼此。", "explanation": "这里应该用〈对方〉。彼此指双方互相，不能只表示“他”把钥匙还给一方。"}, {"text": "这个方案彼此都很好。", "explanation": "这里把“彼此”当成了〈各个〉用，但它只能指双方互相，不能用来评价“方案”这类单一对象。应直接说“这个方案很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个人很彼此熟悉。", "corrected_sentence": "这两个人彼此熟悉。", "error_description": "错误：“很”放在“彼此”前面，“很彼此”不成立。“彼此”是代词，不能被“很”修饰，应去掉“很”，写成“这两个人彼此熟悉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们几个人彼此彼此认识很久了。", "corrected_sentence": "我们几个人彼此认识很久了。", "error_description": "错误：“彼此”多写了一次，出现“彼此彼此”。“彼此”只需说一次，句中重复多余，应去掉其中一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
