INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89016, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，指双方；指对方和自己。", "primary_collocate": null, "pronunciation": "bǐ cǐ", "ipa": "pi˨˩˦ tsʰɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "两家公司彼此合作，都赚了钱。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们彼此尊重，从不吵架。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，同学之间应该彼此信任。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻之间要彼此理解。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个国家彼此友好，经常来往。", "target_word": "彼此", "complexity_tier": "T3", "furigana": "zhè liǎng ge guó jiā bǐ cǐ yǒu hǎo, jīng cháng lái wǎng", "sentence_source": "generated"}, {"text": "彼此的距离近了，话也多了。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，两队队员彼此问好。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住得很远，彼此很少见面。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们彼此都有责任，不能只怪对方。", "target_word": "彼此", "complexity_tier": "T3", "furigana": "wǒ men bǐ cǐ dōu yǒu zé rèn, bù néng zhǐ guài duì fāng", "sentence_source": "generated"}, {"text": "彼此不了解，就很难成为朋友。", "target_word": "彼此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指双方，指对方和自己", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89ee32a3-3677-402a-8adc-801a9e813d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彼此", "is_correct": true, "explanation": "正确：彼此指双方，“两家公司彼此合作”说两家公司互相合作。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”是单数第一人称，与复数的“两家公司”不一致，不能表示两家公司互相合作。"}, {"text": "她", "is_correct": false, "explanation": "语义：“她”是单数人称，与复数的“两家公司”不一致。"}, {"text": "它", "is_correct": false, "explanation": "配价：“合作”需要双方都能作为主体，“它”只指一个事物，无法与“两家公司”共同合作。"}], "explanations": {"彼此": "正确：彼此指双方，“两家公司彼此合作”说两家公司互相合作。", "我": "语义：“我”是单数第一人称，与复数的“两家公司”不一致，不能表示两家公司互相合作。", "她": "语义：“她”是单数人称，与复数的“两家公司”不一致。", "它": "配价：“合作”需要双方都能作为主体，“它”只指一个事物，无法与“两家公司”共同合作。"}, "sentence_index": 0, "correct_answer": "彼此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "张老师彼此很喜欢这个班。", "explanation": "这里把“彼此”当成了〈自己〉用，但它只能指双方互相，单一主语“张老师”不能用。应直接说“很喜欢这个班”。"}, {"text": "我彼此很想念家乡。", "explanation": "这里把“彼此”当成了〈自己〉用，但它需要“对方”参与，句中只有“我”一人，没有对方。应直接说“很想念家乡”。"}, {"text": "这两张桌子彼此很干净。", "explanation": "这里把“彼此”当成了〈各自〉用，但它只表示双方互相，不能描述两张桌子各自的干净程度。应改为“这两张桌子都很干净”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彼此", "is_correct": true, "explanation": "正确：彼此指双方互相，“比赛前，两队队员彼此问好”说两队队员互相问好。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”是单数第一人称，与复数的“两队队员”不一致，无法表示互相问好。"}, {"text": "你", "is_correct": false, "explanation": "搭配：“你”指听话的一人，与“两队队员”这一复数主语不搭配。"}, {"text": "他", "is_correct": false, "explanation": "语义：“他”是单数第三人称，与复数的“两队队员”不一致，句子不通。"}], "explanations": {"彼此": "正确：彼此指双方互相，“比赛前，两队队员彼此问好”说两队队员互相问好。", "我": "语义：“我”是单数第一人称，与复数的“两队队员”不一致，无法表示互相问好。", "你": "搭配：“你”指听话的一人，与“两队队员”这一复数主语不搭配。", "他": "语义：“他”是单数第三人称，与复数的“两队队员”不一致，句子不通。"}, "sentence_index": 6, "correct_answer": "彼此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全班彼此都考得很好。", "explanation": "这里的错误不在“彼此”指代的人数，而在“考得很好”不是相互行为：每人考多少分是各自的结果。应改为“全班都考得很好”。"}, {"text": "他把包裹寄给了彼此。", "explanation": "这里应该用〈对方〉。彼此指双方互相，不能只表示寄给一方。"}, {"text": "他把饭彼此吃完了。", "explanation": "这里把“彼此”当成了〈自己〉用，但它只表示双方互相，“他”一人吃饭不能用“彼此”。应去掉“彼此”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个小组很彼此配合。", "corrected_sentence": "这两个小组彼此配合。", "error_description": "错误：“很”放在“彼此”前面，“很彼此”不成立。“彼此”是代词，不能被“很”修饰，应去掉“很”，写成“这两个小组彼此配合”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夫妻俩彼此彼此关心，生活很幸福。", "corrected_sentence": "夫妻俩彼此关心，生活很幸福。", "error_description": "错误：“彼此”多写了一次，出现“彼此彼此”。“彼此”只需说一次，句中重复多余，应去掉其中一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
