INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89017, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "得了是说好了，或者同意了。", "primary_collocate": null, "pronunciation": "dé le", "ipa": "tɤ˧˥ lə", "syllable_count": 2, "sentences": [{"text": "得了，就这么办吧。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“明天八点见。”“得了，不见不散。”", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，你说怎么做，我就怎么做。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，这件事我同意了。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，我听你的，明天就去。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“我请客。”“得了，那我不客气了。”", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，你们定的时间我可以。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，那就这么定了。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着说：“得了，就按你说的做。”", "target_word": "得了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得了，明天我陪你一起去。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "得了得了", "label": "重叠"}], "register": "口语", "sense_fingerprint": "得了：叹词，表示说定了、同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6cbc5a-610d-4b16-8f18-ee2152c34c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89017, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "得了", "is_correct": true, "explanation": "得了：dé le，叹词，表示同意或说定。"}, {"text": "咳了", "is_correct": false, "explanation": "咳了（ké le）与得了（dé le）声母不同（k 与 d），声调相同，意思是咳嗽了。"}, {"text": "和了", "is_correct": false, "explanation": "和了（hé le）与得了（dé le）声母不同（h 与 d），声调相同，意思是麻将中胡了。"}, {"text": "答了", "is_correct": false, "explanation": "答了（dá le）与得了（dé le）声调相同，元音不同（a 与 e），意思是回答了。"}], "explanations": {"得了": "得了：dé le，叹词，表示同意或说定。", "咳了": "咳了（ké le）与得了（dé le）声母不同（k 与 d），声调相同，意思是咳嗽了。", "和了": "和了（hé le）与得了（dé le）声母不同（h 与 d），声调相同，意思是麻将中胡了。", "答了": "答了（dá le）与得了（dé le）声调相同，元音不同（a 与 e），意思是回答了。"}, "sentence_index": null, "correct_answer": "得了"}, "level_3": {"options": [{"text": "得了", "is_correct": true, "explanation": "叹词“得了”：表示同意、说定，与“就这么办吧”相合。"}, {"text": "嗟夫", "is_correct": false, "explanation": "语域：“嗟夫”是文言叹词，口语里不用。"}, {"text": "呜呼", "is_correct": false, "explanation": "语义：“呜呼”表示悲叹，与“就这么办吧”的决定语气不合。"}, {"text": "吁", "is_correct": false, "explanation": "语域：“吁”是文言叹词，多表示感叹或忧虑，不表示同意。"}], "explanations": {"得了": "叹词“得了”：表示同意、说定，与“就这么办吧”相合。", "嗟夫": "语域：“嗟夫”是文言叹词，口语里不用。", "呜呼": "语义：“呜呼”表示悲叹，与“就这么办吧”的决定语气不合。", "吁": "语域：“吁”是文言叹词，多表示感叹或忧虑，不表示同意。"}, "sentence_index": 0, "correct_answer": "得了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "得了，祝你新年快乐！", "explanation": "这里应该用〈好〉。“得了”表示同意或说定，不能用来送上新年祝福；可以说“好，祝你新年快乐！”。"}, {"text": "得了，天气太好了！", "explanation": "这里应该用〈哇〉。“得了”表示同意或说定，不表示对天气的赞叹。"}, {"text": "得了，请问厕所在哪儿？", "explanation": "这里应该用〈你好〉。“得了”表示同意或说定，不能用来开口向人询问地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89017, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "得了", "is_correct": true, "explanation": "得了：dé le，叹词，表示同意或说定。"}, {"text": "隔了", "is_correct": false, "explanation": "隔了（gé le）与得了（dé le）声母不同（g 与 d），声调相同，意思是隔开了。"}, {"text": "择了", "is_correct": false, "explanation": "择了（zé le）与得了（dé le）声母不同（z 与 d），声调相同，意思是选择了。"}, {"text": "答了", "is_correct": false, "explanation": "答了（dá le）与得了（dé le）韵母不同（a 与 e），声调相同，意思是回答了。"}], "explanations": {"得了": "得了：dé le，叹词，表示同意或说定。", "隔了": "隔了（gé le）与得了（dé le）声母不同（g 与 d），声调相同，意思是隔开了。", "择了": "择了（zé le）与得了（dé le）声母不同（z 与 d），声调相同，意思是选择了。", "答了": "答了（dá le）与得了（dé le）韵母不同（a 与 e），声调相同，意思是回答了。"}, "sentence_index": null, "correct_answer": "得了"}, "level_3": {"options": [{"text": "得了", "is_correct": true, "explanation": "叹词“得了”：表示同意，与“你们定的时间我可以”相合。"}, {"text": "咄", "is_correct": false, "explanation": "语义：“咄”表示斥责，与“我可以”的同意语气不合。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊讶或赞叹，与同意对方安排的语气不合。"}, {"text": "呸", "is_correct": false, "explanation": "语义：“呸”表示唾弃、鄙视，与同意的语气冲突。"}], "explanations": {"得了": "叹词“得了”：表示同意，与“你们定的时间我可以”相合。", "咄": "语义：“咄”表示斥责，与“我可以”的同意语气不合。", "哇": "语义：“哇”表示惊讶或赞叹，与同意对方安排的语气不合。", "呸": "语义：“呸”表示唾弃、鄙视，与同意的语气冲突。"}, "sentence_index": 6, "correct_answer": "得了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "得了，欢迎光临。", "explanation": "这里应该用〈你好〉。“得了”表示同意或作罢，不能用来招呼客人。"}, {"text": "得了，请问附近有银行吗？", "explanation": "这里应该用〈你好〉。“得了”表示同意或说定，不能用来开口向人询问地点。"}, {"text": "得了，好漂亮的花！", "explanation": "这里应该用〈哇〉。“得了”表示同意或作罢，不表示惊叹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EX