INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89018, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "表示制止或作罢，相当于「行了」「算了」。", "primary_collocate": null, "pronunciation": "dé le", "ipa": "tɤ˧˥ lə", "syllable_count": 2, "sentences": [{"text": "得了，别再说了，我不想听。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了得了，这件事就别提了。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，我自己去吧，不麻烦你了。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他还想说，我说：“得了，别说了。”", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，你别哭了，我给你买新的。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，今天太晚了，明天再做吧。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，别吵了，大家都累了。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，不去就不去，没什么大不了。", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得了，算我错了，行不行？", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说：“得了，别看手机了，快睡觉。”", "target_word": "得了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "得了得了", "label": "重叠"}], "register": "口语", "sense_fingerprint": "得了：叹词，制止或作罢，相当于算了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6cbc5a-610d-4b16-8f18-ee2152c34c49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89018, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "得了", "is_correct": true, "explanation": "得了：dé le，叹词，表示制止或作罢。"}, {"text": "咳了", "is_correct": false, "explanation": "咳了（ké le）与得了（dé le）声母不同（k 与 d），声调相同，意思是咳嗽了。"}, {"text": "和了", "is_correct": false, "explanation": "和了（hé le）与得了（dé le）声母不同（h 与 d），声调相同，意思是麻将中胡了。"}, {"text": "答了", "is_correct": false, "explanation": "答了（dá le）与得了（dé le）声调相同，元音不同（a 与 e），意思是回答了。"}], "explanations": {"得了": "得了：dé le，叹词，表示制止或作罢。", "咳了": "咳了（ké le）与得了（dé le）声母不同（k 与 d），声调相同，意思是咳嗽了。", "和了": "和了（hé le）与得了（dé le）声母不同（h 与 d），声调相同，意思是麻将中胡了。", "答了": "答了（dá le）与得了（dé le）声调相同，元音不同（a 与 e），意思是回答了。"}, "sentence_index": null, "correct_answer": "得了"}, "level_3": {"options": [{"text": "得了", "is_correct": true, "explanation": "叹词“得了”：制止或作罢，与“别再说了，我不想听”相合。"}, {"text": "嗟夫", "is_correct": false, "explanation": "语域：“嗟夫”是文言叹词，口语句子里不用。"}, {"text": "呜呼", "is_correct": false, "explanation": "语义：“呜呼”表示悲叹，不能用来制止别人说话。"}, {"text": "哈哈", "is_correct": false, "explanation": "语义：“哈哈”表示笑声，不能用来制止别人说话。"}], "explanations": {"得了": "叹词“得了”：制止或作罢，与“别再说了，我不想听”相合。", "嗟夫": "语域：“嗟夫”是文言叹词，口语句子里不用。", "呜呼": "语义：“呜呼”表示悲叹，不能用来制止别人说话。", "哈哈": "语义：“哈哈”表示笑声，不能用来制止别人说话。"}, "sentence_index": 0, "correct_answer": "得了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "得了，生日快乐！", "explanation": "这里应该用〈哇〉。“得了”表示制止或作罢，不能用于祝贺生日。"}, {"text": "得了，你几岁了？", "explanation": "这里应该用〈请问〉。“得了”不能用来向人询问年龄，礼貌地提问要用〈请问〉之类的说法。"}, {"text": "得了，我们终于赢了！", "explanation": "这里应该用〈太好了〉。“得了”只表示制止或作罢，不表示高兴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89018, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "得了", "is_correct": true, "explanation": "得了：dé le，叹词，表示制止或作罢。"}, {"text": "隔了", "is_correct": false, "explanation": "隔了（gé le）与得了（dé le）声母不同（g 与 d），声调相同，意思是隔开了。"}, {"text": "择了", "is_correct": false, "explanation": "择了（zé le）与得了（dé le）声母不同（z 与 d），声调相同，意思是选择了。"}, {"text": "答了", "is_correct": false, "explanation": "答了（dá le）与得了（dé le）韵母不同（a 与 e），声调相同，意思是回答了。"}], "explanations": {"得了": "得了：dé le，叹词，表示制止或作罢。", "隔了": "隔了（gé le）与得了（dé le）声母不同（g 与 d），声调相同，意思是隔开了。", "择了": "择了（zé le）与得了（dé le）声母不同（z 与 d），声调相同，意思是选择了。", "答了": "答了（dá le）与得了（dé le）韵母不同（a 与 e），声调相同，意思是回答了。"}, "sentence_index": null, "correct_answer": "得了"}, "level_3": {"options": [{"text": "得了", "is_correct": true, "explanation": "叹词“得了”：制止或作罢，与“别吵了，大家都累了”相合。"}, {"text": "吁", "is_correct": false, "explanation": "语域：“吁”是文言叹词，口语句子里不用。"}, {"text": "喏", "is_correct": false, "explanation": "语义：“喏”是恭敬地应答，不能用来制止吵闹。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊讶或赞叹，与“别吵了”的制止语气不合。"}], "explanations": {"得了": "叹词“得了”：制止或作罢，与“别吵了，大家都累了”相合。", "吁": "语域：“吁”是文言叹词，口语句子里不用。", "喏": "语义：“喏”是恭敬地应答，不能用来制止吵闹。", "哇": "语义：“哇”表示惊讶或赞叹，与“别吵了”的制止语气不合。"}, "sentence_index": 6, "correct_answer": "得了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "得了，早上好！", "explanation": "这里应该用〈嗨〉。“得了”表示制止或作罢，不能用来问候。"}, {"text": "得了，欢迎光临。", "explanation": "这里应该用〈你好〉。“得了”不能用来打招呼或迎接客人。"}, {"text": "得了，我肚子好饿！", "explanation": "这里应该用〈哎呀〉。“得了”表示制止或作罢，不能用来表达饥饿的感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '814cd610-e067-4526-a96f-e9e827cea73f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation