INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89019, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房屋是人住的屋子、楼房。", "primary_collocate": null, "pronunciation": "fáng wū", "ipa": "fɑŋ˧˥ u˥", "syllable_count": 2, "sentences": [{"text": "这栋房屋有三层，住着五家人。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把旧房屋卖了，搬进了新家。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房屋前面有一个小花园。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的房屋又高又漂亮。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想租一套便宜的房屋。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在这座房屋里住了五十年。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房屋里的灯一直亮着。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有几处白色的房屋。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房屋太小，放不下这张大床。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你看看这些房屋的照片。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "栋", "label": "量词"}, {"form": "房屋中介", "label": "复合"}], "register": "通用", "sense_fingerprint": "人居住的屋子或楼房", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb360e55-9684-4dc5-bf88-9814d0ac9a26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89019, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：河流是天然水道，不会有三层，也不住人。"}, {"text": "房屋", "is_correct": true, "explanation": "正确：房屋是供人住的楼房，可以有三层，并住着五家人。"}, {"text": "田野", "is_correct": false, "explanation": "语义：田野是耕地或草地，不能有“三层”，也不住人家。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：“住着五家人”需要居所作主语，“公司”不能住家。"}], "explanations": {"河流": "语义：河流是天然水道，不会有三层，也不住人。", "房屋": "正确：房屋是供人住的楼房，可以有三层，并住着五家人。", "田野": "语义：田野是耕地或草地，不能有“三层”，也不住人家。", "公司": "搭配：“住着五家人”需要居所作主语，“公司”不能住家。"}, "sentence_index": 0, "correct_answer": "房屋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在路上看见一辆房屋。", "explanation": "这里应该用〈栋〉。“辆”用于车辆，房屋要用“栋”，不能用“辆”来数。"}, {"text": "这块房屋去年种满了玉米。", "explanation": "这里应该用〈田地〉。房屋指人住的屋子或楼房，不指耕地。"}, {"text": "他把房屋放进了冰箱里。", "explanation": "这里应该用〈食物〉。房屋是人住的建筑，不能放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89019, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文字", "is_correct": false, "explanation": "语义：“房屋里”指可以住人的空间，文字不是空间，句意不通。"}, {"text": "房屋", "is_correct": true, "explanation": "正确：房屋是可以住人的空间，里面可以有灯亮着。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字不是空间，不能说数字里有灯亮着。"}, {"text": "合同", "is_correct": false, "explanation": "搭配：“里”与“灯亮着”搭配的是空间或场所，合同不能说有灯。"}], "explanations": {"文字": "语义：“房屋里”指可以住人的空间，文字不是空间，句意不通。", "房屋": "正确：房屋是可以住人的空间，里面可以有灯亮着。", "数字": "语义：数字不是空间，不能说数字里有灯亮着。", "合同": "搭配：“里”与“灯亮着”搭配的是空间或场所，合同不能说有灯。"}, "sentence_index": 6, "correct_answer": "房屋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从口袋里掏出房屋。", "explanation": "这里应该用〈钥匙〉。“掏出”的东西须能装进口袋，房屋放不进口袋。"}, {"text": "他背着房屋去上学。", "explanation": "这里应该用〈书包〉。“背”的对象是可以背在身上的物品，房屋不能背着走。"}, {"text": "他穿上房屋，出门去了。", "explanation": "这里应该用〈衣服〉。“穿”的对象是衣物，房屋不能穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们搬进了那本新房屋。", "corrected_sentence": "他们搬进了那栋新房屋。", "error_description": "量词错误：房屋应用量词“栋”，“本”用于书册，不能用来数房屋，应说“那栋新房屋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把那本房屋卖给了朋友。", "corrected_sentence": "他们把那栋房屋卖给了朋友。", "error_description": "量词错误：房屋应用量词“栋”，“本”用于书册，不能用来数房屋，应说“那栋房屋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
