INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89020, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人居住或做其他用途的建筑物。", "primary_collocate": null, "pronunciation": "fáng wū", "ipa": "fɑŋ˧˥ u˥", "syllable_count": 2, "sentences": [{"text": "这座城市的房屋大多是新建的。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山脚下买了一所旧房屋。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，很多房屋都进了水。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这排房屋以前是工厂的仓库。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房屋的墙上爬满了绿色的植物。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的房屋都有红色的屋顶。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，不少房屋都倒了。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要在这里新建一千套房屋。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠出租房屋过日子。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房屋的门前种着几棵树。", "target_word": "房屋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "栋", "label": "量词"}, {"form": "房屋中介", "label": "复合"}], "register": "通用", "sense_fingerprint": "供居住或其他用途的建筑物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb360e55-9684-4dc5-bf88-9814d0ac9a26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "田野", "is_correct": false, "explanation": "语义：田野是耕地或草地，不是可以新建的建筑，句中“这座城市的……大多是新建的”不成立。"}, {"text": "房屋", "is_correct": true, "explanation": "正确：房屋是供人居住或做其他用途的建筑物，可以新建，与“大多是新建的”相合。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”说数量与增减，不能说“新建”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是天然形成的水道，不是人可以新建的东西。"}], "explanations": {"田野": "语义：田野是耕地或草地，不是可以新建的建筑，句中“这座城市的……大多是新建的”不成立。", "房屋": "正确：房屋是供人居住或做其他用途的建筑物，可以新建，与“大多是新建的”相合。", "人口": "搭配：“人口”说数量与增减，不能说“新建”。", "河流": "语义：河流是天然形成的水道，不是人可以新建的东西。"}, "sentence_index": 0, "correct_answer": "房屋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把房屋装进箱子里寄走了。", "explanation": "这里应该用〈礼物〉。房屋是建筑物，不能装进箱子寄走。"}, {"text": "这块房屋今年种满了玉米。", "explanation": "这里应该用〈田地〉。房屋指供人居住或做其他用途的建筑物，不能指耕种的土地。"}, {"text": "他轻轻推开了房屋。", "explanation": "这里应该用〈门〉。房屋指整座建筑，不能被“推开”，“推开”的对象应是门或窗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文字", "is_correct": false, "explanation": "语义：文字不会倒塌，“倒了”的主语须是能倒塌的东西。"}, {"text": "数据", "is_correct": false, "explanation": "语义：数据是信息，不会因地震而倒。"}, {"text": "房屋", "is_correct": true, "explanation": "正确：房屋可以因地震倒塌，与“地震后……都倒了”相合。"}, {"text": "合同", "is_correct": false, "explanation": "搭配：“倒”说有形物体塌落，合同只能说失效或作废，不能说“倒了”。"}], "explanations": {"文字": "语义：文字不会倒塌，“倒了”的主语须是能倒塌的东西。", "数据": "语义：数据是信息，不会因地震而倒。", "房屋": "正确：房屋可以因地震倒塌，与“地震后……都倒了”相合。", "合同": "搭配：“倒”说有形物体塌落，合同只能说失效或作废，不能说“倒了”。"}, "sentence_index": 6, "correct_answer": "房屋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上穿上房屋去上班。", "explanation": "这里应该用〈衣服〉。“穿”的对象是衣物，房屋不能穿在身上。"}, {"text": "他从口袋里掏出房屋。", "explanation": "这里应该用〈钥匙〉。“掏出”的东西须能装进口袋，房屋放不进口袋。"}, {"text": "他背着房屋去上学。", "explanation": "这里应该用〈书包〉。“背”的对象是可以背在身上的物品，房屋不能背着走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cd4d5f-2df6-4311-8850-97bc359d2bca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
