INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89022, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "政党、团体各级组织中的主要负责人。", "primary_collocate": null, "pronunciation": "shū jì", "ipa": "ʂu˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "村里的书记今天来看望老人。", "target_word": "书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书记在大会上讲了话。", "target_word": "书记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当了二十年书记。", "target_word": "书记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的书记很关心农民的生活。", "target_word": "书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书记要求大家认真学习文件。", "target_word": "书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的书记明天去北京开会。", "target_word": "书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位书记经常到村民家里走访。", "target_word": "书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司党委的书记向大家介绍了计划。", "target_word": "书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书记说，工作要为人民服务。", "target_word": "书记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都很尊敬这位老书记。", "target_word": "书记", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "書記", "label": "繁体"}, {"form": "总书记", "label": "复合"}], "register": "正式", "sense_fingerprint": "党组织或团体的主要负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '216324cd-0d1f-4db4-b00d-b0895e448e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89022, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "书契", "is_correct": false, "explanation": "shū qì（书契）与 shū jì 仅声母不同（q 与 j），意思是古代的文书或契约。"}, {"text": "熟记", "is_correct": false, "explanation": "shú（第二声）与 shū（第一声）声调不同，意思是熟记、牢记。"}, {"text": "书记", "is_correct": true, "explanation": "正确答案：书记（shū jì），指党组织或团体的主要负责人。"}, {"text": "书籍", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是书籍。"}], "explanations": {"书契": "shū qì（书契）与 shū jì 仅声母不同（q 与 j），意思是古代的文书或契约。", "熟记": "shú（第二声）与 shū（第一声）声调不同，意思是熟记、牢记。", "书记": "正确答案：书记（shū jì），指党组织或团体的主要负责人。", "书籍": "jí（第二声）与 jì（第四声）声调不同，意思是书籍。"}, "sentence_index": null, "correct_answer": "书记"}, "level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "配价：“来看望”要求有生命的施事，“石头”不能来看望老人。"}, {"text": "书记", "is_correct": true, "explanation": "正确：书记是人，能够来看望老人，符合语境。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是人，不能来看望老人，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是人，不能来看望老人，句意不通。"}], "explanations": {"石头": "配价：“来看望”要求有生命的施事，“石头”不能来看望老人。", "书记": "正确：书记是人，能够来看望老人，符合语境。", "电脑": "语义：电脑不是人，不能来看望老人，句意不通。", "桌子": "语义：桌子不是人，不能来看望老人，句意不通。"}, "sentence_index": 0, "correct_answer": "书记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "邮局的书记正在挨家挨户送信。", "explanation": "这里应该用〈邮递员〉。书记指党组织或团体的主要负责人，不指送信的人。"}, {"text": "村口的书记正在剪头发。", "explanation": "这里应该用〈理发师〉。书记指党政团体的主要负责人，不指给人剪头发的人。"}, {"text": "食堂里的书记每天做三顿饭。", "explanation": "这里应该用〈厨师〉。书记不指做饭的人，那是厨师的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89022, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "书肆", "is_correct": false, "explanation": "sì 与 jì 声母不同（s 与 j），书肆指旧时的书店。"}, {"text": "熟记", "is_correct": false, "explanation": "shú（第二声）与 shū（第一声）声调不同，意思是熟记、牢记。"}, {"text": "书记", "is_correct": true, "explanation": "正确答案：书记（shū jì），指党组织或团体的主要负责人。"}, {"text": "舒适", "is_correct": false, "explanation": "shì 与 jì 声母不同（sh 与 j），意思是舒服、适宜。"}], "explanations": {"书肆": "sì 与 jì 声母不同（s 与 j），书肆指旧时的书店。", "熟记": "shú（第二声）与 shū（第一声）声调不同，意思是熟记、牢记。", "书记": "正确答案：书记（shū jì），指党组织或团体的主要负责人。", "舒适": "shì 与 jì 声母不同（sh 与 j），意思是舒服、适宜。"}, "sentence_index": null, "correct_answer": "书记"}, "level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人，不会经常到村民家里走访，句意不通。"}, {"text": "书记", "is_correct": true, "explanation": "正确：书记是人，能够经常到村民家里走访，符合语境。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是人，不会经常到村民家里走访。"}, {"text": "河流", "is_correct": false, "explanation": "配价：“走访”要求有生命的施事，“河流”不能走访村民。"}], "explanations": {"窗户": "语义：窗户不是人，不会经常到村民家里走访，句意不通。", "书记": "正确：书记是人，能够经常到村民家里走访，符合语境。", "汽车": "语义：汽车不是人，不会经常到村民家里走访。", "河流": "配价：“走访”要求有生命的施事，“河流”不能走访村民。"}, "sentence_index": 6, "correct_answer": "书记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公交车上的书记正在开车。", "explanation": "这里应该用〈司机〉。书记指负责人，不指驾驶车辆的人。"}, {"text": "病房里的书记正在打针。", "explanation": "这里应该用〈护士〉。书记不指给病人打针的人。"}, {"text": "景区的书记正在讲解历史。", "explanation": "这里应该用〈导游〉。书记指党政团体的主要负责人，不指讲解景点的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厂里新调来了一只书记。", "corrected_sentence": "厂里新调来了一位书记。", "error_description": "量词错误：“书记”指人，应用“位”或“名”，不能用“只”。正确应说“一位书记”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经过村里的书记。", "corrected_sentence": "他曾经当过村里的书记。", "error_description": "漏字：「当过」中的动词「当」不能省，应说“曾经当过村里的书记”；去掉“当”后，“过”无所附着，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
