INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89024, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "族是有共同语言和习俗的人群，即民族。", "primary_collocate": null, "pronunciation": "zú", "ipa": "tsu˧˥", "syllable_count": 1, "sentences": [{"text": "这个族爱唱歌，也爱跳舞。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们那个族在山里住了很多年。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们族有自己的语言和节日。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他妈妈是我们族的人。", "target_word": "族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个族的人过节都穿红色的衣服。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是哪个族的人？", "target_word": "族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们族过年的时候，大家一起跳舞。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个族不大，只有几千人。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "族里有自己的老师教孩子说话。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们族住在南方的大山里。", "target_word": "族", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "民族", "label": "复合"}], "register": "中性", "sense_fingerprint": "民族（有共同语言和习俗的群体）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b64ca331-cee2-4a4d-bcc5-b9b5a93b48c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
