INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只族的人大多会两种语言。", "corrected_sentence": "这个族的人大多会两种语言。", "error_description": "“族”作群体名词，量词应用“个”，不能用“只”。错误在“这只”，应为“这个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个族有几千个人们。", "corrected_sentence": "这个族有几千人。", "error_description": "数量词后面的“人”不能加“们”。应为“几千人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
