INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89025, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89025, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "民众是很多普通的人,就是老百姓。", "primary_collocate": null, "pronunciation": "mín zhòng", "ipa": "min˧˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "政府听取了民众的意见。", "target_word": "民众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多民众在广场上等着看表演。", "target_word": "民众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息让民众很高兴。", "target_word": "民众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民众都希望生活越来越好。", "target_word": "民众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长走到民众中间，和大家说话。", "target_word": "民众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨的时候，民众可以去地铁站里休息。", "target_word": "民众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的公园对民众开放了。", "target_word": "民众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察告诉民众不要走这条路。", "target_word": "民众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民众对新的规定很满意。", "target_word": "民众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给民众讲了很多健康知识。", "target_word": "民众", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "民眾", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "民众：普通百姓这个群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6572065d-d0c8-4f83-baf4-ecb8a6676503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89025, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民众", "is_correct": true, "explanation": "民众：指普通百姓这一群体，与“政府”相对，是“听取意见”的对象。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不能发表意见，“听取……的意见”不能用于动物。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有意见可以听取。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”不能作为能提出意见的主体，与“听取……的意见”搭配不当。"}], "explanations": {"民众": "民众：指普通百姓这一群体，与“政府”相对，是“听取意见”的对象。", "动物": "语义：动物不能发表意见，“听取……的意见”不能用于动物。", "石头": "语义：石头没有意见可以听取。", "天空": "搭配：“天空”不能作为能提出意见的主体，与“听取……的意见”搭配不当。"}, "sentence_index": 0, "correct_answer": "民众"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "街上走来了一只民众。", "explanation": "这里不能用〈只〉作量词。民众是集体名词，指一群普通百姓，不能用“只”计数，应说“一群民众”。"}, {"text": "公司的民众都很努力工作。", "explanation": "这里应该用〈员工〉。民众指普通百姓，不指某单位的工作人员。"}, {"text": "老板是我们的民众。", "explanation": "这里应该用〈领导〉。民众指普通百姓，不指企业或单位里有职务的人，说这类人要用“领导”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民众", "is_correct": true, "explanation": "民众：指普通百姓，是“对……开放”的对象，与“新的公园”相对应。"}, {"text": "树木", "is_correct": false, "explanation": "语义：公园不会对树木开放，“对……开放”的对象应是人群。"}, {"text": "墙壁", "is_correct": false, "explanation": "搭配：“对……开放”一般搭配人群或场所，不搭配墙壁。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能作为公园开放的对象，此句语义不通。"}], "explanations": {"民众": "民众：指普通百姓，是“对……开放”的对象，与“新的公园”相对应。", "树木": "语义：公园不会对树木开放，“对……开放”的对象应是人群。", "墙壁": "搭配：“对……开放”一般搭配人群或场所，不搭配墙壁。", "电脑": "语义：电脑不能作为公园开放的对象，此句语义不通。"}, "sentence_index": 6, "correct_answer": "民众"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是班里的民众。", "explanation": "这里应该用〈同学〉。民众指普通百姓，不指班级里的学生，说班里的人要用“同学”。"}, {"text": "我们学校的民众都很努力学习。", "explanation": "这里应该用〈学生〉。民众指普通百姓，不指学校里的学生。"}, {"text": "这所大学聘请了一位民众教授。", "explanation": "这里应该用〈专家〉。民众指普通百姓，不能修饰“教授”这类职称；聘请的人员要说“专家”或直接说“教授”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项措施给一条民众带来了很多方便。", "corrected_sentence": "这项措施给民众带来了很多方便。", "error_description": "错误：“民众”是集体名词，不能用“条”这样的个体量词，“一条民众”不通。正确：直接说“给民众带来了很多方便”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座公园对一只民众免费开放了。", "corrected_sentence": "这座公园对民众免费开放了。", "error_description": "错误：“民众”是集体名词，不能用“只”计数，“一只民众”不通；应直接说“对民众免费开放”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5832db7a-7430-4448-94f4-64c816ee246e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
