INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89027, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "日期是哪一年哪一月哪一天。", "primary_collocate": null, "pronunciation": "rì qī", "ipa": "ɻ̩˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "请在这里写上你的出生日期。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是几号？我忘了日期。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张票上的日期是三月五号。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把朋友的结婚日期记在本子上了。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶盒上有日期，你先看看。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信的右上角写着日期。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写错了日期，所以要重写。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在表格的右下角写上日期。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上能看到今天的日期。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日历上这个日期画了一个红圈。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "出生日期", "label": "复合"}, {"form": "生产日期", "label": "复合"}], "register": "中性", "sense_fingerprint": "某年某月某日的年月日写法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223a2931-5429-4f73-9c3e-06403fa309c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89027, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“出生”后面不能接“颜色”，说“出生颜色”不通，表格里也不填这一项。"}, {"text": "日期", "is_correct": true, "explanation": "正确：“出生日期”指出生的年月日，填表时要求写的正是这个词，符合句意。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不是出生时的信息，“出生学校”说不通，句意不成立。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“出生”后不能接表示人的性格的词，“出生性格”说不通。"}], "explanations": {"颜色": "搭配：“出生”后面不能接“颜色”，说“出生颜色”不通，表格里也不填这一项。", "日期": "正确：“出生日期”指出生的年月日，填表时要求写的正是这个词，符合句意。", "学校": "语义：学校不是出生时的信息，“出生学校”说不通，句意不成立。", "性格": "语义：“出生”后不能接表示人的性格的词，“出生性格”说不通。"}, "sentence_index": 0, "correct_answer": "日期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了准备这次活动，我们用了很长的日期。", "explanation": "这里应该用〈时间〉。日期指某一天，不能表示一段时长，说“用了很长的时间”才对。"}, {"text": "会议的日期定在下午三点。", "explanation": "这里应该用〈时刻〉。日期只指年、月、日，说具体的钟点要用“时刻”或“时间”。"}, {"text": "我记住了这张日期。", "explanation": "量词不当：日期是抽象的，应说“这个日期”，不说“这张日期”；“张”多用于纸、票等平面的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脚步", "is_correct": false, "explanation": "搭配：“写”能接文字、数字，不能接“脚步”，说“写错了脚步”不通。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“写错了”的对象是文字或数字，早饭不能被写错，句意不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不是可以书写的内容，“写错了大海”不成立。"}, {"text": "日期", "is_correct": true, "explanation": "正确：“写错了日期”指写错了年月日，符合句意，所以要重写。"}], "explanations": {"脚步": "搭配：“写”能接文字、数字，不能接“脚步”，说“写错了脚步”不通。", "早饭": "语义：“写错了”的对象是文字或数字，早饭不能被写错，句意不通。", "大海": "语义：大海不是可以书写的内容，“写错了大海”不成立。", "日期": "正确：“写错了日期”指写错了年月日，符合句意，所以要重写。"}, "sentence_index": 6, "correct_answer": "日期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校的日期就在市中心。", "explanation": "用法错误：日期表示时间，不能表示地点。说学校的位置要用“位置”或“地址”，不说“日期”。"}, {"text": "我把日期放进了冰箱。", "explanation": "用法错误：日期是抽象的时间，不是实物，不能放进冰箱。"}, {"text": "这份日期很厚，我看不完。", "explanation": "搭配错误：“厚”形容纸张或书本的厚度，日期不是实物，不能说很厚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议通知上的这张日期是下周一。", "corrected_sentence": "会议通知上的这个日期是下周一。", "error_description": "量词错误：“日期”是抽象的时间概念，应说“这个日期”；“这张日期”中的“张”用于纸张、票据等有平面的东西，不能用来修饰日期。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这个日期对写了。", "corrected_sentence": "他把这个日期写对了。", "error_description": "补语位置错误：结果补语“对”应紧跟动词“写”，说“写对了”；“对写了”的语序不对，母语者会立刻察觉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
