INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89028, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "发生某事的具体日子。", "primary_collocate": null, "pronunciation": "rì qī", "ipa": "ɻ̩˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "考试的日期定在六月十号。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议的日期改了，大家别忘了。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们还没有决定旅行的日期。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼的日期是明年五月二号。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我你们见面的日期。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司已经公布了比赛的日期。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说演出的日期下周才定。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事发生的日期，我记不清了。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车票上有出发日期，别弄错。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家的日期快到了，我们得打包行李。", "target_word": "日期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "出生日期", "label": "复合"}, {"form": "生产日期", "label": "复合"}], "register": "中性", "sense_fingerprint": "某件事发生或安排的具体日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223a2931-5429-4f73-9c3e-06403fa309c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地点", "is_correct": false, "explanation": "语义：“六月十号”是时间，地点不能被定在某个日子上，句意不通。"}, {"text": "日期", "is_correct": true, "explanation": "正确：“考试的日期”指考试具体的日子，“定在六月十号”说的正是时间，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能被定在某一天，“考试的颜色定在六月十号”说不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是可以定在某一天的事项，“课本定在六月十号”说不通。"}], "explanations": {"地点": "语义：“六月十号”是时间，地点不能被定在某个日子上，句意不通。", "日期": "正确：“考试的日期”指考试具体的日子，“定在六月十号”说的正是时间，符合句意。", "颜色": "语义：颜色不能被定在某一天，“考试的颜色定在六月十号”说不通。", "课本": "语义：课本不是可以定在某一天的事项，“课本定在六月十号”说不通。"}, "sentence_index": 0, "correct_answer": "日期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了这场婚礼，他们用了很长的日期来准备。", "explanation": "这里应该用〈时间〉。日期指某一天，不能表示一段时长，应说“用了很长的时间”。"}, {"text": "婚礼的日期从上午十点开始。", "explanation": "这里应该用〈时刻〉。日期只表示哪一天，“从上午十点开始”说的是钟点，应说“时刻”或“时间”。"}, {"text": "我们定下了一场日期。", "explanation": "量词不当：日期是抽象的，应说“一个日期”；“场”用于比赛、演出等活动，不用于日期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气由自然决定，不能由人“定”在下周，句意不通。"}, {"text": "日期", "is_correct": true, "explanation": "正确：“演出的日期下周才定”指演出的具体日子要到下周才确定，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“定”不能接“味道”，说“味道下周才定”不通。"}, {"text": "体重", "is_correct": false, "explanation": "配价：“定”要求能被确定的事项作宾语，“体重”不能被定在某个时间，句意不通。"}], "explanations": {"天气": "语义：天气由自然决定，不能由人“定”在下周，句意不通。", "日期": "正确：“演出的日期下周才定”指演出的具体日子要到下周才确定，符合句意。", "味道": "搭配：“定”不能接“味道”，说“味道下周才定”不通。", "体重": "配价：“定”要求能被确定的事项作宾语，“体重”不能被定在某个时间，句意不通。"}, "sentence_index": 6, "correct_answer": "日期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的日期在二楼。", "explanation": "用法错误：日期表示时间，不能表示地点。说房子的位置要用“在”加地点，如“我家在二楼”。"}, {"text": "我们在日期里吃了午饭。", "explanation": "用法错误：日期表示哪一天，不是地点，不能说“在日期里”吃饭。"}, {"text": "这个日期很重，我搬不动。", "explanation": "搭配错误：“重”形容实物的分量，日期是抽象的时间，不能说很重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们还没定下比赛的这场日期。", "corrected_sentence": "我们还没定下比赛的这个日期。", "error_description": "量词错误：“日期”应搭配“个”，说“这个日期”；“场”只用于比赛、演出等活动，不能修饰日期。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把比赛的日期下定来了。", "corrected_sentence": "我们把比赛的日期定下来了。", "error_description": "补语位置错误：趋向补语“下来”应紧跟动词“定”，说“定下来”；“下定来”的语序不对，母语者会立刻察觉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '744ef770-c5f3-45a1-93c2-be34872e7cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
