INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89031, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "星是晚上在天上一闪一闪的小亮点。", "primary_collocate": null, "pronunciation": "xīng", "ipa": "ɕiŋ⁵⁵", "syllable_count": 1, "sentences": [{"text": "晚上天上有很多星。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚没有月亮，只有几颗星。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星在天上一闪一闪的，真好看。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子躺在草地上，数着天上的星。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，天上看不见星。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪一颗星最亮？", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在院子里，看天上的星。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上没有灯，夜里的星特别亮。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，星一颗一颗出来了。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对着天上最亮的那颗星许了个愿。", "target_word": "星", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一颗星", "label": "量词"}, {"form": "星星", "label": "重叠"}, {"form": "星空", "label": "复合"}], "register": "中性", "sense_fingerprint": "夜空中一闪一闪的小亮点（日常所见的星）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b64ca331-cee2-4a4d-bcc5-b9b5a93b48c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89031, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "星", "is_correct": true, "explanation": "xīng（第一声）指夜空中一闪一闪的小亮点，即这里要选的词。"}, {"text": "醒", "is_correct": false, "explanation": "xǐng（第三声）与 xīng（第一声）声调不同，意思是醒来、清醒。"}, {"text": "行", "is_correct": false, "explanation": "xíng（第二声）与 xīng（第一声）声调不同，意思是可以、行走。"}, {"text": "性", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，意思是性格、性质。"}, {"text": "心", "is_correct": false, "explanation": "xīn 与 xīng 韵母不同（-n 与 -ng），意思是心脏、心情。"}, {"text": "精", "is_correct": false, "explanation": "jīng 与 xīng 声母不同（j 与 x），意思是精神、精力。"}], "explanations": {"星": "xīng（第一声）指夜空中一闪一闪的小亮点，即这里要选的词。", "醒": "xǐng（第三声）与 xīng（第一声）声调不同，意思是醒来、清醒。", "行": "xíng（第二声）与 xīng（第一声）声调不同，意思是可以、行走。", "性": "xìng（第四声）与 xīng（第一声）声调不同，意思是性格、性质。", "心": "xīn 与 xīng 韵母不同（-n 与 -ng），意思是心脏、心情。", "精": "jīng 与 xīng 声母不同（j 与 x），意思是精神、精力。"}, "sentence_index": null, "correct_answer": "星"}, "level_3": {"options": [{"text": "星", "is_correct": true, "explanation": "星：指夜空中一闪一闪的小亮点，符合“晚上天上有很多”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是白天的天体，晚上看不到，与“晚上”矛盾。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：月亮只有一个，不能用“很多”来修饰。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹出现在雨后的白天，与“晚上”的时间矛盾。"}], "explanations": {"星": "星：指夜空中一闪一闪的小亮点，符合“晚上天上有很多”。", "太阳": "语义：太阳是白天的天体，晚上看不到，与“晚上”矛盾。", "月亮": "搭配：月亮只有一个，不能用“很多”来修饰。", "彩虹": "语义：彩虹出现在雨后的白天，与“晚上”的时间矛盾。"}, "sentence_index": 0, "correct_answer": "星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我渴了，喝了一杯星。", "explanation": "这里应该用〈水〉。星是天上的亮点，不能喝。"}, {"text": "他骑着星去上学。", "explanation": "这里应该用〈自行车〉。星在天上，不能骑。"}, {"text": "我把星放进书包里了。", "explanation": "这里应该用〈书〉。星在天上，不能放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89031, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "星", "is_correct": true, "explanation": "xīng（第一声）指夜空中一闪一闪的小亮点，即这里要选的词。"}, {"text": "新", "is_correct": false, "explanation": "xīn 与 xīng 韵母不同（-n 与 -ng），意思是新旧的新。"}, {"text": "型", "is_correct": false, "explanation": "xíng（第二声）与 xīng（第一声）声调不同，意思是类型、型号。"}, {"text": "幸", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，意思是幸运、幸福。"}, {"text": "经", "is_correct": false, "explanation": "jīng 与 xīng 声母不同（j 与 x），意思是经过、经济。"}, {"text": "姓", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，意思是姓氏。"}], "explanations": {"星": "xīng（第一声）指夜空中一闪一闪的小亮点，即这里要选的词。", "新": "xīn 与 xīng 韵母不同（-n 与 -ng），意思是新旧的新。", "型": "xíng（第二声）与 xīng（第一声）声调不同，意思是类型、型号。", "幸": "xìng（第四声）与 xīng（第一声）声调不同，意思是幸运、幸福。", "经": "jīng 与 xīng 声母不同（j 与 x），意思是经过、经济。", "姓": "xìng（第四声）与 xīng（第一声）声调不同，意思是姓氏。"}, "sentence_index": null, "correct_answer": "星"}, "level_3": {"options": [{"text": "星", "is_correct": true, "explanation": "星：看得见的天上的小亮点，符合“看天上的”。"}, {"text": "树", "is_correct": false, "explanation": "语义：树长在地面，不能在天上被看到。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼生活在水中，不会出现在天上。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”的对象是可见的事物，不能说“看声音”。"}], "explanations": {"星": "星：看得见的天上的小亮点，符合“看天上的”。", "树": "语义：树长在地面，不能在天上被看到。", "鱼": "语义：鱼生活在水中，不会出现在天上。", "声音": "搭配：“看”的对象是可见的事物，不能说“看声音”。"}, "sentence_index": 6, "correct_answer": "星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今晚的星很圆，特别好看。", "explanation": "这里应该用〈月亮〉。“圆”形容月亮的形状；星是一闪一闪的亮点，不能说“圆”。"}, {"text": "中午的星晒得他满头大汗。", "explanation": "这里应该用〈太阳〉。“晒”的是太阳，星不会晒人，也不能这样用。"}, {"text": "屋里的星坏了，一下子变得很黑。", "explanation": "这里应该用〈灯〉。灯会坏、会亮，星是天上的亮点，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天上有一只星。", "corrected_sentence": "天上有一颗星。", "error_description": "量词错误：星的量词应为“颗”，不能用“只”（“只”多用于动物等）。应改为“一颗星”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今晚天上有很多星们。", "corrected_sentence": "今晚天上有很多星。", "error_description": "“很多”后面的名词不加“们”，“们”也不用于星这样的东西。应为“很多星”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
