INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89034, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "成年男性。", "primary_collocate": null, "pronunciation": "nán zǐ", "ipa": "nan˧˥ tsɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "那位男子在门口等着他的朋友。", "target_word": "男子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个男子今年三十岁了。", "target_word": "男子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有一个男子在跑步。", "target_word": "男子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一位年轻男子走进了书店。", "target_word": "男子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一名高大的男子。", "target_word": "男子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个男子手里拿着一个红色的包。", "target_word": "男子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那名男子身高一米八，看上去三十多岁。", "target_word": "男子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问了那位男子几个问题。", "target_word": "男子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个男子在银行工作。", "target_word": "男子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个穿黑衣服的男子坐在我旁边。", "target_word": "男子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "男子汉", "label": "复合"}, {"form": "男子足球", "label": "复合"}], "register": "书面", "sense_fingerprint": "成年男性；指人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: 3 words above tier T1 (max 2): 那名 (Zipf 3.25), 一米 (Zipf 3.31), 三十多 (Zipf 3.0)']::text[], '07800451-dd71-4009-8d4c-1927c61a756d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89034, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男子", "is_correct": true, "explanation": "男子：指成年男性，可用“位”计量，能“等着朋友”。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：量词“位”只用于人，房间要用“间”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会等人。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果不能等待。"}], "explanations": {"男子": "男子：指成年男性，可用“位”计量，能“等着朋友”。", "房间": "搭配：量词“位”只用于人，房间要用“间”。", "桌子": "语义：桌子不会等人。", "苹果": "语义：苹果不能等待。"}, "sentence_index": 0, "correct_answer": "男子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有一个男子，今年十岁。", "explanation": "这里应该用〈男孩〉。男子指成年男性，不指十岁的孩子；说儿童要用男孩。"}, {"text": "这只小猫是男子。", "explanation": "这里应该用〈公的〉或〈雄性〉。男子只指成年男人，不用来说动物的性别。"}, {"text": "他才两岁，就是个男子了。", "explanation": "这里应该用〈幼童〉。男子指成年男性，两岁的孩子要说幼童。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男子", "is_correct": true, "explanation": "男子：指成年男性，与“身高一米八，看上去三十多岁”相合。"}, {"text": "婴儿", "is_correct": false, "explanation": "体貌：婴儿的身高不可能是一米八。"}, {"text": "老人", "is_correct": false, "explanation": "语义：老人与“看上去三十多岁”矛盾。"}, {"text": "男孩", "is_correct": false, "explanation": "语义：男孩不会看上去三十多岁。"}], "explanations": {"男子": "男子：指成年男性，与“身高一米八，看上去三十多岁”相合。", "婴儿": "体貌：婴儿的身高不可能是一米八。", "老人": "语义：老人与“看上去三十多岁”矛盾。", "男孩": "语义：男孩不会看上去三十多岁。"}, "sentence_index": 6, "correct_answer": "男子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我旁边坐着一个男子，他才上小学一年级。", "explanation": "这里应该用〈小学生〉。男子指成年男性，小学生是未成年的孩子。"}, {"text": "我班的男子有三十个，都很活泼。", "explanation": "这里应该用〈男生〉。男子指成年男性，班里的学生是未成年人，应说“男生”。"}, {"text": "一名男子出生了，体重三公斤。", "explanation": "这里应该用〈男婴〉。男子指成年男性，刚出生的婴儿要说“男婴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站里走来一只高大男子。", "corrected_sentence": "车站里走来一位高大男子。", "error_description": "错误在量词“只”。“男子”指人，量词应用“位”，“只”多用于动物，不能用来计量“男子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公园门口站着一头年轻男子。", "corrected_sentence": "公园门口站着一位年轻男子。", "error_description": "错误在量词“头”。“头”用于牛、猪等动物，“男子”指人，应用“位”或“名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
