INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89036, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "妇女每月一次的生理现象；月经的婉称。", "primary_collocate": null, "pronunciation": "yuè shì", "ipa": "ɥe˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "古人把月经叫作月事。", "target_word": "月事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说身体不舒服，是因为月事到了。", "target_word": "月事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月事每月一次，是女人正常的现象。", "target_word": "月事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上讲了女生的月事常识。", "target_word": "月事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的月事已经两个月没来了。", "target_word": "月事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月事前几天，她的心情常常不好。", "target_word": "月事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生专门看和月事有关的病。", "target_word": "月事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，很多人觉得月事是不能公开说的话题。", "target_word": "月事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每个月都会记下月事开始的日子。", "target_word": "月事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月事不准的话，最好去医院检查一下。", "target_word": "月事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "委婉", "sense_fingerprint": "月经的婉称，妇女每月一次的生理现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92d2e1a1-099e-41db-962b-ec5c14b7f3d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89036, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是对月经的称呼。"}, {"text": "月票", "is_correct": false, "explanation": "语义：月票是乘车凭证，与对月经的称呼不符。"}, {"text": "月薪", "is_correct": false, "explanation": "搭配：「叫作」后接的应是对这种现象的称呼，“月薪”是工资，不能作为其称呼。"}, {"text": "月事", "is_correct": true, "explanation": "正确：是月经的婉称，与句意相符。"}], "explanations": {"月亮": "语义：月亮是天体，不是对月经的称呼。", "月票": "语义：月票是乘车凭证，与对月经的称呼不符。", "月薪": "搭配：「叫作」后接的应是对这种现象的称呼，“月薪”是工资，不能作为其称呼。", "月事": "正确：是月经的婉称，与句意相符。"}, "sentence_index": 0, "correct_answer": "月事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生说这个月的月事是十二月。", "explanation": "这里应该用〈月份〉。月事指女性每月的生理现象，不能表示月份，说哪个月要用月份。"}, {"text": "我每个月都买一张月事坐地铁。", "explanation": "这里应该用〈月票〉。月事是女性的生理现象，不能表示乘车用的月票。"}, {"text": "他的月事比去年高了不少。", "explanation": "这里应该用〈月薪〉。月事不表示工资，不能说比去年高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月报", "is_correct": false, "explanation": "语义：月报是工作报告，与“和……有关的病”的意思不符。"}, {"text": "月刊", "is_correct": false, "explanation": "语义：月刊是定期出版的刊物，与“有关的病”的语境不符。"}, {"text": "月底", "is_correct": false, "explanation": "搭配：“有关”后接的是事物，“月底”是时间，搭配不当。"}, {"text": "月事", "is_correct": true, "explanation": "正确：指女性每月一次的生理现象，与句意相符。"}], "explanations": {"月报": "语义：月报是工作报告，与“和……有关的病”的意思不符。", "月刊": "语义：月刊是定期出版的刊物，与“有关的病”的语境不符。", "月底": "搭配：“有关”后接的是事物，“月底”是时间，搭配不当。", "月事": "正确：指女性每月一次的生理现象，与句意相符。"}, "sentence_index": 6, "correct_answer": "月事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我弟弟的月事最近不太好。", "explanation": "这里应该用〈身体状况〉。月事只指女性每月的生理现象，不能用来描述男性的身体状况。"}, {"text": "今晚的月事很圆很亮。", "explanation": "这里应该用〈月亮〉。月事指生理现象，不能描述月亮又圆又亮。"}, {"text": "她每个月都要写月事给老板。", "explanation": "这里应该用〈月报〉。月事指女性每月的生理现象，不能表示写给老板的工作报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她上个月的一个月事推迟了一周。", "corrected_sentence": "她上个月的一次月事推迟了一周。", "error_description": "量词错误：月事应用“次”，不用“个”，应说“一次月事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她这个月来了一条月事。", "corrected_sentence": "她这个月来了一次月事。", "error_description": "量词错误：月事用“次”计数，“条”用于细长的东西，应说“一次月事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
