INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89037, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看上是看了以后,觉得很喜欢,想要。", "primary_collocate": null, "pronunciation": "kàn shàng", "ipa": "kʰan˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "小明看上了同学的新手机。", "target_word": "看上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看上那件大衣，可是太贵了。", "target_word": "看上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书店看上了一本旧词典。", "target_word": "看上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸看上了那块手表，想买下来。", "target_word": "看上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿看上了橱窗里的娃娃。", "target_word": "看上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看上了那块地，想盖个小房子。", "target_word": "看上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看上什么，就告诉我。", "target_word": "看上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人看上了他做的蛋糕，买了两个。", "target_word": "看上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看上了朋友家的那只狗。", "target_word": "看上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看上了一双蓝色的运动鞋。", "target_word": "看上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看上了", "label": "体标"}, {"form": "看上过", "label": "体标"}, {"form": "看不上", "label": "复合"}], "register": "口语", "sense_fingerprint": "看了以后很喜欢，想要得到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4b1fec-b529-465b-92b7-6f05dc3c0020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89037, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "看上", "is_correct": true, "explanation": "看上（kàn shàng）：看后很喜欢，想要得到，即本词。"}, {"text": "砍伤", "is_correct": false, "explanation": "砍伤（kǎn shāng）：两个音节的声调都与 kàn shàng 不同，意思是砍得受伤。"}, {"text": "砍上", "is_correct": false, "explanation": "砍上（kǎn shàng）：kǎn（第三声）与 kàn（第四声）声调不同，意思是朝某处砍下去。"}, {"text": "焊上", "is_correct": false, "explanation": "焊上（hàn shàng）：hàn 与 kàn 声母不同（h 与 k），声调相同，意思是焊接到某处。"}, {"text": "看账", "is_correct": false, "explanation": "看账（kàn zhàng）：zhàng 与 shàng 声母不同（zh 与 sh），声调相同，意思是查看账目。"}], "explanations": {"看上": "看上（kàn shàng）：看后很喜欢，想要得到，即本词。", "砍伤": "砍伤（kǎn shāng）：两个音节的声调都与 kàn shàng 不同，意思是砍得受伤。", "砍上": "砍上（kǎn shàng）：kǎn（第三声）与 kàn（第四声）声调不同，意思是朝某处砍下去。", "焊上": "焊上（hàn shàng）：hàn 与 kàn 声母不同（h 与 k），声调相同，意思是焊接到某处。", "看账": "看账（kàn zhàng）：zhàng 与 shàng 声母不同（zh 与 sh），声调相同，意思是查看账目。"}, "sentence_index": null, "correct_answer": "看上"}, "level_3": {"options": [{"text": "看上", "is_correct": true, "explanation": "看上：看后很喜欢，想要得到，填入后句意“小明喜欢上了同学的新手机”通顺。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，手机不能被咬，句子不通。"}, {"text": "逛", "is_correct": false, "explanation": "语义：逛的对象是商店、公园等场所，手机不能“逛”，句子不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是吃东西，手机不能吃，句子不通。"}], "explanations": {"看上": "看上：看后很喜欢，想要得到，填入后句意“小明喜欢上了同学的新手机”通顺。", "咬": "语义：咬是用牙齿夹住，手机不能被咬，句子不通。", "逛": "语义：逛的对象是商店、公园等场所，手机不能“逛”，句子不通。", "吃": "语义：吃是吃东西，手机不能吃，句子不通。"}, "sentence_index": 0, "correct_answer": "看上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节时我们去看上了外婆。", "explanation": "这里应该用〈看望〉。看上表示看后中意、想要，不能用于探望长辈。"}, {"text": "保安负责看上大门。", "explanation": "这里应该用〈看管〉。看上表示喜欢、想要，不表示照看、管理，大门不能被“看上”。"}, {"text": "他一看上这道题，就知道怎么做。", "explanation": "这里只需用〈看〉。看上表示看后中意、想要，不表示看明白题目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89037, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "看上", "is_correct": true, "explanation": "看上（kàn shàng）：看后很喜欢，想要得到，即本词。"}, {"text": "炕上", "is_correct": false, "explanation": "炕上（kàng shàng）：kàng 与 kàn 韵母不同（ng 与 n），声调相同，意思是在火炕上。"}, {"text": "看相", "is_correct": false, "explanation": "看相（kàn xiàng）：xiàng 与 shàng 声母不同（x 与 sh），声调相同，意思是给人看面相。"}, {"text": "干上", "is_correct": false, "explanation": "干上（gàn shàng）：gàn 与 kàn 声母不同（g 与 k），声调相同，意思是卷入、搞上。"}], "explanations": {"看上": "看上（kàn shàng）：看后很喜欢，想要得到，即本词。", "炕上": "炕上（kàng shàng）：kàng 与 kàn 韵母不同（ng 与 n），声调相同，意思是在火炕上。", "看相": "看相（kàn xiàng）：xiàng 与 shàng 声母不同（x 与 sh），声调相同，意思是给人看面相。", "干上": "干上（gàn shàng）：gàn 与 kàn 声母不同（g 与 k），声调相同，意思是卷入、搞上。"}, "sentence_index": null, "correct_answer": "看上"}, "level_3": {"options": [{"text": "看上", "is_correct": true, "explanation": "看上：看后很喜欢，想要得到，填入后句意“你喜欢什么，就告诉我”通顺。"}, {"text": "修", "is_correct": false, "explanation": "语义：修是修理，与句中“想要什么”的语境不合，句子不通。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是擦拭，与句中表示选择、需求的语境不合，句子不通。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔是跌落、扔下，与句中表示选择、需求的语境不合，句子不通。"}], "explanations": {"看上": "看上：看后很喜欢，想要得到，填入后句意“你喜欢什么，就告诉我”通顺。", "修": "语义：修是修理，与句中“想要什么”的语境不合，句子不通。", "擦": "语义：擦是擦拭，与句中表示选择、需求的语境不合，句子不通。", "摔": "语义：摔是跌落、扔下，与句中表示选择、需求的语境不合，句子不通。"}, "sentence_index": 6, "correct_answer": "看上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从她的表情看上了她的不安。", "explanation": "这里应该用〈看出〉。看上表示看后中意、想要，不表示察觉到别人的情绪。"}, {"text": "护士负责看上病人。", "explanation": "这里应该用〈看护〉。看上表示喜欢、想要，不表示照料病人。"}, {"text": "我在报纸上看上了这条新闻。", "explanation": "这里应该用〈看到〉。看上只用于人或物，表示喜欢、想要，不能用于读到的新闻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹看上得那个粉色的书包。", "corrected_sentence": "我妹妹看上了那个粉色的书包。", "error_description": "错误：“看上得”，正确：“看上了”。“得”用于动词后的补语或可能式，看上后接宾语表示已经发生，要用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她已经看上着那件黑色的外套。", "corrected_sentence": "她已经看上了那件黑色的外套。", "error_description": "错误：“已经看上着”，正确：“已经看上了”。“已经”表示动作已完成，与表示持续的“着”不搭配，这里应使用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649c290b-c186-46ad-ba49-fd2c1b368cea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
