INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89039, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "欣赏是看到好东西，心里喜欢，认真地看。", "primary_collocate": null, "pronunciation": "xīn shǎng", "ipa": "ɕin˥ ʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们站在湖边欣赏夕阳。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常去美术馆欣赏名画。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去公园欣赏樱花。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坐在窗前欣赏着外面的雪景。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们停下来欣赏这里的风景。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢欣赏孩子们的画。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我们一起欣赏了一场音乐会。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的日出值得好好欣赏。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸正在院子里欣赏他的花。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们花了一个小时欣赏这些照片。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "欣赏了", "label": "完成体"}, {"form": "欣赏过", "label": "经历体"}, {"form": "欣赏着", "label": "持续体"}, {"form": "欣赏欣赏", "label": "重叠"}], "register": "中性", "sense_fingerprint": "认真观看美好的风景或作品并感到愉快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b53e4b0-c261-4aa3-a7a3-270daa3968ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89039, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": true, "explanation": "欣赏指观看美好的景色，与“站在湖边”和“夕阳”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，夕阳不能被吃。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不说“修理夕阳”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清除脏物，与夕阳无关，句意不通。"}], "explanations": {"欣赏": "欣赏指观看美好的景色，与“站在湖边”和“夕阳”相符。", "吃": "语义：“吃”指进食，夕阳不能被吃。", "修理": "搭配：“修理”的对象是器物，不说“修理夕阳”。", "打扫": "语义：“打扫”指清除脏物，与夕阳无关，句意不通。"}, "sentence_index": 0, "correct_answer": "欣赏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们认真欣赏了这份账单。", "explanation": "这里应该用〈核对〉。欣赏指观赏美好的事物，账单要用核对。"}, {"text": "公司派人去欣赏市场。", "explanation": "这里应该用〈考察〉。欣赏指观赏美好的事物，调查市场要用考察。"}, {"text": "他们终于欣赏了矛盾。", "explanation": "这里应该用〈解决〉。欣赏指观赏美好的事物，矛盾要用解决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89039, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": true, "explanation": "欣赏指观看美好的表演，与“一起”和“音乐会”相符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁，不能用于音乐会。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”的对象是破损的东西，不说“修补音乐会”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹调食物，不能用于音乐会。"}], "explanations": {"欣赏": "欣赏指观看美好的表演，与“一起”和“音乐会”相符。", "洗": "语义：“洗”指清洁，不能用于音乐会。", "修补": "搭配：“修补”的对象是破损的东西，不说“修补音乐会”。", "煮": "语义：“煮”指烹调食物，不能用于音乐会。"}, "sentence_index": 6, "correct_answer": "欣赏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们欣赏了这份合同。", "explanation": "这里应该用〈审阅〉。欣赏指观赏美好的事物，合同要用审阅。"}, {"text": "我们欣赏了这笔预算。", "explanation": "这里应该用〈核算〉。欣赏指观赏美好的事物，预算要用核算。"}, {"text": "专家欣赏了这组数据。", "explanation": "这里应该用〈分析〉。欣赏指观赏美好的事物，数据要用分析。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天晚上一起欣赏了月亮。", "corrected_sentence": "我们明天晚上一起欣赏月亮。", "error_description": "错误在“欣赏”后面的“了”。“明天晚上”是将来的时间，动作还没有发生，不能用“欣赏了”，应去掉“了”，说“我们明天晚上一起欣赏月亮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈正在欣赏过这幅画。", "corrected_sentence": "妈妈正在欣赏这幅画。", "error_description": "错误在“欣赏”后面的“过”。“正在”表示动作正在进行，“过”表示曾经有过的经历，两者不能同用，应去掉“过”，说“妈妈正在欣赏这幅画”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89040, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "厌恶", "is_correct": true, "explanation": "厌恶指非常讨厌，与“认为好而喜欢”的欣赏互为反义。"}, {"text": "思考", "is_correct": false, "explanation": "思考指用脑子考虑问题，与欣赏没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "研究指深入探讨，与欣赏没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行指到外地游览，与欣赏没有反义关系。"}], "correct_answer": "厌恶", "explanations": {"厌恶": "厌恶指非常讨厌，与“认为好而喜欢”的欣赏互为反义。", "思考": "思考指用脑子考虑问题，与欣赏没有反义关系。", "研究": "研究指深入探讨，与欣赏没有反义关系。", "旅行": "旅行指到外地游览，与欣赏没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89040, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "厌恶", "is_correct": true, "explanation": "厌恶指非常讨厌，与“认为好而喜欢”的欣赏互为反义。"}, {"text": "询问", "is_correct": false, "explanation": "询问指向人提问，与欣赏没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理指把杂乱的东西归置好，与欣赏没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步指随意走走，与欣赏没有反义关系。"}], "correct_answer": "厌恶", "explanations": {"厌恶": "厌恶指非常讨厌，与“认为好而喜欢”的欣赏互为反义。", "询问": "询问指向人提问，与欣赏没有反义关系。", "整理": "整理指把杂乱的东西归置好，与欣赏没有反义关系。", "散步": "散步指随意走走，与欣赏没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89040, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认为人或事物好，因而喜欢、赞赏。", "primary_collocate": null, "pronunciation": "xīn shǎng", "ipa": "ɕin˥ ʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师很欣赏你的想法。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我特别欣赏他的勇气。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理欣赏她认真工作的态度。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我欣赏诚实的人。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很欣赏这位年轻的作家。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都欣赏她的好性格。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最欣赏朋友的地方是他很热心。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不太欣赏这种做法。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长十分欣赏这个学生。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我非常欣赏这首歌的创作思路。", "target_word": "欣赏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "欣赏了", "label": "完成体"}, {"form": "欣赏过", "label": "经历体"}, {"form": "欣赏着", "label": "持续体"}, {"form": "欣赏欣赏", "label": "重叠"}], "register": "中性", "sense_fingerprint": "认为人或事物好，因而喜欢、赞赏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b53e4b0-c261-4aa3-a7a3-270daa3968ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": true, "explanation": "欣赏表示认为你的想法好而喜欢，与“很”表达的赞许语气相符。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”指撕破，不用来对想法。"}, {"text": "包装", "is_correct": false, "explanation": "语义：“包装”指包裹或装饰，与“很”所表达的赞许态度不合，句意不通。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，与“很”表达的赞许态度冲突。"}], "explanations": {"欣赏": "欣赏表示认为你的想法好而喜欢，与“很”表达的赞许语气相符。", "撕": "搭配：“撕”指撕破，不用来对想法。", "包装": "语义：“包装”指包裹或装饰，与“很”所表达的赞许态度不合，句意不通。", "扔": "语义：“扔”指丢弃，与“很”表达的赞许态度冲突。"}, "sentence_index": 0, "correct_answer": "欣赏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很欣赏这场车祸。", "explanation": "这里应该说〈对……感到痛心〉。欣赏指认为好而喜欢，车祸是坏事，应说“我对这场车祸感到很痛心”。"}, {"text": "老师很欣赏他的懒惰。", "explanation": "这里应该用〈不满〉。欣赏指认为好而喜欢，懒惰是缺点，应说“老师很不满他的懒惰”。"}, {"text": "他很欣赏那种不诚实的行为。", "explanation": "这里应该用〈反对〉。欣赏指认为好而喜欢，不诚实不能认为好，表示否定要用反对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": true, "explanation": "欣赏表示认为朋友的优点好而喜欢，与“热心”的赞许语气相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与“热心”的赞许语气相反。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”不能用于人的优点，句意不通。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”指卖掉，与“朋友的地方”不搭。"}], "explanations": {"欣赏": "欣赏表示认为朋友的优点好而喜欢，与“热心”的赞许语气相符。", "拒绝": "语义：“拒绝”表示不接受，与“热心”的赞许语气相反。", "修理": "搭配：“修理”不能用于人的优点，句意不通。", "出售": "语义：“出售”指卖掉，与“朋友的地方”不搭。"}, "sentence_index": 6, "correct_answer": "欣赏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她很欣赏这次的欺骗。", "explanation": "这里应该用〈反感〉。欣赏指认为好而喜欢，欺骗是坏事，表示厌恶要用反感。"}, {"text": "我很欣赏这种粗暴的态度。", "explanation": "这里应该用〈不满〉。欣赏指认为好而喜欢，粗暴的态度是缺点，对它应表达不满。"}, {"text": "他欣赏那个欺负别人的孩子。", "explanation": "这里应该用〈谴责〉。欣赏指认为好而喜欢，欺负别人是坏行为，对它应表示谴责。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长很欣赏了这位老师的教学。", "corrected_sentence": "校长很欣赏这位老师的教学。", "error_description": "错误在“欣赏”后面的“了”。“很”表示一种状态，不能与表示完成的“了”同用，应去掉“了”，说“校长很欣赏这位老师的教学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直很欣赏了这位画家的作品。", "corrected_sentence": "他一直很欣赏这位画家的作品。", "error_description": "错误在“欣赏”后面的“了”。这里的“欣赏”表示一种持续的态度，又有“一直很”修饰，不能加表示完成的“了”。应去掉“了”，说“他一直很欣赏这位画家的作品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "新与旧是反义词，指新的、未用过的东西，与“旧”相对。"}, {"text": "大", "is_correct": false, "explanation": "大说体积或范围，与“旧”没有反义关系。"}, {"text": "红", "is_correct": false, "explanation": "红是颜色，与“旧”没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "慢说速度，与“旧”没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "新与旧是反义词，指新的、未用过的东西，与“旧”相对。", "大": "大说体积或范围，与“旧”没有反义关系。", "红": "红是颜色，与“旧”没有反义关系。", "慢": "慢说速度，与“旧”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "新与旧是反义词，指新的、未用过的东西，与“旧”相对。"}, {"text": "远", "is_correct": false, "explanation": "远说距离，与“旧”没有反义关系。"}, {"text": "红", "is_correct": false, "explanation": "红是颜色，与“旧”没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "轻说重量，与“旧”没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "新与旧是反义词，指新的、未用过的东西，与“旧”相对。", "远": "远说距离，与“旧”没有反义关系。", "红": "红是颜色，与“旧”没有反义关系。", "轻": "轻说重量，与“旧”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "旧是用了很久,已经不新了。", "primary_collocate": null, "pronunciation": "jiù", "ipa": "tɕjoʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "这双鞋太旧了,该换了。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书包很旧,但是我很喜欢。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶家的沙发又旧又小。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书看起来很旧。", "target_word": "旧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他骑着一辆旧自行车。", "target_word": "旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把旧衣服送给了邻居。", "target_word": "旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些椅子虽然旧,但是还能坐。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的旧手表还走得很准。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里的黑板有点旧。", "target_word": "旧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他住在一个很旧的小房子里。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "舊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西用了很久,已经不新", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a2d37c5-ce5a-420d-8d73-ab1cf9e08d40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确答案：旧（jiù），指东西用了很久、已经不新。"}, {"text": "九", "is_correct": false, "explanation": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，九是数字“九”。"}, {"text": "六", "is_correct": false, "explanation": "声母不同：liù（l）与 jiù（j）声母不同，六是数字“六”。"}, {"text": "秀", "is_correct": false, "explanation": "声母不同：xiù（x）与 jiù（j）声母不同，秀是“优美”的意思，不是“旧”。"}, {"text": "究", "is_correct": false, "explanation": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，究是“追查、究竟”的意思。"}], "explanations": {"旧": "正确答案：旧（jiù），指东西用了很久、已经不新。", "九": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，九是数字“九”。", "六": "声母不同：liù（l）与 jiù（j）声母不同，六是数字“六”。", "秀": "声母不同：xiù（x）与 jiù（j）声母不同，秀是“优美”的意思，不是“旧”。", "究": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，究是“追查、究竟”的意思。"}, "sentence_index": null, "correct_answer": "旧"}, "level_3": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确：“太旧了，该换了”说鞋用久了、不新，需要换。"}, {"text": "新", "is_correct": false, "explanation": "语义：太新了就不必换，与“该换了”的理由矛盾。"}, {"text": "干净", "is_correct": false, "explanation": "语义：太干净不构成该换的理由，与句意不合。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：甜不能修饰鞋，“太甜了”不成话。"}], "explanations": {"旧": "正确：“太旧了，该换了”说鞋用久了、不新，需要换。", "新": "语义：太新了就不必换，与“该换了”的理由矛盾。", "干净": "语义：太干净不构成该换的理由，与句意不合。", "甜": "搭配：甜不能修饰鞋，“太甜了”不成话。"}, "sentence_index": 0, "correct_answer": "旧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看起来很旧，头发都白了。", "explanation": "这里应该用〈老〉。旧用于东西，指用久了、不新；说人年纪大要用〈老〉。"}, {"text": "他对旧事念念不忘。", "explanation": "此处“旧”是“过去的”义项，指旧事，不是“用了很久、已经不新”的意思。"}, {"text": "他的旧病复发了。", "explanation": "此处“旧”指原有的、早就有的病，是另一义项，不是“用了很久”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确答案：旧（jiù），指东西用了很久、已经不新。"}, {"text": "久", "is_correct": false, "explanation": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，久是“时间长”的意思。"}, {"text": "酒", "is_correct": false, "explanation": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，酒是饮料。"}, {"text": "袖", "is_correct": false, "explanation": "声母不同：xiù（x）与 jiù（j）声母不同，袖是衣服的袖子。"}, {"text": "纠", "is_correct": false, "explanation": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，纠是“纠正”的意思。"}], "explanations": {"旧": "正确答案：旧（jiù），指东西用了很久、已经不新。", "久": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，久是“时间长”的意思。", "酒": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，酒是饮料。", "袖": "声母不同：xiù（x）与 jiù（j）声母不同，袖是衣服的袖子。", "纠": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，纠是“纠正”的意思。"}, "sentence_index": null, "correct_answer": "旧"}, "level_3": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确：“虽然旧，但是还能坐”是让步句，说椅子用久了但仍可用。"}, {"text": "新", "is_correct": false, "explanation": "语义：新不是需要让步的缺点，“虽然新，但是还能坐”的让步关系不成立。"}, {"text": "精致", "is_correct": false, "explanation": "语义：精致指精巧细致，与“还能坐”之间没有让步关系，句子不通。"}, {"text": "蓝", "is_correct": false, "explanation": "语义：蓝是颜色，不能说明椅子的新旧，也不构成“虽然……但是还能坐”的让步关系。"}], "explanations": {"旧": "正确：“虽然旧，但是还能坐”是让步句，说椅子用久了但仍可用。", "新": "语义：新不是需要让步的缺点，“虽然新，但是还能坐”的让步关系不成立。", "精致": "语义：精致指精巧细致，与“还能坐”之间没有让步关系，句子不通。", "蓝": "语义：蓝是颜色，不能说明椅子的新旧，也不构成“虽然……但是还能坐”的让步关系。"}, "sentence_index": 6, "correct_answer": "旧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出生在旧社会，小时候很苦。", "explanation": "此处“旧”是“过去的、以前的时代”义项，指旧社会，不是“用了很久、过时”的意思。"}, {"text": "他常常回忆旧日的时光。", "explanation": "此处“旧”是“过去的”义项，指旧日，不是“用了很久、过时”的意思。"}, {"text": "这双袜子旧了一个洞。", "explanation": "这里应该用〈破〉。旧只说东西用久了、不新，不说有了窟窿；有洞要用〈破〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋穿旧过，该换了。", "corrected_sentence": "这双鞋穿旧了，该换了。", "error_description": "“穿旧”后应用“了”表示变化，用“过”表示经历，句意不通。正确写法是“这双鞋穿旧了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89041, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间老屋旧很，但很温暖。", "corrected_sentence": "这间老屋很旧，但很温暖。", "error_description": "程度副词“很”应放在“旧”之前作状语，写成“旧很”是语序错误。正确写法是“很旧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "新与旧是反义词，指新的、未用过的东西，与“旧”（用了很久、过时）相对。"}, {"text": "大", "is_correct": false, "explanation": "大说体积或范围，与“旧”没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "亮说光线明亮，与“旧”的“用久、过时”没有反义关系。"}, {"text": "甜", "is_correct": false, "explanation": "甜说味道，与“旧”没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "新与旧是反义词，指新的、未用过的东西，与“旧”（用了很久、过时）相对。", "大": "大说体积或范围，与“旧”没有反义关系。", "亮": "亮说光线明亮，与“旧”的“用久、过时”没有反义关系。", "甜": "甜说味道，与“旧”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "新与旧是反义词，指新的、未用过的东西，与“旧”相对。"}, {"text": "远", "is_correct": false, "explanation": "远说距离，与“旧”没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "厚说厚度，与“旧”没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "轻说重量，与“旧”没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "新与旧是反义词，指新的、未用过的东西，与“旧”相对。", "远": "远说距离，与“旧”没有反义关系。", "厚": "厚说厚度，与“旧”没有反义关系。", "轻": "轻说重量，与“旧”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "过时的;经过长久使用的;与「新」相对。", "primary_collocate": null, "pronunciation": "jiù", "ipa": "tɕjoʊ̯˥˩", "syllable_count": 1, "sentences": [{"text": "这种旧手机现在没人用了。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他还穿着一件旧外套。", "target_word": "旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法太旧了,不适合现在。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旧的桌子坏了,我们买了新的。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条裤子已经很旧了。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸开着一辆旧车去上班。", "target_word": "旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的观念很旧,总是不接受新东西。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子旧了,墙也黄了。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把旧书卖给了收废品的人。", "target_word": "旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑太旧,开机要等很久。", "target_word": "旧", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "舊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "与新相对,指过时的或用了很久的事物、观念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a2d37c5-ce5a-420d-8d73-ab1cf9e08d40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确答案：旧（jiù），指过时的、用了很久的，与“新”相对。"}, {"text": "九", "is_correct": false, "explanation": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，九是数字“九”。"}, {"text": "六", "is_correct": false, "explanation": "声母不同：liù（l）与 jiù（j）声母不同，六是数字“六”。"}, {"text": "秀", "is_correct": false, "explanation": "声母不同：xiù（x）与 jiù（j）声母不同，秀是“优美”的意思，不是“旧”。"}, {"text": "究", "is_correct": false, "explanation": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，究是“追查、究竟”的意思。"}], "explanations": {"旧": "正确答案：旧（jiù），指过时的、用了很久的，与“新”相对。", "九": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，九是数字“九”。", "六": "声母不同：liù（l）与 jiù（j）声母不同，六是数字“六”。", "秀": "声母不同：xiù（x）与 jiù（j）声母不同，秀是“优美”的意思，不是“旧”。", "究": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，究是“追查、究竟”的意思。"}, "sentence_index": null, "correct_answer": "旧"}, "level_3": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确：“旧手机”指用久、过时的手机，与“现在没人用了”相符。"}, {"text": "热门", "is_correct": false, "explanation": "语义：热门指很受欢迎，与“现在没人用了”的情况矛盾。"}, {"text": "时髦", "is_correct": false, "explanation": "语义：时髦指很流行、跟得上潮流，与“现在没人用了”的情况相反。"}, {"text": "深", "is_correct": false, "explanation": "搭配：深不能修饰手机，“这种深手机”不成话。"}], "explanations": {"旧": "正确：“旧手机”指用久、过时的手机，与“现在没人用了”相符。", "热门": "语义：热门指很受欢迎，与“现在没人用了”的情况矛盾。", "时髦": "语义：时髦指很流行、跟得上潮流，与“现在没人用了”的情况相反。", "深": "搭配：深不能修饰手机，“这种深手机”不成话。"}, "sentence_index": 0, "correct_answer": "旧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爷爷已经很旧了，走路都不方便。", "explanation": "这里应该用〈老〉。旧多指东西用久、不新，说人年纪大要用〈老〉。"}, {"text": "他一直怀念旧友。", "explanation": "此处“旧”是“以前的、长久相交的”义项，指旧友，不是“用了很久、已经不新”的意思。"}, {"text": "他的旧病又复发了。", "explanation": "此处“旧”指原有的、以前就有的病，属于另一义项，不是“用了很久、已不新”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确答案：旧（jiù），指过时的、用了很久的，与“新”相对。"}, {"text": "久", "is_correct": false, "explanation": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，久是“时间长”的意思。"}, {"text": "酒", "is_correct": false, "explanation": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，酒是饮料。"}, {"text": "袖", "is_correct": false, "explanation": "声母不同：xiù（x）与 jiù（j）声母不同，袖是衣服的袖子。"}, {"text": "纠", "is_correct": false, "explanation": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，纠是“纠正”的意思。"}], "explanations": {"旧": "正确答案：旧（jiù），指过时的、用了很久的，与“新”相对。", "久": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，久是“时间长”的意思。", "酒": "声调不同：jiǔ（第三声）与 jiù（第四声）声调不同，酒是饮料。", "袖": "声母不同：xiù（x）与 jiù（j）声母不同，袖是衣服的袖子。", "纠": "声调不同：jiū（第一声）与 jiù（第四声）声调不同，纠是“纠正”的意思。"}, "sentence_index": null, "correct_answer": "旧"}, "level_3": {"options": [{"text": "旧", "is_correct": true, "explanation": "正确：“观念很旧，总是不接受新东西”说观念过时，与句意一致。"}, {"text": "开放", "is_correct": false, "explanation": "语义：开放指思想不保守、乐于接受新事物，与“总是不接受新东西”矛盾。"}, {"text": "新", "is_correct": false, "explanation": "语义：观念很新与后面“总是不接受新东西”自相矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“观念”不能用“亮”来形容，“观念很亮”不成话。"}], "explanations": {"旧": "正确：“观念很旧，总是不接受新东西”说观念过时，与句意一致。", "开放": "语义：开放指思想不保守、乐于接受新事物，与“总是不接受新东西”矛盾。", "新": "语义：观念很新与后面“总是不接受新东西”自相矛盾。", "亮": "搭配：“观念”不能用“亮”来形容，“观念很亮”不成话。"}, "sentence_index": 6, "correct_answer": "旧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑开机太旧了，要等很久。", "explanation": "这里应该用〈慢〉。旧说东西用了很久、不新，不能用来形容开机的速度。"}, {"text": "他出生在旧社会，小时候很苦。", "explanation": "此处“旧”是“过去的、以前的时代”义项，指旧社会，不是“用了很久、过时”的意思。"}, {"text": "他们又回到了旧地。", "explanation": "此处“旧”是“以前去过的”义项，指旧地方，不是“东西用久、不新”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件外套我穿了很多年，已经旧了了。", "corrected_sentence": "这件外套我穿了很多年，已经旧了。", "error_description": "“旧”后只需一个“了”表示变化，此处多加了一个“了”，重复。正确写法是“已经旧了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼旧很了，电梯也常坏。", "corrected_sentence": "这栋楼很旧了，电梯也常坏。", "error_description": "程度副词“很”应放在“旧”之前作状语，写成“旧很了”语序错误。正确写法是“这栋楼很旧了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "彼时", "is_correct": true, "explanation": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。"}, {"text": "明天", "is_correct": false, "explanation": "“明天”指将来的一天，与“此时”不构成反义。"}, {"text": "春天", "is_correct": false, "explanation": "“春天”是季节，与“此时”不构成反义。"}, {"text": "深夜", "is_correct": false, "explanation": "“深夜”指夜深的一段时间，与“此时”不构成反义。"}], "correct_answer": "彼时", "explanations": {"彼时": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。", "明天": "“明天”指将来的一天，与“此时”不构成反义。", "春天": "“春天”是季节，与“此时”不构成反义。", "深夜": "“深夜”指夜深的一段时间，与“此时”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "彼时", "is_correct": true, "explanation": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。"}, {"text": "清晨", "is_correct": false, "explanation": "“清晨”指一天中的早晨时段，与“此时”不构成反义。"}, {"text": "夏天", "is_correct": false, "explanation": "“夏天”是季节，与“此时”不构成反义。"}, {"text": "周末", "is_correct": false, "explanation": "“周末”指一周末尾的假日，与“此时”不构成反义。"}], "correct_answer": "彼时", "explanations": {"彼时": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。", "清晨": "“清晨”指一天中的早晨时段，与“此时”不构成反义。", "夏天": "“夏天”是季节，与“此时”不构成反义。", "周末": "“周末”指一周末尾的假日，与“此时”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "此时是说话时的这个时候。", "primary_collocate": null, "pronunciation": "cǐ shí", "ipa": "tsʰɨ˨˩˦ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "此时天已经黑了。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时我正在回家的路上。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时他心里非常紧张。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时外面下起了大雨。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时大家都安静了下来。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时的我只想好好睡一觉。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时她还不知道这件事。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八点钟，此时街上人很少。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了很久，此时有点累了。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都睡了，此时屋里很安静。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "此时此刻", "label": "复合"}], "register": "书面", "sense_fingerprint": "指说话或叙述时正在发生的这个时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b53e4b0-c261-4aa3-a7a3-270daa3968ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此时", "is_correct": true, "explanation": "此时指说话或叙述的这个时候，与“天已经黑了”的时点相符。"}, {"text": "明天", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，与指向将来的“明天”相冲突。"}, {"text": "去年", "is_correct": false, "explanation": "搭配：“去年”指整整一年，不能用来指傍晚天黑的某个时刻。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不表示天色变暗的具体时刻。"}], "explanations": {"此时": "此时指说话或叙述的这个时候，与“天已经黑了”的时点相符。", "明天": "体貌：“已经”表示动作已经完成，与指向将来的“明天”相冲突。", "去年": "搭配：“去年”指整整一年，不能用来指傍晚天黑的某个时刻。", "春天": "语义：“春天”是季节，不表示天色变暗的具体时刻。"}, "sentence_index": 0, "correct_answer": "此时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们把学校建在此时了。", "explanation": "这里应该用〈此地〉。“建在”需要处所，此时是时间，不能作地点。"}, {"text": "他在此时工作了三个小时。", "explanation": "这里应该用〈这段时间〉。“此时”指一个时间点，不能与表示持续时段的“工作了三个小时”搭配。"}, {"text": "我们明年夏天再见面，此时一起去旅行。", "explanation": "这里应该用〈届时〉。“明年夏天”是将来的时间，此时指说话时的当下，不能用来指将来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此时", "is_correct": true, "explanation": "此时指说话或叙述的这个时候，与“还不知道”所描述的时间状态相符。"}, {"text": "结局", "is_correct": false, "explanation": "语义：“结局”指事情最终的结果，不能作时间状语表示“现在”。"}, {"text": "时期", "is_correct": false, "explanation": "搭配：“时期”需要修饰语才能作时间状语，不能单独放在“还不知道”前。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”表示终止，与“她还不知道这件事”的状态不相容。"}], "explanations": {"此时": "此时指说话或叙述的这个时候，与“还不知道”所描述的时间状态相符。", "结局": "语义：“结局”指事情最终的结果，不能作时间状语表示“现在”。", "时期": "搭配：“时期”需要修饰语才能作时间状语，不能单独放在“还不知道”前。", "结束": "语义：“结束”表示终止，与“她还不知道这件事”的状态不相容。"}, "sentence_index": 6, "correct_answer": "此时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们都睡了，我把玩具放在此时了。", "explanation": "这里应该用〈桌上〉这类处所词。“此时”是时间，不能作“放”的处所。"}, {"text": "孩子们都睡了，此时我们明天去公园。", "explanation": "这里应该用〈届时〉或〈明天〉这类将来时间词。“此时”指说话时的当下，不能与“明天去公园”的将来安排连用。"}, {"text": "孩子们都睡了，屋里此时安静了一整个学期。", "explanation": "这里应该用〈这段时间〉。“此时”是时间点，不能与“一整个学期”这种时段搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "此时过街上已经没有人了。", "corrected_sentence": "此时街上已经没有人了。", "error_description": "错误：“此时”后面加了“过”。正确：“此时街上已经没有人了。”此时是时间名词，后面不接“过”，“过”只能跟在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "此时了街上已经很安静。", "corrected_sentence": "此时街上已经很安静。", "error_description": "错误：“此时”后面直接加了“了”。正确：“此时街上已经很安静。”此时是时间名词，后面不接“了”，“了”应放在动词或形容词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "彼时", "is_correct": true, "explanation": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。"}, {"text": "早晨", "is_correct": false, "explanation": "“早晨”指一天的一个时段，与“此时”不构成反义。"}, {"text": "明天", "is_correct": false, "explanation": "“明天”指将来的一天，与“此时”不构成反义。"}, {"text": "周末", "is_correct": false, "explanation": "“周末”指一周末尾的假日，与“此时”不构成反义。"}], "correct_answer": "彼时", "explanations": {"彼时": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。", "早晨": "“早晨”指一天的一个时段，与“此时”不构成反义。", "明天": "“明天”指将来的一天，与“此时”不构成反义。", "周末": "“周末”指一周末尾的假日，与“此时”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "彼时", "is_correct": true, "explanation": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。"}, {"text": "深夜", "is_correct": false, "explanation": "“深夜”指夜深的一段时间，与“此时”不构成反义。"}, {"text": "去年", "is_correct": false, "explanation": "“去年”指上一年，与“此时”不构成反义。"}, {"text": "星期天", "is_correct": false, "explanation": "“星期天”指一周中的一天，与“此时”不构成反义。"}], "correct_answer": "彼时", "explanations": {"彼时": "彼时指说话或叙述的那个时候，与“此时”相对，是反义关系。", "深夜": "“深夜”指夜深的一段时间，与“此时”不构成反义。", "去年": "“去年”指上一年，与“此时”不构成反义。", "星期天": "“星期天”指一周中的一天，与“此时”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这个时候；现在。", "primary_collocate": null, "pronunciation": "cǐ shí", "ipa": "tsʰɨ˨˩˦ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "此时正是春天，花都开了。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛到了最后，此时大家都站了起来。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时你应该好好休息。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时我才明白他的意思。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳升起来了，此时山里很美。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走进教室，此时老师正在讲课。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时的北京已经很冷了。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钟响了十二下，此时已经是半夜了。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她接到电话，此时心里很高兴。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此时我们已经到了机场。", "target_word": "此时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "此时此刻", "label": "复合"}], "register": "书面", "sense_fingerprint": "这个时候，现在，承接前文所说的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b53e4b0-c261-4aa3-a7a3-270daa3968ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此时", "is_correct": true, "explanation": "此时指说话或叙述的这个时候，与“正是春天”的时间描述相符。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”与“正是春天”的季节相矛盾，不能用在这里。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：“夏天”是另一个季节，与“正是春天”相冲突。"}, {"text": "午夜", "is_correct": false, "explanation": "搭配：“午夜”是一天中的某个时刻，不能和“正是春天”这种季节说法搭配。"}], "explanations": {"此时": "此时指说话或叙述的这个时候，与“正是春天”的时间描述相符。", "冬天": "语义：“冬天”与“正是春天”的季节相矛盾，不能用在这里。", "夏天": "语义：“夏天”是另一个季节，与“正是春天”相冲突。", "午夜": "搭配：“午夜”是一天中的某个时刻，不能和“正是春天”这种季节说法搭配。"}, "sentence_index": 0, "correct_answer": "此时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把行李放在此时了。", "explanation": "这里应该用〈车上〉这类处所词。“此时”是时间，不能作“放”的处所。"}, {"text": "他在此时学了三年英语。", "explanation": "这里应该用〈这段时间〉。“此时”是时间点，不能与“学了三年”这种时段搭配。"}, {"text": "明天上午十点请大家准时到会议室，此时我们开始讨论。", "explanation": "这里应该用〈届时〉。“明天上午十点”指将来，此时指当前，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此时", "is_correct": true, "explanation": "此时指说话或叙述的这个时候，与“北京已经很冷了”的时间语境相符。"}, {"text": "盛夏", "is_correct": false, "explanation": "语义：“盛夏”是一年中最热的季节，与“已经很冷了”相矛盾。"}, {"text": "三伏", "is_correct": false, "explanation": "语义：“三伏”指夏天最热的时段，与“很冷了”相矛盾。"}, {"text": "暑假", "is_correct": false, "explanation": "搭配：“暑假”是一段假期，不能与“很冷了”这种天气描述搭配。"}], "explanations": {"此时": "此时指说话或叙述的这个时候，与“北京已经很冷了”的时间语境相符。", "盛夏": "语义：“盛夏”是一年中最热的季节，与“已经很冷了”相矛盾。", "三伏": "语义：“三伏”指夏天最热的时段，与“很冷了”相矛盾。", "暑假": "搭配：“暑假”是一段假期，不能与“很冷了”这种天气描述搭配。"}, "sentence_index": 6, "correct_answer": "此时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们明天就到机场，此时已经到了。", "explanation": "这里应该用〈届时〉。“此时”指当下，不能与“明天就到”的将来时间并列。"}, {"text": "我们在此时里等飞机。", "explanation": "这里应该用〈候机厅里〉。“此时”是时间，不能作处所，“此时里”不通。"}, {"text": "我们在此时走了三个小时才到机场。", "explanation": "这里应该用〈这段时间〉。“此时”是时间点，不能与“走了三个小时”这种时段搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "此时过花都开了。", "corrected_sentence": "此时花都开了。", "error_description": "错误：“此时”后面加了“过”。正确：“此时花都开了。”此时是时间名词，后面不接“过”，“过”只能跟在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "此时了天气很冷。", "corrected_sentence": "此时天气很冷。", "error_description": "错误：“此时”后面直接加了“了”。正确：“此时天气很冷。”此时是时间名词，后面不接“了”，“了”应放在动词或形容词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbded4b4-2284-419c-b0cf-7613cad41196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "正确：无名，指没有名声、不为人知，与“著名”相反。"}, {"text": "勇敢", "is_correct": false, "explanation": "非反义：勇敢指不怕危险、有胆量，与名声的有无无关。"}, {"text": "清澈", "is_correct": false, "explanation": "非反义：清澈指水或空气干净透明，与名声的有无无关。"}, {"text": "朴素", "is_correct": false, "explanation": "非反义：朴素指简单不华丽，与名声无关。"}], "correct_answer": "无名", "explanations": {"无名": "正确：无名，指没有名声、不为人知，与“著名”相反。", "勇敢": "非反义：勇敢指不怕危险、有胆量，与名声的有无无关。", "清澈": "非反义：清澈指水或空气干净透明，与名声的有无无关。", "朴素": "非反义：朴素指简单不华丽，与名声无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "正确：无名，指没有名声、不为人知，与“著名”相反。"}, {"text": "神秘", "is_correct": false, "explanation": "非反义：神秘指难以理解，与名声无关。"}, {"text": "简陋", "is_correct": false, "explanation": "非反义：简陋指粗糙简单，与名声无关。"}, {"text": "湿润", "is_correct": false, "explanation": "非反义：湿润指含有较多水分，与名声无关。"}], "correct_answer": "无名", "explanations": {"无名": "正确：无名，指没有名声、不为人知，与“著名”相反。", "神秘": "非反义：神秘指难以理解，与名声无关。", "简陋": "非反义：简陋指粗糙简单，与名声无关。", "湿润": "非反义：湿润指含有较多水分，与名声无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "著名是很多人都知道,很有名。", "primary_collocate": null, "pronunciation": "zhù míng", "ipa": "ʈʂu˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "长城是世界上很著名的地方。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师在全国都很著名。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的书很著名，我也看过。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家在国外也很著名。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故宫是北京最著名的景点之一。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个著名的演员今天来我们城市了。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路因为小吃而著名，晚上人很多。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是著名的足球运动员，大家都认识他。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方以茶著名，游客都来买茶叶。", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道那位著名的作家吗？", "target_word": "著名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容很多人都知道、很有名，可作定语或谓语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8acff1a7-15ec-4016-88fb-91db472ff9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "著名", "is_correct": true, "explanation": "正确：著名，指很多人都知道、很有名。"}, {"text": "署名", "is_correct": false, "explanation": "署名（shǔmíng）与著名声母（sh 与 zh）和声调（第三声与第四声）不同，意思是在文件上签写名字。"}, {"text": "注目", "is_correct": false, "explanation": "注目（zhùmù）第二音节 mù 与 míng 韵母和声调不同，意思是把目光集中在一点上。"}, {"text": "书名", "is_correct": false, "explanation": "书名（shūmíng）与著名声母不同（sh 与 zh）且声调不同，意思是书的名称。"}, {"text": "除名", "is_correct": false, "explanation": "除名（chúmíng）声母 ch 与 zh 不同，声调也不同，意思是取消名籍。"}], "explanations": {"著名": "正确：著名，指很多人都知道、很有名。", "署名": "署名（shǔmíng）与著名声母（sh 与 zh）和声调（第三声与第四声）不同，意思是在文件上签写名字。", "注目": "注目（zhùmù）第二音节 mù 与 míng 韵母和声调不同，意思是把目光集中在一点上。", "书名": "书名（shūmíng）与著名声母不同（sh 与 zh）且声调不同，意思是书的名称。", "除名": "除名（chúmíng）声母 ch 与 zh 不同，声调也不同，意思是取消名籍。"}, "sentence_index": null, "correct_answer": "著名"}, "level_3": {"options": [{"text": "苦", "is_correct": false, "explanation": "语义：苦说味道，不能用来形容地方的名气。"}, {"text": "著名", "is_correct": true, "explanation": "正确：著名，表示有名声，修饰“地方”。"}, {"text": "幼稚", "is_correct": false, "explanation": "搭配：幼稚说人的想法或做法，不用来形容地方。"}, {"text": "透明", "is_correct": false, "explanation": "语义：透明说物体的状态，不能用来形容地方。"}], "explanations": {"苦": "语义：苦说味道，不能用来形容地方的名气。", "著名": "正确：著名，表示有名声，修饰“地方”。", "幼稚": "搭配：幼稚说人的想法或做法，不用来形容地方。", "透明": "语义：透明说物体的状态，不能用来形容地方。"}, "sentence_index": 0, "correct_answer": "著名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室的温度很著名，学生都觉得很冷。", "explanation": "这里应该用〈高〉或〈低〉。著名指名声，不能用来形容温度。"}, {"text": "这个人的个子很著名，走在人群里很显眼。", "explanation": "这里应该用〈高〉。著名指名声，不能用来形容身高。"}, {"text": "这套家具的颜色很著名，搭配起来很漂亮。", "explanation": "这里应该用〈好看〉。著名指名声，不能用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "著名", "is_correct": true, "explanation": "正确：著名，指很多人都知道、很有名。"}, {"text": "指名", "is_correct": false, "explanation": "指名（zhǐmíng）韵母 u 与 i 不同，意思是点名或指定，不是有名。"}, {"text": "除名", "is_correct": false, "explanation": "除名（chúmíng）声母 zh 与 ch 不同且声调不同，意思是取消名籍。"}, {"text": "注定", "is_correct": false, "explanation": "注定（zhùdìng）后一音节声母 m 与 d 不同，意思是事先已经决定。"}, {"text": "驻京", "is_correct": false, "explanation": "驻京（zhùjīng）后一音节声母 m 与 j 不同，意思是在首都驻扎。"}], "explanations": {"著名": "正确：著名，指很多人都知道、很有名。", "指名": "指名（zhǐmíng）韵母 u 与 i 不同，意思是点名或指定，不是有名。", "除名": "除名（chúmíng）声母 zh 与 ch 不同且声调不同，意思是取消名籍。", "注定": "注定（zhùdìng）后一音节声母 m 与 d 不同，意思是事先已经决定。", "驻京": "驻京（zhùjīng）后一音节声母 m 与 j 不同，意思是在首都驻扎。"}, "sentence_index": null, "correct_answer": "著名"}, "level_3": {"options": [{"text": "烫", "is_correct": false, "explanation": "语义：烫说温度，与“因为小吃而”不搭配。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：矮说高低，不能说因为小吃而矮。"}, {"text": "著名", "is_correct": true, "explanation": "正确：著名，表示因小吃而有名声，与“因为……而”搭配。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：窄说宽度，不能说因为小吃而窄。"}], "explanations": {"烫": "语义：烫说温度，与“因为小吃而”不搭配。", "矮": "搭配：矮说高低，不能说因为小吃而矮。", "著名": "正确：著名，表示因小吃而有名声，与“因为……而”搭配。", "窄": "搭配：窄说宽度，不能说因为小吃而窄。"}, "sentence_index": 6, "correct_answer": "著名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的电脑速度很著名，打字很快。", "explanation": "这里应该用〈快〉。著名指名声，不能用来形容速度。"}, {"text": "这把椅子很著名，坐上去很硬。", "explanation": "这里应该用〈硬〉或〈舒服〉。著名指名声，不能用来形容椅子的舒适程度。"}, {"text": "这本书的价格很著名，买的人不多。", "explanation": "这里应该用〈贵〉。著名指名声，不能用来形容价格的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位医生在我们城市比著名。", "corrected_sentence": "这位医生在我们城市很著名。", "error_description": "“比”后面要有比较对象，表示程度应用“很”，应说“很著名”，不能说“比著名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家饭店在城里的著名。", "corrected_sentence": "那家饭店在城里很著名。", "error_description": "“著名”作谓语前要用程度副词“很”，不能用“的”，否则句子不完整。错误：在城里的著名；正确：在城里很著名。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
