INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89047, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "比来是说最近这一段时间。", "primary_collocate": null, "pronunciation": "bǐ lái", "ipa": "pi˨˩˦ lai˧˥", "syllable_count": 2, "sentences": [{"text": "比来天气很冷，大家都穿上了厚衣服。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比来工作很忙，很少回家。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比来我睡得不好，常常半夜醒来。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你比来身体怎么样？", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比来城里新开了很多饭店。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她比来迷上了跑步，每天早上都去。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比来小王常常加班，看起来很累。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比来雨水多，路上很难走。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老同学比来有没有给你写信？", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我比来读了几本好书，想推荐给你。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "最近这一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89ee32a3-3677-402a-8adc-801a9e813d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89047, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比来", "is_correct": true, "explanation": "正确：比来是副词，指近一段时间，“比来天气很冷”说近来天气的情况。"}, {"text": "即将", "is_correct": false, "explanation": "语义：“即将”表示将要发生，与“大家都穿上了厚衣服”的已完成情况矛盾。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”只修饰形容词，不能放在主语“天气”之前，“非常天气很冷”不成立。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”后接动作，不能直接修饰“天气很冷”这种形容词状态。"}], "explanations": {"比来": "正确：比来是副词，指近一段时间，“比来天气很冷”说近来天气的情况。", "即将": "语义：“即将”表示将要发生，与“大家都穿上了厚衣服”的已完成情况矛盾。", "非常": "搭配：“非常”只修饰形容词，不能放在主语“天气”之前，“非常天气很冷”不成立。", "正在": "搭配：“正在”后接动作，不能直接修饰“天气很冷”这种形容词状态。"}, "sentence_index": 0, "correct_answer": "比来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我比来出生在北京。", "explanation": "这里把“比来”当成了〈以前〉用，但它只指近一段时间，不能用来说出生这种很久以前的事。"}, {"text": "我们比来会结婚。", "explanation": "这里应该用〈将来〉。“比来”指近来，不能表示将来的事。"}, {"text": "今天下午比来开会。", "explanation": "这里把“比来”当成了〈某个时点〉用，但它只指近一段时期，不能用于“今天下午”这样具体的时间点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比来", "is_correct": true, "explanation": "正确：比来指近一段时间，“比来小王常常加班”说小王近来经常加班。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指刚发生的事，与“常常加班”的长期习惯不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”指少有的情况，与“常常”矛盾。"}, {"text": "从不", "is_correct": false, "explanation": "搭配：“从不”是否定，与“常常加班”的肯定习惯相反。"}], "explanations": {"比来": "正确：比来指近一段时间，“比来小王常常加班”说小王近来经常加班。", "刚刚": "语义：“刚刚”指刚发生的事，与“常常加班”的长期习惯不符。", "偶尔": "语义：“偶尔”指少有的情况，与“常常”矛盾。", "从不": "搭配：“从不”是否定，与“常常加班”的肯定习惯相反。"}, "sentence_index": 6, "correct_answer": "比来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地球比来是圆的。", "explanation": "这里把“比来”当成了〈一直〉用，但它只指近一段时间，不能用于地球是圆的这类长久不变的事实。"}, {"text": "去年比来很冷。", "explanation": "这里把“比来”当成了〈当时〉用，但它只指近一段时间，不能指过去某个时期。"}, {"text": "比来，请你马上回家！", "explanation": "这里把“比来”当成了〈立刻〉用，但它只指近一段时间，不能表示立刻要做的命令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城里交通比来着很方便。", "corrected_sentence": "城里交通比来很方便。", "error_description": "错误：“比来”后面多加了“着”。“比来”是表示时间的副词，后面不能加体标“着”，应去掉“着”，写成“城里交通比来很方便”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老王很比来常常出差。", "corrected_sentence": "老王比来常常出差。", "error_description": "错误：“比来”前面多加了“很”。“比来”是副词，表示时间，不能被“很”修饰，应去掉“很”，写成“老王比来常常出差”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
