INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89048, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "近来；最近。", "primary_collocate": null, "pronunciation": "bǐ lái", "ipa": "pi˨˩˦ lai˧˥", "syllable_count": 2, "sentences": [{"text": "比来物价涨了不少，大家花钱更小心。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比来心情不错，总是笑着。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比来公司事情多，我每天都很晚回家。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李比来搬了新家，离我们很近。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比来听说你换了工作，是真的吗？", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比来天天下雨，衣服总是不干。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我比来在学做饭，已经会做三个菜了。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子比来长高了很多。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比来街上的人少了，大概是太热了。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她比来很少上网，说想多看看书。", "target_word": "比来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "近来，最近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89ee32a3-3677-402a-8adc-801a9e813d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89048, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比来", "is_correct": true, "explanation": "正确：比来指近一段时间，“比来物价涨了不少”说近来物价的变化。"}, {"text": "即将", "is_correct": false, "explanation": "语义：“即将”表示将要发生，与“涨了不少”的已发生情况矛盾。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”只修饰形容词，不能放在主语“物价”之前。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”后接动作，不能与“涨了不少”这种已完成的变化搭配。"}], "explanations": {"比来": "正确：比来指近一段时间，“比来物价涨了不少”说近来物价的变化。", "即将": "语义：“即将”表示将要发生，与“涨了不少”的已发生情况矛盾。", "非常": "搭配：“非常”只修饰形容词，不能放在主语“物价”之前。", "正在": "搭配：“正在”后接动作，不能与“涨了不少”这种已完成的变化搭配。"}, "sentence_index": 0, "correct_answer": "比来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我父亲比来出生在农村。", "explanation": "这里把“比来”当成了〈以前〉用，但它只指近一段时间，不能用来说出生这种很久以前的事。"}, {"text": "明年我比来会去北京。", "explanation": "这里把“比来”当成了〈将来〉用，但它指近来，不能用来表示明年的计划。"}, {"text": "星期一比来开会。", "explanation": "这里把“比来”当成了〈某一天〉用，但它只指近一段时期，不能用于“星期一”这样具体的一天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比来", "is_correct": true, "explanation": "正确：比来指近一段时间，“我比来在学做饭”说近来在学做饭。"}, {"text": "将要", "is_correct": false, "explanation": "语义：“将要”表示尚未发生，与“已经会做三个菜了”的已完成情况矛盾。"}, {"text": "立即", "is_correct": false, "explanation": "搭配：“立即”表示马上，不能与“在学”这样持续的过程搭配。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“在学做饭”且“已经会做三个菜了”的事实矛盾。"}], "explanations": {"比来": "正确：比来指近一段时间，“我比来在学做饭”说近来在学做饭。", "将要": "语义：“将要”表示尚未发生，与“已经会做三个菜了”的已完成情况矛盾。", "立即": "搭配：“立即”表示马上，不能与“在学”这样持续的过程搭配。", "从不": "语义：“从不”表示从来没有，与“在学做饭”且“已经会做三个菜了”的事实矛盾。"}, "sentence_index": 6, "correct_answer": "比来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "太阳比来从东边升起。", "explanation": "这里把“比来”当成了〈总是〉用，但它只指近一段时间，不能用于太阳从东边升起这种长久不变的事实。"}, {"text": "去年比来下了很多雪。", "explanation": "这里把“比来”和“去年”放在一起，时间矛盾：“比来”只指近一段时间，不能指去年。"}, {"text": "比来，请你开门！", "explanation": "这里把“比来”当成了〈立刻〉用，但它只指近一段时间，不能表示立刻要做的命令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
