INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们比来过很少生病。", "corrected_sentence": "孩子们比来很少生病。", "error_description": "错误：“比来”后面多加了“过”。“比来”是表示时间的副词，后面不能加“过”，应去掉“过”，写成“孩子们比来很少生病”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
