INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89050, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遇见某人，与某人碰面。", "primary_collocate": null, "pronunciation": "jiàn dào", "ipa": "tɕjɛn˥˩ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "今天我在超市见到了老同学。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天你就能见到你的奶奶了。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很高兴见到你！", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想见到那位有名的作家。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在机场见到了多年没见的哥哥。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你见到王经理，请帮我问好。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了三个小时，才见到医生。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有见到过这位老师。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见到小李的时候，请告诉他我找他。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她见到我，笑着打了个招呼。", "target_word": "见到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "见到了", "label": "体标"}, {"form": "见到过", "label": "体标"}, {"form": "見到", "label": "繁体"}], "register": "中性", "sense_fingerprint": "见到：遇见某人，与某人碰面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8acff1a7-15ec-4016-88fb-91db472ff9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89050, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "见到", "is_correct": true, "explanation": "正确。见到指遇见某人，与某人碰面。"}, {"text": "捡到", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）只有声调不同，意思是从地上拿起（东西）。"}, {"text": "减到", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）只有声调不同，意思是减到（某个数量）。"}, {"text": "变到", "is_correct": false, "explanation": "biàn 与 jiàn 声母不同（b 与 j），意思是变到（某种状态）。"}], "explanations": {"见到": "正确。见到指遇见某人，与某人碰面。", "捡到": "jiǎn（第三声）与 jiàn（第四声）只有声调不同，意思是从地上拿起（东西）。", "减到": "jiǎn（第三声）与 jiàn（第四声）只有声调不同，意思是减到（某个数量）。", "变到": "biàn 与 jiàn 声母不同（b 与 j），意思是变到（某种状态）。"}, "sentence_index": null, "correct_answer": "见到"}, "level_3": {"options": [{"text": "见到", "is_correct": true, "explanation": "正确。句中说在超市遇见了老同学。"}, {"text": "买到", "is_correct": false, "explanation": "搭配：“买到”的对象是商品，老同学不能被买。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”的对象是易碎的器物，不能用来搭配“老同学”。"}, {"text": "搬走", "is_correct": false, "explanation": "搭配：“搬走”的对象多为物品，不能用来搭配“老同学”。"}], "explanations": {"见到": "正确。句中说在超市遇见了老同学。", "买到": "搭配：“买到”的对象是商品，老同学不能被买。", "打碎": "搭配：“打碎”的对象是易碎的器物，不能用来搭配“老同学”。", "搬走": "搭配：“搬走”的对象多为物品，不能用来搭配“老同学”。"}, "sentence_index": 0, "correct_answer": "见到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "走进花店，我见到一阵浓浓的玫瑰香。", "explanation": "这里应该用〈闻到〉。“见到”指遇见某人，不能用于气味；气味要用闻到。"}, {"text": "半夜里，我在床上见到远处传来的一阵狗叫声。", "explanation": "这里应该用〈听到〉。“见到”指遇见某人，不能用于声音；听声音要用听到。"}, {"text": "他摔倒后，见到右腿一阵剧痛。", "explanation": "这里应该用〈感到〉。身体的剧痛是一种感觉，要用感到，见到不能用于身体感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89050, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "见到", "is_correct": true, "explanation": "正确。见到指遇见某人，与某人碰面。"}, {"text": "交到", "is_correct": false, "explanation": "jiāo（第一声）与 jiàn（第四声）韵母不同（-iao 与 -ian），意思是交到（朋友）。"}, {"text": "剪到", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）只有声调不同，意思是用剪刀剪到（东西或手）。"}, {"text": "拣到", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）只有声调不同，意思是挑选出（东西）。"}, {"text": "点到", "is_correct": false, "explanation": "diǎn（第三声）与 jiàn 声母与声调都不同，意思是点到（为止）。"}], "explanations": {"见到": "正确。见到指遇见某人，与某人碰面。", "交到": "jiāo（第一声）与 jiàn（第四声）韵母不同（-iao 与 -ian），意思是交到（朋友）。", "剪到": "jiǎn（第三声）与 jiàn（第四声）只有声调不同，意思是用剪刀剪到（东西或手）。", "拣到": "jiǎn（第三声）与 jiàn（第四声）只有声调不同，意思是挑选出（东西）。", "点到": "diǎn（第三声）与 jiàn 声母与声调都不同，意思是点到（为止）。"}, "sentence_index": null, "correct_answer": "见到"}, "level_3": {"options": [{"text": "见到", "is_correct": true, "explanation": "正确。句中说他等了很久，终于遇见了医生。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”的对象是食物，医生不能被吃掉。"}, {"text": "请走", "is_correct": false, "explanation": "语义：“请走”指请人离开，与“等了三个小时才……”的等待语境矛盾。"}, {"text": "踢开", "is_correct": false, "explanation": "搭配：“踢开”的对象多为物体，不能用于“医生”。"}], "explanations": {"见到": "正确。句中说他等了很久，终于遇见了医生。", "吃掉": "语义：“吃掉”的对象是食物，医生不能被吃掉。", "请走": "语义：“请走”指请人离开，与“等了三个小时才……”的等待语境矛盾。", "踢开": "搭配：“踢开”的对象多为物体，不能用于“医生”。"}, "sentence_index": 6, "correct_answer": "见到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我咬了一口，见到了饼里的甜味。", "explanation": "这里应该用〈尝到〉。“见到”指遇见某人，不能用于味道；尝味道要用尝到。"}, {"text": "屋里很黑，我伸手见到一块冰凉的石头。", "explanation": "这里应该用〈摸到〉。用手接触到的东西要用摸到；“见到”指遇见某人，不能用于触觉。"}, {"text": "直到他提醒我，我才见到明天要交作业。", "explanation": "这里应该用〈想到〉。想起或意识到要做的事要用想到，见到不能用于这种想法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下午在车站很见到了李老师。", "corrected_sentence": "我下午在车站见到了李老师。", "error_description": "错误：“很”是程度副词，不能修饰“见到”这类动作动词，应去掉“很”。正确：“见到了李老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在车站不见到张经理。", "corrected_sentence": "我在车站没见到张经理。", "error_description": "“见到”表示已经发生或没有发生的事实，否定要用“没”，不能用“不”。错误：不见到；正确：没见到。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
