INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89051, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89051, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "维生素是食物里的好东西。吃了它，身体才会长得好、不容易生病。", "primary_collocate": null, "pronunciation": "wéi shēng sù", "ipa": "weɪ˧˥ ʂɤŋ˥ su˥˩", "syllable_count": 3, "sentences": [{"text": "孩子要多吃蔬菜，补充维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "柠檬里的维生素很多。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上喝一杯果汁补维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人需要补充维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果都有维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经常不吃蔬菜的人，容易缺乏维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天吃了一片维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我每天吃一片维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，维生素对身体好。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃维生素，身体会更好。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "維生素", "label": "繁体"}, {"form": "种", "label": "量词"}, {"form": "维生素C", "label": "复合"}], "register": "中性", "sense_fingerprint": "食物里对身体好、能防病的营养物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fb146-8ed8-4752-8994-0b2b95234267') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89051, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "维生素", "is_correct": true, "explanation": "正确：维生素是身体需要的营养物质，蔬菜之外还需要补充它。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不能吃，也不能用来补充身体需要的营养。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料不能食用，不是身体需要补充的东西。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“补充”多用于营养、能量、水分等，一般不说“补充空气”。"}], "explanations": {"维生素": "正确：维生素是身体需要的营养物质，蔬菜之外还需要补充它。", "汽油": "语义：汽油不能吃，也不能用来补充身体需要的营养。", "颜料": "语义：颜料不能食用，不是身体需要补充的东西。", "空气": "搭配：“补充”多用于营养、能量、水分等，一般不说“补充空气”。"}, "sentence_index": 0, "correct_answer": "维生素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种饮料含有丰富的钙和镁等维生素。", "explanation": "这里应该用〈矿物质〉。钙和镁属于矿物质，不是维生素，不能这样说。"}, {"text": "妈妈用维生素煮了一锅粥。", "explanation": "这里应该用〈大米〉。煮粥要用大米，维生素是营养物质，不能用来煮。"}, {"text": "他每天晚上都听维生素。", "explanation": "这里应该用〈音乐〉。“听”的对象是音乐、广播，维生素不能用“听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89051, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "维生素", "is_correct": true, "explanation": "正确：维生素可以用“片”来计量，我今天吃的就是一片维生素。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能吃，吃下去会伤害身体。"}, {"text": "肥皂", "is_correct": false, "explanation": "语义：肥皂不能吃，吃下去会伤害身体。"}, {"text": "木板", "is_correct": false, "explanation": "语义：木板是建材，不能吃。"}], "explanations": {"维生素": "正确：维生素可以用“片”来计量，我今天吃的就是一片维生素。", "玻璃": "语义：玻璃不能吃，吃下去会伤害身体。", "肥皂": "语义：肥皂不能吃，吃下去会伤害身体。", "木板": "语义：木板是建材，不能吃。"}, "sentence_index": 6, "correct_answer": "维生素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的爱好是维生素。", "explanation": "这里应该用〈画画〉。爱好要说画画、唱歌之类的活动，维生素不是活动。"}, {"text": "他把钥匙放进维生素里。", "explanation": "这里应该用〈口袋〉。钥匙要放进口袋、包里，维生素不能当容器装东西。"}, {"text": "下雨了，她撑着维生素。", "explanation": "这里应该用〈伞〉。下雨时撑的是伞，维生素不能撑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子每天吃一条维生素。", "corrected_sentence": "孩子每天吃一片维生素。", "error_description": "量词错误：“条”用于细长的东西，维生素片应该用“片”。正确说法是“一片维生素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈买了两只维生素。", "corrected_sentence": "妈妈买了两瓶维生素。", "error_description": "量词错误：“只”多用于动物，装在瓶里的维生素应该用“瓶”。正确说法是“两瓶维生素”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
