INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89052, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人体维持正常生长和代谢所必需的微量有机物，须从食物中摄取。", "primary_collocate": null, "pronunciation": "wéi shēng sù", "ipa": "weɪ˧˥ ʂɤŋ˥ su˥˩", "syllable_count": 3, "sentences": [{"text": "水果里有很多维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我每天要吃一点维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "维生素对皮肤很好。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她缺少维生素，所以脸色不好。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橙子里的维生素特别多。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩不吃蔬菜，会缺维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了一瓶维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多吃青菜，身体就能得到维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种果汁含有丰富的维生素。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "维生素不能代替正常吃饭。", "target_word": "维生素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "維生素", "label": "繁体"}, {"form": "种", "label": "量词"}, {"form": "维生素C", "label": "复合"}], "register": "中性", "sense_fingerprint": "人体必需、须从食物摄取的微量有机物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f98fb146-8ed8-4752-8994-0b2b95234267') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "维生素", "is_correct": true, "explanation": "正确：维生素是食物中的微量营养物质，水果里含有很多维生素。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是水果里的东西，与“水果里有很多”不符。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料用于绘画，不会存在于水果里。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是水果里含有的营养，不能说“水果里有很多空气”来表示营养。"}], "explanations": {"维生素": "正确：维生素是食物中的微量营养物质，水果里含有很多维生素。", "汽油": "语义：汽油是燃料，不是水果里的东西，与“水果里有很多”不符。", "颜料": "语义：颜料用于绘画，不会存在于水果里。", "空气": "语义：空气不是水果里含有的营养，不能说“水果里有很多空气”来表示营养。"}, "sentence_index": 0, "correct_answer": "维生素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种饮料含有丰富的铁和锌等维生素。", "explanation": "这里应该用〈矿物质〉。铁和锌属于矿物质，维生素是有机物，不能把它们说成维生素。"}, {"text": "这碗粥是用维生素煮的。", "explanation": "这里应该用〈大米〉。煮粥用的是大米等食材，维生素是营养物质，不能用来煮。"}, {"text": "学生们在操场上踢维生素。", "explanation": "这里应该用〈足球〉。“踢”的对象是足球，维生素不能用脚踢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "维生素", "is_correct": true, "explanation": "正确：“一瓶”可以装维生素，妈妈买给我的是维生素。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪是从眼睛流出的液体，不是买来的东西。"}, {"text": "白云", "is_correct": false, "explanation": "语义：白云在天空中，不能买来装进瓶子里。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星在天上，不能买来装进瓶子里。"}], "explanations": {"维生素": "正确：“一瓶”可以装维生素，妈妈买给我的是维生素。", "眼泪": "语义：眼泪是从眼睛流出的液体，不是买来的东西。", "白云": "语义：白云在天空中，不能买来装进瓶子里。", "星星": "语义：星星在天上，不能买来装进瓶子里。"}, "sentence_index": 6, "correct_answer": "维生素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都要洗维生素。", "explanation": "这里应该用〈脸〉。“洗”的对象是脸、衣服等，维生素不能用来洗。"}, {"text": "我哥哥的职业是维生素。", "explanation": "这里应该用〈医生〉。职业要说医生、老师之类，维生素不是职业。"}, {"text": "他把书放在维生素上。", "explanation": "这里应该用〈书架〉。书要放在书架或桌子上，维生素不能用来放书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天吃一根维生素。", "corrected_sentence": "我每天吃一片维生素。", "error_description": "量词错误：“根”用于细长的东西，维生素片应该用“片”。正确说法是“一片维生素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了两瓶的维生素。", "corrected_sentence": "我买了两瓶维生素。", "error_description": "多余的“的”：数量短语和名词之间不用“的”，应说“两瓶维生素”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90060b4a-bdd3-4034-b6f9-86afcd4ef97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
