INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89055, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "认真是做事很用心,不马虎。", "primary_collocate": null, "pronunciation": "rèn zhēn", "ipa": "ɻən˥˩ ʈʂən˥", "syllable_count": 2, "sentences": [{"text": "他做作业总是很认真。", "target_word": "认真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈认真地做了一桌菜。", "target_word": "认真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家认真听我说。", "target_word": "认真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她工作认真，同事都喜欢她。", "target_word": "认真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认真学了一年汉语。", "target_word": "认真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生看病特别认真。", "target_word": "认真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组的同学讨论问题都很认真。", "target_word": "认真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子认真画了一张画。", "target_word": "认真", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我会认真考虑你的建议。", "target_word": "认真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认真起来的时候，谁也比不上。", "target_word": "认真", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "認真", "label": "繁体"}, {"form": "认认真真", "label": "重叠"}], "register": "中性", "sense_fingerprint": "做事用心、不敷衍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '216324cd-0d1f-4db4-b00d-b0895e448e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89055, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认真", "is_correct": true, "explanation": "“认真”表示做事用心，与“做作业总是很”相合。"}, {"text": "宽广", "is_correct": false, "explanation": "搭配：“宽广”形容空间或胸怀，不用来形容做作业。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能用来形容做作业的态度。"}, {"text": "圆满", "is_correct": false, "explanation": "语义：“圆满”指事情顺利完成的结果，不是做事用心的状态。"}], "explanations": {"认真": "“认真”表示做事用心，与“做作业总是很”相合。", "宽广": "搭配：“宽广”形容空间或胸怀，不用来形容做作业。", "响亮": "搭配：“响亮”形容声音，不能用来形容做作业的态度。", "圆满": "语义：“圆满”指事情顺利完成的结果，不是做事用心的状态。"}, "sentence_index": 0, "correct_answer": "认真"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河很认真。", "explanation": "这里应该用〈平静〉。“认真”形容人做事的态度，不能用来形容河流。"}, {"text": "会议室里的气氛很认真。", "explanation": "这里应该用〈严肃〉。“认真”用于人的做事态度，不能用来形容气氛。"}, {"text": "他认真地忘了带钥匙。", "explanation": "这里应该用〈无意〉。“认真地”表示用心做事，忘带东西是无意的，不能与“认真地”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89055, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认真", "is_correct": true, "explanation": "“认真”表示做事用心，与“讨论问题都很”相合。"}, {"text": "亲切", "is_correct": false, "explanation": "搭配：“亲切”形容待人的态度，不用来形容讨论问题。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能用来形容讨论问题。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”形容草原、海洋等空间宽广，不能用来形容讨论问题的态度。"}], "explanations": {"认真": "“认真”表示做事用心，与“讨论问题都很”相合。", "亲切": "搭配：“亲切”形容待人的态度，不用来形容讨论问题。", "明亮": "搭配：“明亮”形容光线或颜色，不能用来形容讨论问题。", "辽阔": "搭配：“辽阔”形容草原、海洋等空间宽广，不能用来形容讨论问题的态度。"}, "sentence_index": 6, "correct_answer": "认真"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真地摔了一跤。", "explanation": "这里应该用〈不小心〉。“认真”表示用心做事，摔跤是无意的，不能与“认真地”搭配。"}, {"text": "这间房子很认真。", "explanation": "这里应该用〈整洁〉。“认真”形容人的做事态度，不能用来形容房子。"}, {"text": "他认真地睡着了。", "explanation": "这里应该用〈不知不觉〉。睡着是无意识的，不能用“认真地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89055, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项工作他做很认真。", "corrected_sentence": "这项工作他做得很认真。", "error_description": "“做”后面的程度补语要用“得”。“做很认真”缺少“得”，应为“做得很认真”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89055, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子画画很认真地。", "corrected_sentence": "孩子画画很认真。", "error_description": "“认真”是形容词，作谓语时后面不加“地”。“很认真地”后面没有动词，应为“很认真”，删去“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
