INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89057, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网络应用是上网才能用的软件或服务。", "primary_collocate": null, "pronunciation": "wǎng luò yìng yòng", "ipa": "wɑŋ˨˩˦ luo˥˩ iŋ˥˩ yŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这个网络应用可以在手机上用。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有网，这个网络应用就打不开。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天用一个网络应用记账。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网络应用能帮你和朋友视频聊天。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们下载一个学中文的网络应用。", "target_word": "网络应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网络应用免费，不用花钱。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做了一个网络应用，帮人订电影票。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络应用要上网才能用。", "target_word": "网络应用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的手机里有很多网络应用。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网络应用的界面很简单，老人也会用。", "target_word": "网络应用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个网络应用", "label": "量词"}, {"form": "網絡應用", "label": "繁体"}, {"form": "网络应用程序", "label": "复合"}], "register": "中性", "sense_fingerprint": "要上网才能使用的软件或服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b548b9fd-667e-4dfa-a4aa-a6d0806d1b3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89057, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网络应用", "is_correct": true, "explanation": "正确。网络应用是靠网络运行的软件，可以在手机上用。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物是吃的东西，不能安装在手机上运行。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“在手机上用”的对象应是软件或设备，不能说“在手机上用桌子”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的实物，与“在手机上用”无关。"}], "explanations": {"网络应用": "正确。网络应用是靠网络运行的软件，可以在手机上用。", "食物": "语义：食物是吃的东西，不能安装在手机上运行。", "桌子": "搭配：“在手机上用”的对象应是软件或设备，不能说“在手机上用桌子”。", "雨伞": "语义：雨伞是遮雨的实物，与“在手机上用”无关。"}, "sentence_index": 0, "correct_answer": "网络应用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把网络应用放进了书包里。", "explanation": "这里应该用“光盘”。网络应用是上网才能用的程序或服务，没有实体，不能放进书包；放进书包的是光盘。"}, {"text": "我每天早上用网络应用刷牙。", "explanation": "这里应该用“牙刷”。网络应用是程序或服务，不能用来刷牙；刷牙要用牙刷。"}, {"text": "这个网络应用很保温，能放一整天的水。", "explanation": "这里应该用“水杯”。网络应用是程序或服务，没有实体，不能保温，也不能装水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网络应用", "is_correct": true, "explanation": "正确。“做了一个网络应用”指开发出的程序，能帮人订电影票。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，做出来不能帮人订电影票。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：朋友是人，不能被“做”出来用来订电影票，句子说不通。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是插花用的器物，不能用来订电影票。"}], "explanations": {"网络应用": "正确。“做了一个网络应用”指开发出的程序，能帮人订电影票。", "饺子": "语义：饺子是食物，做出来不能帮人订电影票。", "朋友": "语义：朋友是人，不能被“做”出来用来订电影票，句子说不通。", "花瓶": "语义：花瓶是插花用的器物，不能用来订电影票。"}, "sentence_index": 6, "correct_answer": "网络应用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个网络应用很好吃，我每天都买来当早饭。", "explanation": "这里应该用“面包”。网络应用是上网才能用的程序或服务，不能吃，也不能当早饭。"}, {"text": "这个网络应用跑得很快，我们坐它去公司。", "explanation": "这里应该用“出租车”。网络应用不是交通工具，不能用来坐。"}, {"text": "这个网络应用很暖和，冬天穿着它出门。", "explanation": "这里应该用“毛衣”。网络应用没有实体，不能穿，也不能保暖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下载了一台网络应用，很好用。", "corrected_sentence": "我下载了一个网络应用，很好用。", "error_description": "量词错误：“网络应用”应用量词“个”，不用“台”。“台”多用于机器、设备，网络应用是程序。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我下载了一个网络应用们，很好用。", "corrected_sentence": "我下载了一个网络应用，很好用。", "error_description": "复数标记错误：“们”只用于指人的名词，“网络应用”后不能加“们”，应说“一个网络应用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
