INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "依托互联网运行并提供服务的程序或软件。", "primary_collocate": null, "pronunciation": "wǎng luò yìng yòng", "ipa": "wɑŋ˨˩˦ luo˥˩ iŋ˥˩ yŋ˥˩", "syllable_count": 4, "sentences": [{"text": "现在很多银行都有自己的网络应用。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网络应用靠服务器运行。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司新做了一个网络应用，客户可以在线订餐。", "target_word": "网络应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网络应用每天有一百万人使用。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以用这个网络应用查公交车到站时间。", "target_word": "网络应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络不好时，这个网络应用会很慢。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网络应用有电脑版，也有手机版。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院的网络应用让病人在家就能挂号。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校用一个网络应用交作业。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网络应用更新后，功能多了。", "target_word": "网络应用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个网络应用", "label": "量词"}, {"form": "網絡應用", "label": "繁体"}, {"form": "网络应用程序", "label": "复合"}], "register": "中性", "sense_fingerprint": "依靠互联网运行、提供服务的程序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b548b9fd-667e-4dfa-a4aa-a6d0806d1b3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网络应用", "is_correct": true, "explanation": "正确。网络应用是依托互联网提供服务的程序，银行可以有自己的网络应用。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是穿的东西，与银行提供的服务无关，句子说不通。"}, {"text": "粥", "is_correct": false, "explanation": "语义：粥是食物，不是银行提供的服务，句子说不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“有自己的”搭配的是服务或机构，不说“有自己的空气”。"}], "explanations": {"网络应用": "正确。网络应用是依托互联网提供服务的程序，银行可以有自己的网络应用。", "鞋子": "语义：鞋子是穿的东西，与银行提供的服务无关，句子说不通。", "粥": "语义：粥是食物，不是银行提供的服务，句子说不通。", "空气": "搭配：“有自己的”搭配的是服务或机构，不说“有自己的空气”。"}, "sentence_index": 0, "correct_answer": "网络应用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个网络应用每天有一百万人来吃饭。", "explanation": "这里应该用“餐厅”。网络应用是程序，不能让人“来吃饭”。"}, {"text": "这个网络应用每天有一百万人来散步。", "explanation": "这里应该用“公园”。网络应用是程序或服务，人不会“来散步”。"}, {"text": "这个网络应用每天有一百万辆车停放。", "explanation": "这里应该用“停车场”。网络应用是上网才能用的程序或服务，不能用来停车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网络应用", "is_correct": true, "explanation": "正确。“电脑版”“手机版”是同一程序的不同版本，网络应用可以有这些版本。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不会有“电脑版”和“手机版”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不能说有“电脑版”和“手机版”。"}, {"text": "菜", "is_correct": false, "explanation": "搭配：“版”多用于软件或程序，不说“菜有电脑版”。"}], "explanations": {"网络应用": "正确。“电脑版”“手机版”是同一程序的不同版本，网络应用可以有这些版本。", "水果": "语义：水果是食物，不会有“电脑版”和“手机版”。", "老师": "语义：老师是人，不能说有“电脑版”和“手机版”。", "菜": "搭配：“版”多用于软件或程序，不说“菜有电脑版”。"}, "sentence_index": 6, "correct_answer": "网络应用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个网络应用很结实，能装十本书。", "explanation": "这里应该用“书包”。网络应用没有实体，不能用来装书。"}, {"text": "这个网络应用跑得很快，我骑它去上班。", "explanation": "这里应该用“自行车”。网络应用不是交通工具，不能用来骑。"}, {"text": "这个网络应用很厚，能挡风挡雨。", "explanation": "这里应该用“雨衣”。网络应用没有实体，不能挡风挡雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校买了一台网络应用。", "corrected_sentence": "我们学校买了一个网络应用。", "error_description": "量词错误：“网络应用”是程序，应用量词“个”或“款”，不用“台”。“台”多用于机器、设备。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天用一个网络应用们学汉字。", "corrected_sentence": "我每天用一个网络应用学汉字。", "error_description": "复数标记错误：“们”只用于指人的名词，“网络应用”后不能加“们”，应说“一个网络应用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
