INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89062, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把事情告诉有关的人。", "primary_collocate": null, "pronunciation": "tōng zhī", "ipa": "tʰʊŋ˥ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "老师通知我们明天早上八点开会。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司通知他下周一去上班。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校已经通知了所有的家长。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你通知大家，会议改到下午三点。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院打电话通知我去取检查结果。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还没有通知我比赛的时间。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把新的时间通知了大家。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东通知我们月底搬家。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是有事，请提前通知我。", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁通知你今天不上课的？", "target_word": "通知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "通知了", "label": "体标"}, {"form": "通知过", "label": "体标"}, {"form": "通知书", "label": "复合"}], "register": "中性", "sense_fingerprint": "通知:把事情告诉有关的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a2d37c5-ce5a-420d-8d73-ab1cf9e08d40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89062, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通知", "is_correct": true, "explanation": "通知：把事情告诉有关的人，是本次听辨的目标词。"}, {"text": "同志", "is_correct": false, "explanation": "tóngzhì（第二声）与 tōngzhī（第一声）声调不同，意思是志同道合的人。"}, {"text": "同时", "is_correct": false, "explanation": "shí 与 zhī 声母不同（sh 与 zh）且声调不同，意思是在同一时间。"}, {"text": "统治", "is_correct": false, "explanation": "tǒngzhì 与 tōngzhī 两个音节的声调都不同，意思是支配、管理。"}, {"text": "同事", "is_correct": false, "explanation": "shì 与 zhī 声母不同（sh 与 zh），意思是一起工作的人。"}, {"text": "通识", "is_correct": false, "explanation": "shí 与 zhī 声母不同（sh 与 zh）且声调不同，意思是普遍的知识。"}], "explanations": {"通知": "通知：把事情告诉有关的人，是本次听辨的目标词。", "同志": "tóngzhì（第二声）与 tōngzhī（第一声）声调不同，意思是志同道合的人。", "同时": "shí 与 zhī 声母不同（sh 与 zh）且声调不同，意思是在同一时间。", "统治": "tǒngzhì 与 tōngzhī 两个音节的声调都不同，意思是支配、管理。", "同事": "shì 与 zhī 声母不同（sh 与 zh），意思是一起工作的人。", "通识": "shí 与 zhī 声母不同（sh 与 zh）且声调不同，意思是普遍的知识。"}, "sentence_index": null, "correct_answer": "通知"}, "level_3": {"options": [{"text": "通知", "is_correct": true, "explanation": "通知：把事情告诉大家，与“明天早上八点开会”的告知语境相符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是责备，与“告知开会时间”的语境不符。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”要带话题或事件，不能直接接“我们明天早上八点开会”。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与开会时间的告知不相干。"}], "explanations": {"通知": "通知：把事情告诉大家，与“明天早上八点开会”的告知语境相符。", "批评": "语义：“批评”是责备，与“告知开会时间”的语境不符。", "讨论": "搭配：“讨论”要带话题或事件，不能直接接“我们明天早上八点开会”。", "表扬": "语义：“表扬”是称赞，与开会时间的告知不相干。"}, "sentence_index": 0, "correct_answer": "通知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直在通知天气很冷。", "explanation": "这里应该用〈抱怨〉。“通知”用于告诉别人事情，抱怨天气要用“抱怨”，“通知天气”不通。"}, {"text": "我向她通知了心意。", "explanation": "这里应该用〈表白〉。表达心意要用“表白”，“通知”只用于告知事情或安排。"}, {"text": "我要通知大家的帮助。", "explanation": "这里应该用〈感谢〉。表达谢意要用“感谢”，“通知”不能接“帮助”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通知", "is_correct": true, "explanation": "通知：把事情告诉大家，与“把新的时间”的告知语境相符。"}, {"text": "分享", "is_correct": false, "explanation": "配价：“分享”的接受者要用“给”引出，不能直接接“大家”。"}, {"text": "宣传", "is_correct": false, "explanation": "搭配：“宣传”的对象是事物或观点，“宣传大家”不通。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是夸奖，与告知“新的时间”不相干。"}], "explanations": {"通知": "通知：把事情告诉大家，与“把新的时间”的告知语境相符。", "分享": "配价：“分享”的接受者要用“给”引出，不能直接接“大家”。", "宣传": "搭配：“宣传”的对象是事物或观点，“宣传大家”不通。", "赞美": "语义：“赞美”是夸奖，与告知“新的时间”不相干。"}, "sentence_index": 6, "correct_answer": "通知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想通知你的意见。", "explanation": "这里应该用〈询问〉。询问意见要用“询问”，“通知”用于告知事情，不能接“意见”。"}, {"text": "他通知了我一会儿。", "explanation": "这里应该用〈安慰〉。安慰他人要用“安慰”，“通知”不能表达这种安慰的动作。"}, {"text": "大家通知她的才华。", "explanation": "这里应该用〈赞美〉。称赞才华要用“赞美”，“通知”不能接“才华”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前通知他过。", "corrected_sentence": "我以前通知过他。", "error_description": "错误在于“过”的位置。“过”表示曾经做过，要紧跟动词，应说“通知过他”，不能放在宾语“他”的后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师没通知了我们今天放假。", "corrected_sentence": "老师没通知我们今天放假。", "error_description": "错误在于“没”和“了”同时出现。“没”否定已经发生的动作，动词后不能再加“了”，应说“没通知我们”，不能说“没通知了我们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2750e488-58c4-4d37-9494-4900c791cdc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
