INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89063, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网络设备是让很多电脑能连上网的机器。", "primary_collocate": null, "pronunciation": "wǎng luò shè bèi", "ipa": "u̯ɑŋ˨˩˦ lu̯ɔ˥˩ ʂɤ˥˩ pei̯˥˩", "syllable_count": 4, "sentences": [{"text": "公司买了很多新的网络设备。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络设备坏了，我们不能上网。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间教室里有一台网络设备。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作是检查学校的网络设备。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络设备放在二楼的小房间里。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的网络设备太旧，网速很慢。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把网络设备的电源关上。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里的网络设备让大家都能上网。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店卖各种网络设备。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新网络设备装好以后，网速快多了。", "target_word": "网络设备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}], "register": "中性", "sense_fingerprint": "让很多电脑能连上网的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4db7646-0948-40ca-93a1-22bf840509fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89063, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感情", "is_correct": false, "explanation": "搭配：“买”不能搭配抽象的“感情”，不能说“买了很多新的感情”。"}, {"text": "网络设备", "is_correct": true, "explanation": "正确：“网络设备”是可以购买的新机器，符合“买了很多新的”的语境。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”是人，不是可以买的东西，与句意不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”是自然存在的，不是可以“买”来的新东西，句子不通。"}], "explanations": {"感情": "搭配：“买”不能搭配抽象的“感情”，不能说“买了很多新的感情”。", "网络设备": "正确：“网络设备”是可以购买的新机器，符合“买了很多新的”的语境。", "病人": "语义：“病人”是人，不是可以买的东西，与句意不符。", "空气": "语义：“空气”是自然存在的，不是可以“买”来的新东西，句子不通。"}, "sentence_index": 0, "correct_answer": "网络设备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的工作是检查学校的一只网络设备。", "explanation": "这里应该用〈台〉。“只”多用于动物，“网络设备”是机器，要用量词“台”。"}, {"text": "学校新买了一本网络设备。", "explanation": "这里应该用〈台〉。“本”用于书籍、本子，“网络设备”是机器，要用量词“台”。"}, {"text": "老师把一张网络设备放在桌子上。", "explanation": "这里应该用〈台〉。“张”用于平面的东西，“网络设备”是机器，要用量词“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89063, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户一般没有电源，不能对它“关电源”，句子不通。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“电源”指用电的设备，“水”不能搭配“关电源”。"}, {"text": "网络设备", "is_correct": true, "explanation": "正确：“网络设备”有电源，可以关掉，符合句意。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”是人，没有电源，不能“关电源”。"}], "explanations": {"窗户": "语义：窗户一般没有电源，不能对它“关电源”，句子不通。", "水": "搭配：“电源”指用电的设备，“水”不能搭配“关电源”。", "网络设备": "正确：“网络设备”有电源，可以关掉，符合句意。", "老师": "语义：“老师”是人，没有电源，不能“关电源”。"}, "sentence_index": 6, "correct_answer": "网络设备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天听网络设备。", "explanation": "这里应该用〈音乐〉。“听”用于音乐、广播等声音，网络设备是硬件，不能听。"}, {"text": "请在地址栏输入网络设备。", "explanation": "这里应该用〈网址〉。“输入”用于网址、文字，网络设备是硬件，不能输入到地址栏。"}, {"text": "他在网络设备上认识了很多好朋友。", "explanation": "这里的“网络”指互联网上的社交或人际关系，“网络设备”只指硬件，不能用来结交朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89063, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校昨天又买了一只网络设备。", "corrected_sentence": "学校昨天又买了一台网络设备。", "error_description": "量词错误：“网络设备”是机器，应用量词“台”。“只”多用于动物，用在这里不对，正确说法是“一台网络设备”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89063, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们昨天终于装好了一网络设备。", "corrected_sentence": "他们昨天终于装好了一台网络设备。", "error_description": "量词缺失：“网络设备”是可数的机器，数词“一”后要加量词“台”，不能说“一网络设备”，应说“一台网络设备”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
