INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89066, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "清楚地了解；知道得很详细。", "primary_collocate": null, "pronunciation": "shú xī", "ipa": "ʂu˧˥ ɕi˥", "syllable_count": 2, "sentences": [{"text": "他很熟悉公司的工作流程。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新员工要先熟悉业务。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生熟悉这种药的用法。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师熟悉中国历史。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，请大家熟悉一下资料。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我熟悉这个软件的所有功能。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师熟悉相关的法律。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她熟悉每道菜的做法。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先熟悉规则，再参加比赛。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对棋谱很熟悉。", "target_word": "熟悉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "熟悉了", "label": "体标"}, {"form": "熟悉过", "label": "体标"}], "register": "中性", "sense_fingerprint": "对事物、业务了解得清楚详细", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b474a69-16b8-4d65-b10a-8b191cf12514') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熟悉", "is_correct": true, "explanation": "正确：“很熟悉公司的工作流程”表示了解得清楚，符合句意。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”是行为动词，不能受“很”修饰。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”指同意核准，与了解程度无关。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”是行为动作，不能受“很”修饰。"}], "explanations": {"熟悉": "正确：“很熟悉公司的工作流程”表示了解得清楚，符合句意。", "拒绝": "搭配：“拒绝”是行为动词，不能受“很”修饰。", "批准": "语义：“批准”指同意核准，与了解程度无关。", "讨论": "搭配：“讨论”是行为动作，不能受“很”修饰。"}, "sentence_index": 0, "correct_answer": "熟悉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他熟悉红色。", "explanation": "这里应该用〈喜欢〉。熟悉表示了解得清楚，不表示喜爱。"}, {"text": "他熟悉了这种快乐，每天都在笑。", "explanation": "这里应该用〈感到〉。熟悉的对象是人、地方或事务，不指一种情绪。"}, {"text": "他熟悉了好成绩。", "explanation": "这里应该用〈取得〉。熟悉的对象是人、地方或事务，不能与“成绩”这类结果搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熟悉", "is_correct": true, "explanation": "正确：“律师熟悉相关的法律”表示了解得清楚，符合句意。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”的对象是动物，不能用于法律。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”的对象是枝叶，不说修剪法律。"}, {"text": "播种", "is_correct": false, "explanation": "语义：“播种”指撒播种子，与法律无关。"}], "explanations": {"熟悉": "正确：“律师熟悉相关的法律”表示了解得清楚，符合句意。", "饲养": "语义：“饲养”的对象是动物，不能用于法律。", "修剪": "搭配：“修剪”的对象是枝叶，不说修剪法律。", "播种": "语义：“播种”指撒播种子，与法律无关。"}, "sentence_index": 6, "correct_answer": "熟悉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他熟悉了这场大雪，马上关上了门。", "explanation": "这里应该用〈看到〉。熟悉的对象是人、地方或事务，不指看到自然现象。"}, {"text": "他熟悉了这次地震，只好躲在桌子下面。", "explanation": "这里应该用〈遭遇〉。熟悉的对象是人、地方或事务，不指遭遇突发的地震。"}, {"text": "他熟悉了花瓶，很后悔。", "explanation": "这里应该用〈打碎〉。熟悉指对人、地方或事务了解清楚，不指损坏某物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跟这份工作很熟悉。", "corrected_sentence": "他对这份工作很熟悉。", "error_description": "介词误用：表示对事务了解时应说“对……很熟悉”，“跟……熟悉”多用于人与人之间，不能说“跟这份工作很熟悉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这套软件熟悉地很快。", "corrected_sentence": "他对这套软件熟悉得很快。", "error_description": "结构助词误用：“熟悉”后引出补语应用“得”，“地”只用于状语，应说“熟悉得很快”，不能说“熟悉地很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cc55e70-e468-438e-b1bf-98f6a2d873a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89067, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89067, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89067, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "过人是比一般人还要强。", "primary_collocate": null, "pronunciation": "guò rén", "ipa": "kuo˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他的记忆力过人，什么都记得住。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生胆识过人。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就聪明过人。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师的耐心过人，从不发火。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他力气过人，一个人搬起了大桌子。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的本领过人，大家都很佩服。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子的音乐天分过人。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在比赛中表现出过人的勇气。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼力过人，一眼就看出了问题。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的精力过人，天天工作到很晚。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过人之处", "label": "复合"}], "register": "中性", "sense_fingerprint": "能力、品质比一般人还要强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df93761e-3099-453a-be8c-fa0da9ef77d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89067, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "过人", "is_correct": true, "explanation": "正确。过人读 guò rén，意思是超过一般人。"}, {"text": "国人", "is_correct": false, "explanation": "guó（第二声）与 guò（第四声）声调不同，国人意思是中国人、同胞。"}, {"text": "果仁", "is_correct": false, "explanation": "guǒ（第三声）与 guò（第四声）声调不同，果仁指果实里面的仁儿。"}, {"text": "阔人", "is_correct": false, "explanation": "kuò 与 guò 声母不同（k 与 g），阔人指有钱有势的人。"}, {"text": "过门", "is_correct": false, "explanation": "mén（第二声）与 rén（第二声）声母不同，过门指旧时女子出嫁到夫家。"}, {"text": "故人", "is_correct": false, "explanation": "gù 与 guò 韵母不同（u 与 uo），故人指老朋友。"}], "explanations": {"过人": "正确。过人读 guò rén，意思是超过一般人。", "国人": "guó（第二声）与 guò（第四声）声调不同，国人意思是中国人、同胞。", "果仁": "guǒ（第三声）与 guò（第四声）声调不同，果仁指果实里面的仁儿。", "阔人": "kuò 与 guò 声母不同（k 与 g），阔人指有钱有势的人。", "过门": "mén（第二声）与 rén（第二声）声母不同，过门指旧时女子出嫁到夫家。", "故人": "gù 与 guò 韵母不同（u 与 uo），故人指老朋友。"}, "sentence_index": null, "correct_answer": "过人"}, "level_3": {"options": [{"text": "过人", "is_correct": true, "explanation": "正确。过人表示超过一般人，与后半句“什么都记得住”相符。"}, {"text": "差", "is_correct": false, "explanation": "语义：“差”表示能力弱，与“什么都记得住”正相反。"}, {"text": "健忘", "is_correct": false, "explanation": "语义：“健忘”指容易忘事，与“什么都记得住”矛盾。"}, {"text": "平凡", "is_correct": false, "explanation": "搭配：“平凡”说人或事普通，一般不用来形容记忆力的强弱。"}], "explanations": {"过人": "正确。过人表示超过一般人，与后半句“什么都记得住”相符。", "差": "语义：“差”表示能力弱，与“什么都记得住”正相反。", "健忘": "语义：“健忘”指容易忘事，与“什么都记得住”矛盾。", "平凡": "搭配：“平凡”说人或事普通，一般不用来形容记忆力的强弱。"}, "sentence_index": 0, "correct_answer": "过人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的缺点过人，大家都知道。", "explanation": "这里应该用〈突出〉。过人只形容能力、品质等正面的优点，不能用来说缺点。"}, {"text": "这个方案的设计很过人，评委都很满意。", "explanation": "这里应该用〈出色〉。过人形容人的能力、品质，不能用来形容方案的设计这类成果。"}, {"text": "今天的天气过人，大家都出去玩了。", "explanation": "这里应该用〈好〉。过人形容人的能力、品质，不能用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89067, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过人", "is_correct": true, "explanation": "正确。过人表示超过一般人，与“音乐天分”的褒义语境相符。"}, {"text": "虚弱", "is_correct": false, "explanation": "语义：“虚弱”形容身体状态，与“音乐天分”无关，也不能说天分的高低。"}, {"text": "枯燥", "is_correct": false, "explanation": "语义：“枯燥”指内容单调乏味，不能用来形容天分。"}, {"text": "呆滞", "is_correct": false, "explanation": "体貌：“呆滞”多形容眼神、表情，不用来形容天分。"}], "explanations": {"过人": "正确。过人表示超过一般人，与“音乐天分”的褒义语境相符。", "虚弱": "语义：“虚弱”形容身体状态，与“音乐天分”无关，也不能说天分的高低。", "枯燥": "语义：“枯燥”指内容单调乏味，不能用来形容天分。", "呆滞": "体貌：“呆滞”多形容眼神、表情，不用来形容天分。"}, "sentence_index": 6, "correct_answer": "过人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次胜利的意义过人。", "explanation": "这里应该用〈非凡〉。过人只形容人的能力、品质，不能用来说事情的意义。"}, {"text": "这座大楼的外观过人，一眼就能看见。", "explanation": "这里应该用〈醒目〉。过人形容人的能力或品质，不能用来形容建筑的外观。"}, {"text": "这项改革的效果过人，大家都看到了。", "explanation": "这里应该用〈显著〉。过人不能用来形容改革的效果这类事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89067, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有过人地体力，能扛起一百斤的米袋。", "corrected_sentence": "他有过人的体力，能扛起一百斤的米袋。", "error_description": "错误：“过人”修饰名词“体力”时要用“的”，不能用“地”（“地”用于修饰动词或形容词作状语）。应改为“过人的体力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89067, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他身上有不少过人的之处，大家都很佩服。", "corrected_sentence": "他身上有不少过人之处，大家都很佩服。", "error_description": "错误：“过人之处”是固定的复合词，“之”已表示“……的地方”，后面不能再加“的”。应改为“过人之处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
