INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89068, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "超过一般人的。", "primary_collocate": null, "pronunciation": "guò rén", "ipa": "kuo˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他有过人的本事。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小女孩有过人的才华。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的胆量过人，敢一个人走夜路。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队靠着过人的速度赢了比赛。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有过人之处，大家都愿意听他的。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板有过人的眼光，选对了地方。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员的体力过人。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的记性过人，看一遍就会了。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成功的人往往有过人的毅力。", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么过人之处吗？", "target_word": "过人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过人之处", "label": "复合"}], "register": "中性", "sense_fingerprint": "修饰才能、品质，指超过一般人的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df93761e-3099-453a-be8c-fa0da9ef77d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89068, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "过人", "is_correct": true, "explanation": "正确。过人读 guò rén，意思是超过一般人的。"}, {"text": "国人", "is_correct": false, "explanation": "guó（第二声）与 guò（第四声）声调不同，国人意思是中国人、同胞。"}, {"text": "果仁", "is_correct": false, "explanation": "guǒ（第三声）与 guò（第四声）声调不同，果仁指果实里面的仁儿。"}, {"text": "阔人", "is_correct": false, "explanation": "kuò 与 guò 声母不同（k 与 g），阔人指有钱有势的人。"}, {"text": "过门", "is_correct": false, "explanation": "mén（第二声）与 rén（第二声）声母不同，过门指旧时女子出嫁到夫家。"}, {"text": "故人", "is_correct": false, "explanation": "gù 与 guò 韵母不同（u 与 uo），故人指老朋友。"}], "explanations": {"过人": "正确。过人读 guò rén，意思是超过一般人的。", "国人": "guó（第二声）与 guò（第四声）声调不同，国人意思是中国人、同胞。", "果仁": "guǒ（第三声）与 guò（第四声）声调不同，果仁指果实里面的仁儿。", "阔人": "kuò 与 guò 声母不同（k 与 g），阔人指有钱有势的人。", "过门": "mén（第二声）与 rén（第二声）声母不同，过门指旧时女子出嫁到夫家。", "故人": "gù 与 guò 韵母不同（u 与 uo），故人指老朋友。"}, "sentence_index": null, "correct_answer": "过人"}, "level_3": {"options": [{"text": "过人", "is_correct": true, "explanation": "正确。过人表示超过一般人，与“本事”搭配，意思是本领超群。"}, {"text": "生疏", "is_correct": false, "explanation": "搭配：“生疏”说不熟练，与“本事”的强弱搭配不通。"}, {"text": "狭隘", "is_correct": false, "explanation": "语义：“狭隘”形容心胸或见识，不能用来修饰“本事”。"}, {"text": "呆板", "is_correct": false, "explanation": "语义：“呆板”形容做事的方式不灵活，不能用来说本领的高低。"}], "explanations": {"过人": "正确。过人表示超过一般人，与“本事”搭配，意思是本领超群。", "生疏": "搭配：“生疏”说不熟练，与“本事”的强弱搭配不通。", "狭隘": "语义：“狭隘”形容心胸或见识，不能用来修饰“本事”。", "呆板": "语义：“呆板”形容做事的方式不灵活，不能用来说本领的高低。"}, "sentence_index": 0, "correct_answer": "过人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题过人，需要马上解决。", "explanation": "这里应该用〈突出〉。过人形容人的能力或品质超过一般人，不能用来说问题。"}, {"text": "这部纪录片的画面很过人，获得了不少好评。", "explanation": "这里应该用〈精彩〉。过人形容人的能力、品质，不能用来形容画面这类事物。"}, {"text": "这杯咖啡的味道过人，我很喜欢。", "explanation": "这里应该用〈不错〉。过人形容人的能力、品质，不能用来形容咖啡的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过人", "is_correct": true, "explanation": "正确。过人表示超过一般人，与“运动员”的强项语境相符。"}, {"text": "虚弱", "is_correct": false, "explanation": "语义：“虚弱”说身体弱，与“运动员”的身份矛盾。"}, {"text": "柔弱", "is_correct": false, "explanation": "体貌：“柔弱”多形容人的身形或气质，不用来说体力。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：“脆弱”指容易被损坏，与“运动员”的体力要求矛盾。"}], "explanations": {"过人": "正确。过人表示超过一般人，与“运动员”的强项语境相符。", "虚弱": "语义：“虚弱”说身体弱，与“运动员”的身份矛盾。", "柔弱": "体貌：“柔弱”多形容人的身形或气质，不用来说体力。", "脆弱": "语义：“脆弱”指容易被损坏，与“运动员”的体力要求矛盾。"}, "sentence_index": 6, "correct_answer": "过人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的历史过人。", "explanation": "这里应该用〈非凡〉。过人只形容人的能力、品质，不能用来形容历史。"}, {"text": "这家店的招牌过人，老远就能看见。", "explanation": "这里应该用〈醒目〉。过人不能用来形容招牌这类物品。"}, {"text": "这种药的疗效过人，三天就好了。", "explanation": "这里应该用〈显著〉。过人形容人的能力、品质，不能用来形容药的疗效。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小伙子有过人得体能，连续跑了三小时。", "corrected_sentence": "这个小伙子有过人的体能，连续跑了三小时。", "error_description": "错误：“过人”修饰名词“体能”时，中间要用结构助词“的”。“得”是补语标记，不能用来修饰名词。应改为“过人的体能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有过人地听力，隔着两个房间都能听见门响。", "corrected_sentence": "她有过人的听力，隔着两个房间都能听见门响。", "error_description": "错误：“过人”修饰名词“听力”，要用“的”，不能用“地”（“地”多用于修饰动词）。应改为“过人的听力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528ae9eb-8f3f-45db-941a-909b86cd0b50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
