INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89069, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "织是把线一根一根穿在一起，做成布或毛衣。", "primary_collocate": null, "pronunciation": "zhī", "ipa": "ʈʂɻ̩˥", "syllable_count": 1, "sentences": [{"text": "奶奶在家织毛衣。", "target_word": "织", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈给我织了一条围巾。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每天晚上织一会儿毛衣。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天快到了，姐姐想织一件毛衣。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前村里的人用机器织布。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外婆织的帽子又软又暖和。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想学织手套，送给爸爸。", "target_word": "织", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她一边看电视，一边织围巾。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条围巾是我自己织的。", "target_word": "织", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "织一条围巾要用三天时间。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "织了", "label": "体标"}, {"form": "织着", "label": "体标"}, {"form": "织过", "label": "体标"}, {"form": "编织", "label": "复合"}, {"form": "織", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用线编成毛衣、围巾、布等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b548b9fd-667e-4dfa-a4aa-a6d0806d1b3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89069, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "织", "is_correct": true, "explanation": "正确。织（zhī）是把线编成毛衣、围巾等物品。"}, {"text": "直", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是笔直、一直。"}, {"text": "纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是纸张。"}, {"text": "吃", "is_correct": false, "explanation": "chī 与 zhī 声母不同（ch 与 zh），意思是吃东西。"}, {"text": "失", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），意思是失去。"}, {"text": "猪", "is_correct": false, "explanation": "zhū 与 zhī 韵母不同（u 与 i），意思是猪。"}, {"text": "资", "is_correct": false, "explanation": "zī 与 zhī 声母不同（z 与 zh），意思是资料、资金。"}], "explanations": {"织": "正确。织（zhī）是把线编成毛衣、围巾等物品。", "直": "zhí（第二声）与 zhī（第一声）声调不同，意思是笔直、一直。", "纸": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是纸张。", "吃": "chī 与 zhī 声母不同（ch 与 zh），意思是吃东西。", "失": "shī 与 zhī 声母不同（sh 与 zh），意思是失去。", "猪": "zhū 与 zhī 韵母不同（u 与 i），意思是猪。", "资": "zī 与 zhī 声母不同（z 与 zh），意思是资料、资金。"}, "sentence_index": null, "correct_answer": "织"}, "level_3": {"options": [{"text": "织", "is_correct": true, "explanation": "正确。“奶奶在家织毛衣”指用线编织毛衣。"}, {"text": "煮", "is_correct": false, "explanation": "语义：毛衣不能煮，“煮”只用于食物。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不说“写毛衣”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：毛衣不能吃，句子说不通。"}], "explanations": {"织": "正确。“奶奶在家织毛衣”指用线编织毛衣。", "煮": "语义：毛衣不能煮，“煮”只用于食物。", "写": "搭配：“写”的对象是文字，不说“写毛衣”。", "吃": "语义：毛衣不能吃，句子说不通。"}, "sentence_index": 0, "correct_answer": "织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在锅里织了一碗面条。", "explanation": "这里应该用“煮”。织是用线交叉编成布或毛衣等物品，不能用来做面条。"}, {"text": "他用油漆织了一面墙。", "explanation": "这里应该用“涂”。织是用线编成布或物品，油漆只能用来涂，不能用来织墙。"}, {"text": "她在纸上织了一只小鸟。", "explanation": "这里应该用“画”。织要用线编成物品，不能在纸上织图案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89069, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "织", "is_correct": true, "explanation": "正确。织（zhī）是把线编成毛衣、围巾等物品。"}, {"text": "制", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是制作。"}, {"text": "指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是手指。"}, {"text": "施", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），意思是施加。"}, {"text": "滋", "is_correct": false, "explanation": "zī 与 zhī 声母不同（z 与 zh），意思是滋养。"}, {"text": "痴", "is_correct": false, "explanation": "chī 与 zhī 声母不同（ch 与 zh），意思是痴呆、痴迷。"}], "explanations": {"织": "正确。织（zhī）是把线编成毛衣、围巾等物品。", "制": "zhì（第四声）与 zhī（第一声）声调不同，意思是制作。", "指": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是手指。", "施": "shī 与 zhī 声母不同（sh 与 zh），意思是施加。", "滋": "zī 与 zhī 声母不同（z 与 zh），意思是滋养。", "痴": "chī 与 zhī 声母不同（ch 与 zh），意思是痴呆、痴迷。"}, "sentence_index": null, "correct_answer": "织"}, "level_3": {"options": [{"text": "织", "is_correct": true, "explanation": "正确。“学织手套”指学习用线编手套。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发声歌唱，“学唱手套”说不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿咬东西，“学咬手套”说不通。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”不搭配“手套”，不能说“学吹手套”。"}], "explanations": {"织": "正确。“学织手套”指学习用线编手套。", "唱": "语义：唱是发声歌唱，“学唱手套”说不通。", "咬": "语义：咬是用牙齿咬东西，“学咬手套”说不通。", "吹": "搭配：“吹”不搭配“手套”，不能说“学吹手套”。"}, "sentence_index": 6, "correct_answer": "织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在地里织了一个坑。", "explanation": "这里应该用“挖”。织是用线编成布或物品，不能用来挖坑。"}, {"text": "他用木头织了一把椅子。", "explanation": "这里应该用“做”。织要用线，用木头做椅子不能说织。"}, {"text": "她在作业本上织了一行字。", "explanation": "这里应该用“写”。织是用线编成物品，不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她已经把毛衣完织了。", "corrected_sentence": "她已经把毛衣织完了。", "error_description": "补语位置错误：结果补语“完”应紧跟动词，应说“织完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
