INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89070, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把线、丝、麻等交叉编成布帛或其他物品。", "primary_collocate": null, "pronunciation": "zhī", "ipa": "ʈʂɻ̩˥", "syllable_count": 1, "sentences": [{"text": "蜘蛛在树上织了一张网。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候的人用蚕丝织绸缎。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔民正在织渔网。", "target_word": "织", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块地毯是工人用手一根一根织的。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在工厂织布，一天织很多米。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的妇女常用麻线织袋子。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器织出来的布又快又整齐。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用彩色的线织了一块桌布。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我看见奶奶坐在门口织帽子。", "target_word": "织", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种布是用丝线织成的。", "target_word": "织", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "织了", "label": "体标"}, {"form": "织着", "label": "体标"}, {"form": "织过", "label": "体标"}, {"form": "编织", "label": "复合"}, {"form": "織", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把线、丝、麻交叉编成布帛或网等物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b548b9fd-667e-4dfa-a4aa-a6d0806d1b3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89070, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "织", "is_correct": true, "explanation": "正确。织（zhī）是把线、丝等交叉编成布或网等物品。"}, {"text": "只", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是只有、一只。"}, {"text": "志", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是志向。"}, {"text": "诗", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），意思是诗歌。"}, {"text": "资", "is_correct": false, "explanation": "zī 与 zhī 声母不同（z 与 zh），意思是资料。"}], "explanations": {"织": "正确。织（zhī）是把线、丝等交叉编成布或网等物品。", "只": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是只有、一只。", "志": "zhì（第四声）与 zhī（第一声）声调不同，意思是志向。", "诗": "shī 与 zhī 声母不同（sh 与 zh），意思是诗歌。", "资": "zī 与 zhī 声母不同（z 与 zh），意思是资料。"}, "sentence_index": null, "correct_answer": "织"}, "level_3": {"options": [{"text": "织", "is_correct": true, "explanation": "正确。“织了一张网”指用线编成网。"}, {"text": "吃", "is_correct": false, "explanation": "语义：蜘蛛不会“吃”网，“吃了一张网”说不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不说“写网”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发出声音，不能“唱了一张网”。"}], "explanations": {"织": "正确。“织了一张网”指用线编成网。", "吃": "语义：蜘蛛不会“吃”网，“吃了一张网”说不通。", "写": "搭配：“写”的对象是文字，不说“写网”。", "唱": "语义：唱是发出声音，不能“唱了一张网”。"}, "sentence_index": 0, "correct_answer": "织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在锅里织了一盘青菜。", "explanation": "这里应该用“炒”。织是用线编成布或物品，不能用来炒菜。"}, {"text": "工人在织砖。", "explanation": "这里应该用“烧”。砖要烧制，不能用“织”。"}, {"text": "他用刀织了一个苹果。", "explanation": "这里应该用“切”。织是用线交叉编成布或物品，不能用刀织苹果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89070, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "织", "is_correct": true, "explanation": "正确。织（zhī）是把线、丝等交叉编成布或网等物品。"}, {"text": "直", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，意思是笔直。"}, {"text": "纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是纸张。"}, {"text": "失", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），意思是失去。"}, {"text": "猪", "is_correct": false, "explanation": "zhū 与 zhī 韵母不同（u 与 i），意思是猪。"}], "explanations": {"织": "正确。织（zhī）是把线、丝等交叉编成布或网等物品。", "直": "zhí（第二声）与 zhī（第一声）声调不同，意思是笔直。", "纸": "zhǐ（第三声）与 zhī（第一声）声调不同，意思是纸张。", "失": "shī 与 zhī 声母不同（sh 与 zh），意思是失去。", "猪": "zhū 与 zhī 韵母不同（u 与 i），意思是猪。"}, "sentence_index": null, "correct_answer": "织"}, "level_3": {"options": [{"text": "织", "is_correct": true, "explanation": "正确。“机器织出来的布”指用机器把线编成布。"}, {"text": "烤", "is_correct": false, "explanation": "语义：布不能用“烤”做出来，“烤出来的布”说不通。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”不能把线变成布，“晒出来的布”说不通。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”不搭配“布”，“吹出来的布”不成立。"}], "explanations": {"织": "正确。“机器织出来的布”指用机器把线编成布。", "烤": "语义：布不能用“烤”做出来，“烤出来的布”说不通。", "晒": "语义：“晒”不能把线变成布，“晒出来的布”说不通。", "吹": "搭配：“吹”不搭配“布”，“吹出来的布”不成立。"}, "sentence_index": 6, "correct_answer": "织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用石头织了一座房子。", "explanation": "这里应该用“建”。织是用线编成物品，不能用石头织出房子。"}, {"text": "她用颜料织了一幅画。", "explanation": "这里应该用“画”。织要用线编成布或物品，颜料只能用来画，不能说用颜料织画。"}, {"text": "他用毛笔织了一句话。", "explanation": "这里应该用“写”。织是编织物品，不能用毛笔织字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0431e36-8c4e-4683-ba93-6840cabd74b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid,