INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89071, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "犯是做了不应该做的事，做错事。", "primary_collocate": null, "pronunciation": "fàn", "ipa": "fan˥˩", "syllable_count": 1, "sentences": [{"text": "他又犯了同样的错误。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁都会犯错，别太难过。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在作业里犯了三个小错误。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么简单的题，你怎么还犯错？", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她犯了错，马上向老师道歉。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车太快，容易犯大错。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯过一个很大的错误，所以很小心。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想再犯这样的错误了。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子犯了错，爸爸没有生气。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时我太紧张，犯了很多错误。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯了", "label": "完成体"}, {"form": "犯过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "做了不该做的事，犯错误", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92d2e1a1-099e-41db-962b-ec5c14b7f3d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89071, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "犯", "is_correct": true, "explanation": "犯（fàn，第四声）：做错事，是本题的目标词。"}, {"text": "放", "is_correct": false, "explanation": "放（fàng）与犯（fàn）韵母不同（ang 与 an），意思是放置。"}, {"text": "反", "is_correct": false, "explanation": "反（fǎn，第三声）与犯（fàn，第四声）声调不同，意思是相反。"}, {"text": "翻", "is_correct": false, "explanation": "翻（fān，第一声）与犯（fàn，第四声）声调不同，意思是翻转。"}, {"text": "烦", "is_correct": false, "explanation": "烦（fán，第二声）与犯（fàn，第四声）声调不同，意思是烦恼。"}], "explanations": {"犯": "犯（fàn，第四声）：做错事，是本题的目标词。", "放": "放（fàng）与犯（fàn）韵母不同（ang 与 an），意思是放置。", "反": "反（fǎn，第三声）与犯（fàn，第四声）声调不同，意思是相反。", "翻": "翻（fān，第一声）与犯（fàn，第四声）声调不同，意思是翻转。", "烦": "烦（fán，第二声）与犯（fàn，第四声）声调不同，意思是烦恼。"}, "sentence_index": null, "correct_answer": "犯"}, "level_3": {"options": [{"text": "犯", "is_correct": true, "explanation": "犯：“犯错误”是固定搭配，表示做出错误的事，符合句意。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”指躲避，不能带“错误”作宾语，句子无法成立。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能带“错误”作宾语，句子无法成立。"}, {"text": "挨", "is_correct": false, "explanation": "配价：“挨”表示承受不好的事（挨骂、挨打），不能带“错误”作宾语。"}], "explanations": {"犯": "犯：“犯错误”是固定搭配，表示做出错误的事，符合句意。", "躲": "语义：“躲”指躲避，不能带“错误”作宾语，句子无法成立。", "吃": "语义：“吃”指进食，不能带“错误”作宾语，句子无法成立。", "挨": "配价：“挨”表示承受不好的事（挨骂、挨打），不能带“错误”作宾语。"}, "sentence_index": 0, "correct_answer": "犯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器昨天犯了故障。", "explanation": "这里应该用〈出〉。“犯”只用于人做错事，“出故障”说设备出现问题，机器不能“犯故障”。"}, {"text": "他很快犯了这个问题。", "explanation": "这里应该用〈解决〉。“犯”表示做错事，不能用来表示处理问题。"}, {"text": "妈妈犯了晚饭。", "explanation": "这里应该用〈准备〉。“犯”表示做错事，不能用于“准备晚饭”这类日常事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89071, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "犯", "is_correct": true, "explanation": "犯（fàn，第四声）：做错事，是本题的目标词。"}, {"text": "凡", "is_correct": false, "explanation": "凡（fán，第二声）与犯（fàn，第四声）声调不同，意思是凡是、平凡。"}, {"text": "繁", "is_correct": false, "explanation": "繁（fán，第二声）与犯（fàn，第四声）声调不同，意思是繁多。"}, {"text": "返", "is_correct": false, "explanation": "返（fǎn，第三声）与犯（fàn，第四声）声调不同，意思是返回。"}, {"text": "帆", "is_correct": false, "explanation": "帆（fān，第一声）与犯（fàn，第四声）声调不同，意思是船帆。"}], "explanations": {"犯": "犯（fàn，第四声）：做错事，是本题的目标词。", "凡": "凡（fán，第二声）与犯（fàn，第四声）声调不同，意思是凡是、平凡。", "繁": "繁（fán，第二声）与犯（fàn，第四声）声调不同，意思是繁多。", "返": "返（fǎn，第三声）与犯（fàn，第四声）声调不同，意思是返回。", "帆": "帆（fān，第一声）与犯（fàn，第四声）声调不同，意思是船帆。"}, "sentence_index": null, "correct_answer": "犯"}, "level_3": {"options": [{"text": "犯", "is_correct": true, "explanation": "犯过：“犯错误”的经历体，符合句意。"}, {"text": "留", "is_correct": false, "explanation": "语义：“留”指留下、保留，不能指做错事，句意不通。"}, {"text": "摔", "is_correct": false, "explanation": "配价：“摔”是跌倒或器物碎裂的动作，不能带“错误”作宾语。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，与“错误”不搭，句子无法成立。"}], "explanations": {"犯": "犯过：“犯错误”的经历体，符合句意。", "留": "语义：“留”指留下、保留，不能指做错事，句意不通。", "摔": "配价：“摔”是跌倒或器物碎裂的动作，不能带“错误”作宾语。", "喝": "语义：“喝”指饮用，与“错误”不搭，句子无法成立。"}, "sentence_index": 6, "correct_answer": "犯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他帮助迷路的老人，犯了一件好事。", "explanation": "这里应该用〈做〉。“犯”表示做错事，含贬义，不能用于“好事”。"}, {"text": "这种交通事故很少犯。", "explanation": "这里应该用〈发生〉。“犯”的主语必须是人，表示做错事，事故不能“犯”。"}, {"text": "他终于犯了作业。", "explanation": "这里应该用〈完成〉。“犯”表示做错事，不能用于作业这类任务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这学期犯着三次错。", "corrected_sentence": "他这学期犯了三次错。", "error_description": "体标错误：表示已经发生的几次错误要用“了”，“着”表示持续状态，“犯着三次错”不符合句意，应说“犯了三次错”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这次犯了一只大错。", "corrected_sentence": "他这次犯了一个大错。", "error_description": "量词错误：“错”前应用“个”，“只”用于动物等，不能修饰“错”，应说“一个大错”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
