INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89072, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出违反法律、规定的事。", "primary_collocate": null, "pronunciation": "fàn", "ipa": "fan˥˩", "syllable_count": 1, "sentences": [{"text": "偷东西是犯法的。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯了罪，被警察带走了。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车喝酒是犯法的事。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不知道法律，也不能犯法。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时犯过法，现在是好人了。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个国家，随地吐痰也犯法。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人犯了法，法院要审判他。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打人犯法，你要记住。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问他到底犯了什么罪。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了钱犯了罪，现在很后悔。", "target_word": "犯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "犯了", "label": "完成体"}, {"form": "犯过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "做出违反法律的事，犯法、犯罪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92d2e1a1-099e-41db-962b-ec5c14b7f3d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89072, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "犯", "is_correct": true, "explanation": "犯（fàn，第四声）：做出违法的事，是本题的目标词。"}, {"text": "返", "is_correct": false, "explanation": "返（fǎn，第三声）与犯（fàn，第四声）声调不同，意思是返回。"}, {"text": "凡", "is_correct": false, "explanation": "凡（fán，第二声）与犯（fàn，第四声）声调不同，意思是凡是、平凡。"}, {"text": "翻", "is_correct": false, "explanation": "翻（fān，第一声）与犯（fàn，第四声）声调不同，意思是翻转。"}, {"text": "放", "is_correct": false, "explanation": "放（fàng）与犯（fàn）韵母不同（ang 与 an），意思是放置。"}], "explanations": {"犯": "犯（fàn，第四声）：做出违法的事，是本题的目标词。", "返": "返（fǎn，第三声）与犯（fàn，第四声）声调不同，意思是返回。", "凡": "凡（fán，第二声）与犯（fàn，第四声）声调不同，意思是凡是、平凡。", "翻": "翻（fān，第一声）与犯（fàn，第四声）声调不同，意思是翻转。", "放": "放（fàng）与犯（fàn）韵母不同（ang 与 an），意思是放置。"}, "sentence_index": null, "correct_answer": "犯"}, "level_3": {"options": [{"text": "犯", "is_correct": true, "explanation": "犯法：违反法律，符合句意。"}, {"text": "守", "is_correct": false, "explanation": "语义：“守法”指遵守法律，与“偷东西”相反，句子说不通。"}, {"text": "护", "is_correct": false, "explanation": "搭配：“护法”多指护卫法制或佛法，不能用来判断“偷东西”的性质。"}, {"text": "立", "is_correct": false, "explanation": "语义：“立法”指制定法律，与“偷东西”的判断不符。"}], "explanations": {"犯": "犯法：违反法律，符合句意。", "守": "语义：“守法”指遵守法律，与“偷东西”相反，句子说不通。", "护": "搭配：“护法”多指护卫法制或佛法，不能用来判断“偷东西”的性质。", "立": "语义：“立法”指制定法律，与“偷东西”的判断不符。"}, "sentence_index": 0, "correct_answer": "犯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他犯了这份合同。", "explanation": "这里应该用〈违反〉。“犯”不能接“合同”这类规定性的文件，违反合同应说“违反”。"}, {"text": "他犯了公共财物。", "explanation": "这里应该用〈破坏〉。“犯”说的是违法行为，不能接“公共财物”作宾语，破坏财物应说“破坏”。"}, {"text": "他犯了别人的手机。", "explanation": "这里应该用〈偷〉。“犯”不能带“手机”这类具体物品作宾语，偷东西应说“偷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89072, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "犯", "is_correct": true, "explanation": "犯（fàn，第四声）：做出违法的事，是本题的目标词。"}, {"text": "反", "is_correct": false, "explanation": "反（fǎn，第三声）与犯（fàn，第四声）声调不同，意思是相反。"}, {"text": "烦", "is_correct": false, "explanation": "烦（fán，第二声）与犯（fàn，第四声）声调不同，意思是烦恼。"}, {"text": "繁", "is_correct": false, "explanation": "繁（fán，第二声）与犯（fàn，第四声）声调不同，意思是繁多。"}, {"text": "汉", "is_correct": false, "explanation": "汉（hàn，第四声）与犯（fàn）声母不同（h 与 f），意思是汉族。"}], "explanations": {"犯": "犯（fàn，第四声）：做出违法的事，是本题的目标词。", "反": "反（fǎn，第三声）与犯（fàn，第四声）声调不同，意思是相反。", "烦": "烦（fán，第二声）与犯（fàn，第四声）声调不同，意思是烦恼。", "繁": "繁（fán，第二声）与犯（fàn，第四声）声调不同，意思是繁多。", "汉": "汉（hàn，第四声）与犯（fàn）声母不同（h 与 f），意思是汉族。"}, "sentence_index": null, "correct_answer": "犯"}, "level_3": {"options": [{"text": "犯", "is_correct": true, "explanation": "犯了法：违法，符合句意。"}, {"text": "执", "is_correct": false, "explanation": "语义：“执法”指执行法律，应由执法者做，与被审判者的句意不符。"}, {"text": "用", "is_correct": false, "explanation": "搭配：“用法”指使用的方式，不能用于“这个人……了法”的句式。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”需要可食用的对象，不能带“法”作宾语。"}], "explanations": {"犯": "犯了法：违法，符合句意。", "执": "语义：“执法”指执行法律，应由执法者做，与被审判者的句意不符。", "用": "搭配：“用法”指使用的方式，不能用于“这个人……了法”的句式。", "吃": "配价：“吃”需要可食用的对象，不能带“法”作宾语。"}, "sentence_index": 6, "correct_answer": "犯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在战场上犯了大功。", "explanation": "这里应该用〈立〉。“犯”表示违法或做错事，含贬义，不能用于“大功”这类正面的功绩。"}, {"text": "他认真犯了命令。", "explanation": "这里应该用〈执行〉。“犯”表示违反规定，不能用于“命令”这类要服从的指示。"}, {"text": "朋友之间要犯约定。", "explanation": "这里应该用〈遵守〉。“犯”表示违反规定，不能用于要遵守的“约定”，应说“遵守约定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他犯下了一只重罪。", "corrected_sentence": "他犯下了一项重罪。", "error_description": "量词错误：“罪”应搭配“项”，“只”用于动物等，不能修饰“罪”，应说“一项重罪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他犯了过罪，现在很后悔。", "corrected_sentence": "他犯过罪，现在很后悔。", "error_description": "体标错误：“犯过”是经历体，已用“过”，不能再加“了”，应说“犯过罪”，不能说“犯了过罪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b5e8e9e2-9a18-4d41-b561-6e310940faf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
