INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89073, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "后段是一件事或一段路的后面那一部分。", "primary_collocate": null, "pronunciation": "hòu duàn", "ipa": "xoʊ̯˥˩ tu̯an˥˩", "syllable_count": 2, "sentences": [{"text": "这条山路的后段比较难走。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的后段，他跑得越来越慢。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的后段有点儿没意思。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走到路的后段，天已经黑了。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的后段，我们住在海边。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的后段写得比前段好。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议的后段，大家都累了。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马拉松后段，不少人都跑不动了。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条路的前段很宽，后段很窄。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这节课的后段，老师让我们自己练习。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一件事或一段路靠后的那一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4db7646-0948-40ca-93a1-22bf840509fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89073, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“价格”不是路段，不能说“比较难走”，句子说不通。"}, {"text": "后段", "is_correct": true, "explanation": "“后段”指山路靠后的一段，与“比较难走”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与山路的路况无关，“颜色比较难走”不通。"}, {"text": "后尘", "is_correct": false, "explanation": "语义：“后尘”只用于“步人后尘”等固定说法，不指路的一段，“山路的后尘比较难走”说不通。"}], "explanations": {"价格": "语义：“价格”不是路段，不能说“比较难走”，句子说不通。", "后段": "“后段”指山路靠后的一段，与“比较难走”相符。", "颜色": "语义：“颜色”与山路的路况无关，“颜色比较难走”不通。", "后尘": "语义：“后尘”只用于“步人后尘”等固定说法，不指路的一段，“山路的后尘比较难走”说不通。"}, "sentence_index": 0, "correct_answer": "后段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子的后段坏了。", "explanation": "这里应该用〈后面〉。〈后段〉指一段路或过程靠后的部分，不指物体的后面。"}, {"text": "他的后段很疼。", "explanation": "这里应该用〈后背〉。〈后段〉不指身体部位。"}, {"text": "我家的后段有一个小花园。", "explanation": "这里应该用〈后面〉。〈后段〉指一段路或过程靠后的部分，不指房子后面的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是会议的一部分，“会议的天气”说不通。"}, {"text": "后段", "is_correct": true, "explanation": "“后段”指会议靠后的一段时间，与“大家都累了”相符。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”不表示会议的一段，“会议的座位”说不通。"}, {"text": "末梢", "is_correct": false, "explanation": "语域：“末梢”是术语，指神经或枝条的末端，用在描述会议时不合语域。"}], "explanations": {"天气": "语义：“天气”不是会议的一部分，“会议的天气”说不通。", "后段": "“后段”指会议靠后的一段时间，与“大家都累了”相符。", "座位": "语义：“座位”不表示会议的一段，“会议的座位”说不通。", "末梢": "语域：“末梢”是术语，指神经或枝条的末端，用在描述会议时不合语域。"}, "sentence_index": 6, "correct_answer": "后段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要为后段着想，多留些资源。", "explanation": "这里应该用〈后辈〉。〈后段〉不指人，“为……着想”的对象应是人。"}, {"text": "他是我们的后段，总是默默支持我们。", "explanation": "这里应该用〈后盾〉。〈后段〉不指人，不能指给予支持的人。"}, {"text": "我们在后段种了很多花。", "explanation": "这里应该用〈后院〉。〈后段〉指路或过程的部分，不指一块场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们爬到了山路的后段们。", "corrected_sentence": "他们爬到了山路的后段。", "error_description": "错误：在“后段”后加了复数词尾“们”。“们”只能加在指人的名词后，“后段”指路段，应直接说“山路的后段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "选手们都落着后段。", "corrected_sentence": "选手们都落在后段。", "error_description": "错误：“落”后面用了“着”，“落着后段”不通。正确：说“落在后段”，“落”后要用介词“在”，不用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一过程或路程中靠后的部分。", "primary_collocate": null, "pronunciation": "hòu duàn", "ipa": "xoʊ̯˥˩ tu̯an˥˩", "syllable_count": 2, "sentences": [{"text": "比赛进入后段，他的速度慢了下来。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的后段水很浅。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事的后段让我很感动。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目到了后段，大家都很忙。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条公路的后段正在修路。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会的后段，歌迷一起唱歌。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的后段，我才发现时间不够了。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次火车旅行的后段，旅客们都睡着了。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首曲子的后段声音越来越大。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次长跑的后段，我一直跟着他。", "target_word": "后段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "过程或路程中靠后的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4db7646-0948-40ca-93a1-22bf840509fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开始", "is_correct": false, "explanation": "语义：“开始”指起点，不是比赛靠后的阶段，“进入开始”也不通。"}, {"text": "后段", "is_correct": true, "explanation": "“后段”指比赛靠后的阶段，与“进入”搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是比赛的阶段，“进入颜色”说不通。"}, {"text": "后尘", "is_correct": false, "explanation": "语域：“后尘”是文言词，不用于描述比赛阶段，不合语域。"}], "explanations": {"开始": "语义：“开始”指起点，不是比赛靠后的阶段，“进入开始”也不通。", "后段": "“后段”指比赛靠后的阶段，与“进入”搭配自然。", "颜色": "语义：“颜色”不是比赛的阶段，“进入颜色”说不通。", "后尘": "语域：“后尘”是文言词，不用于描述比赛阶段，不合语域。"}, "sentence_index": 0, "correct_answer": "后段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在太阳下站久了，后段很疼。", "explanation": "这里应该用〈后脑勺〉。〈后段〉不指身体部位，也不指后脑勺。"}, {"text": "他是我的后段，比我小两岁。", "explanation": "这里应该用〈后代〉。〈后段〉指过程或路程的一部分，不指人。"}, {"text": "我们在路边看到了一只后段。", "explanation": "这里的量词用错了。〈只〉用于动物，〈后段〉不是动物，不能用〈只〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“价格”不是考试的一段，句子说不通。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”与考试无关，“考试的饮料”说不通。"}, {"text": "后段", "is_correct": true, "explanation": "“后段”指考试靠后的时段，与“才发现时间不够”的语境相符。"}, {"text": "后序", "is_correct": false, "explanation": "语域：“后序”是书籍末尾的序文，不用于描述考试的时段，不合语域。"}], "explanations": {"价格": "语义：“价格”不是考试的一段，句子说不通。", "饮料": "语义：“饮料”与考试无关，“考试的饮料”说不通。", "后段": "“后段”指考试靠后的时段，与“才发现时间不够”的语境相符。", "后序": "语域：“后序”是书籍末尾的序文，不用于描述考试的时段，不合语域。"}, "sentence_index": 6, "correct_answer": "后段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一生都在为后段操心，把钱都留给孩子。", "explanation": "这里应该用〈后人〉。〈后段〉不指人，不能作“为……操心”的对象。"}, {"text": "他从后段溜进了会场。", "explanation": "这里应该用〈后门〉。〈后段〉不指门或出入口，不能用于“从……溜进”。"}, {"text": "后段的战士一直在支援前线。", "explanation": "这里应该用〈后方〉。〈后段〉指过程或路程靠后的部分，不指地区，战士不在“后段”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个项目快在后段了，大家得加快速度。", "corrected_sentence": "这个项目快到后段了，大家得加快速度。", "error_description": "错误：“到”误写成“在”，“快在后段了”不通。正确：说“快到后段了”，“到”后接表示阶段的“后段”，表示事情进展到了这一阶段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直落着队伍的后段。", "corrected_sentence": "他一直落在队伍的后段。", "error_description": "错误：“落”后面用了“着”，“落着队伍的后段”不通。正确：说“落在队伍的后段”，“落”后接处所要用介词“在”，不用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
