INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89075, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一等是质量或水平最高、最好的。", "primary_collocate": null, "pronunciation": "yī děng", "ipa": "i˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家宾馆的房间是一等的，住起来很舒服。", "target_word": "一等", "complexity_tier": "T3", "furigana": "zhè jiā bīnguǎn de fángjiān shì yī děng de, zhù qǐlái hěn shūfu", "sentence_source": "generated"}, {"text": "这家店的茶是一等的，价格也高。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一等的米，做出来的饭很香。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台冰箱的材料是一等的，用了十几年还很好。", "target_word": "一等", "complexity_tier": "T3", "furigana": "zhè tái bīngxiāng de cáiliào shì yī děng de, yòng le shí jǐ nián hái hěn hǎo", "sentence_source": "generated"}, {"text": "老张的手艺是一等的，没有人比他好。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的篮球水平是一等的。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批苹果都是一等的，一个坏的也没有。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的服务是一等的，病人都说好。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师做的鱼是一等的，客人吃了还想来。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布是一等的，摸起来很软。", "target_word": "一等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一等奖", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容质量、水平排在第一级、最好，常说“是一等的”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8acff1a7-15ec-4016-88fb-91db472ff9f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89075, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透明", "is_correct": false, "explanation": "语义：透明说物体的状态，不能用来形容房间的等级。"}, {"text": "一等", "is_correct": true, "explanation": "正确：一等，表示最好的等级，修饰“房间”。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：沉重多用来说负担或心情，不用来形容房间的质量。"}, {"text": "咸", "is_correct": false, "explanation": "语义：咸说味道，不能用来形容房间。"}], "explanations": {"透明": "语义：透明说物体的状态，不能用来形容房间的等级。", "一等": "正确：一等，表示最好的等级，修饰“房间”。", "沉重": "搭配：沉重多用来说负担或心情，不用来形容房间的质量。", "咸": "语义：咸说味道，不能用来形容房间。"}, "sentence_index": 0, "correct_answer": "一等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们班的一等生。", "explanation": "这里应该用〈优等〉。“优等生”是固定说法，“一等”不能直接修饰“生”。"}, {"text": "这是一等大事，大家都很重视。", "explanation": "这里应该用〈头等〉。“头等大事”是固定说法，“一等”不能这样修饰“大事”。"}, {"text": "这家饭店的服务很一等，客人都很满意。", "explanation": "这里应该用〈一流〉。“一等”表示等级，不能用“很”修饰程度，应说“一流”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89075, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烫", "is_correct": false, "explanation": "语义：烫说温度，不能用来形容苹果的质量等级。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：窄说宽度，不用来形容苹果。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：安静说人或环境的状态，不用来形容苹果。"}, {"text": "一等", "is_correct": true, "explanation": "正确：一等，表示质量最好的等级。"}], "explanations": {"烫": "语义：烫说温度，不能用来形容苹果的质量等级。", "窄": "搭配：窄说宽度，不用来形容苹果。", "安静": "搭配：安静说人或环境的状态，不用来形容苹果。", "一等": "正确：一等，表示质量最好的等级。"}, "sentence_index": 6, "correct_answer": "一等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件毛衣最一等，穿起来很舒服。", "explanation": "这里应该用〈上等〉。“一等”表示等级，不能和“最”一起表示程度，应说“最上等”。"}, {"text": "这件毛衣的袖子很一等，穿起来很暖和。", "explanation": "这里应该用〈精致〉。一等表示质量或名次的等级，不能用来形容袖子的样式。"}, {"text": "这件毛衣比那件更一等，穿起来很暖和。", "explanation": "这里应该用〈更好〉。“一等”是等级词，不能用“更”表示比较。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市的牛肉是很一等的，很新鲜。", "corrected_sentence": "这家超市的牛肉是一等的，很新鲜。", "error_description": "“很”不能修饰“一等”这类等级词，应去掉“很”。错误：是很一等的；正确：是一等的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些茶叶都是一等地，喝起来很香。", "corrected_sentence": "这些茶叶都是一等的，喝起来很香。", "error_description": "“一等”作形容词放在“是”后面要用“的”，不能用“地”；“地”用来修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4322816c-57d2-4ab7-ad75-a9892f1c7601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89077, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新派", "is_correct": true, "explanation": "新派与老派相对，指做事、穿衣的新式作风，与“这位老师的教法有点老派”正好相反。"}, {"text": "勤快", "is_correct": false, "explanation": "勤快与老派没有反义关系，它说的是做事勤劳。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明与老派没有反义关系，它说的是头脑灵活。"}, {"text": "安静", "is_correct": false, "explanation": "安静与老派没有反义关系，它说的是声音或环境安静。"}], "correct_answer": "新派", "explanations": {"新派": "新派与老派相对，指做事、穿衣的新式作风，与“这位老师的教法有点老派”正好相反。", "勤快": "勤快与老派没有反义关系，它说的是做事勤劳。", "聪明": "聪明与老派没有反义关系，它说的是头脑灵活。", "安静": "安静与老派没有反义关系，它说的是声音或环境安静。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89077, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "时髦", "is_correct": true, "explanation": "时髦与老派相对，指紧跟潮流、新式，与“你这种做事方式太老派了”正好相反。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢与老派没有反义关系，它说的是不怕危险。"}, {"text": "高大", "is_correct": false, "explanation": "高大与老派没有反义关系，它说的是身材或样子高大。"}, {"text": "热情", "is_correct": false, "explanation": "热情与老派没有反义关系，它说的是待人的态度。"}], "correct_answer": "时髦", "explanations": {"时髦": "时髦与老派相对，指紧跟潮流、新式，与“你这种做事方式太老派了”正好相反。", "勇敢": "勇敢与老派没有反义关系，它说的是不怕危险。", "高大": "高大与老派没有反义关系，它说的是身材或样子高大。", "热情": "热情与老派没有反义关系，它说的是待人的态度。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89077, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "老派是做事和穿衣都像以前的老办法。", "primary_collocate": null, "pronunciation": "lǎo pài", "ipa": "lau̯˨˩ pʰai̯˥˩", "syllable_count": 2, "sentences": [{"text": "我爷爷穿衣服很老派。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事一直很老派。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着一件很老派的外套。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的教法有点老派。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢写信，不用手机，真老派。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他老派的做法，年轻人不太习惯。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的穿衣风格太老派了。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店的老板做生意很老派。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打扮得很老派，像五十年前的人。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这种做事方式太老派了，现在没人这样做。", "target_word": "老派", "complexity_tier": "T3", "furigana": "nǐ zhè zhǒng zuò shì fāng shì tài lǎo pài le, xiàn zài méi rén zhè yàng zuò", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "做事穿衣像以前的老办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a929c76-6771-4b07-b944-72f67b1dd6c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89077, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老派", "is_correct": true, "explanation": "老派指做事、穿衣像以前的老办法，与“我爷爷穿衣服很……”相符。"}, {"text": "长", "is_correct": false, "explanation": "搭配：“长”说长短，不能用来形容穿衣的风格。"}, {"text": "矮", "is_correct": false, "explanation": "语义：“矮”描述人的身高，不能形容穿衣服的样子。"}, {"text": "响", "is_correct": false, "explanation": "语义：“响”指声音大，不能形容穿衣服的风格。"}], "explanations": {"老派": "老派指做事、穿衣像以前的老办法，与“我爷爷穿衣服很……”相符。", "长": "搭配：“长”说长短，不能用来形容穿衣的风格。", "矮": "语义：“矮”描述人的身高，不能形容穿衣服的样子。", "响": "语义：“响”指声音大，不能形容穿衣服的风格。"}, "sentence_index": 0, "correct_answer": "老派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区的经济很老派。", "explanation": "这里应该用〈落后〉。老派说做事和穿衣的旧办法，形容经济水平要用落后。"}, {"text": "这块布料被洗得很老派了。", "explanation": "这里应该用〈破旧〉。老派指做事、穿衣的旧作风，说布料磨损要用破旧。"}, {"text": "这台手机的电量很老派了。", "explanation": "这里应该用〈不足〉。老派指作风、习惯的旧式，形容电量少要用不足。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89077, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老派", "is_correct": true, "explanation": "老派形容穿衣风格保持旧式，与“爸爸的穿衣风格太……了”相符。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢”说速度，不能形容穿衣的风格。"}, {"text": "响", "is_correct": false, "explanation": "语义：“响”指声音大，与穿衣风格的旧式或新式无关。"}, {"text": "短", "is_correct": false, "explanation": "搭配：“短”说长度，不能用来形容穿衣风格。"}], "explanations": {"老派": "老派形容穿衣风格保持旧式，与“爸爸的穿衣风格太……了”相符。", "慢": "搭配：“慢”说速度，不能形容穿衣的风格。", "响": "语义：“响”指声音大，与穿衣风格的旧式或新式无关。", "短": "搭配：“短”说长度，不能用来形容穿衣风格。"}, "sentence_index": 6, "correct_answer": "老派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一个老派的传说。", "explanation": "这里应该用〈古老〉。老派说人的做事、穿衣作风，讲传说、历史要用古老。"}, {"text": "这条河的水很老派。", "explanation": "这里应该用〈清澈〉。老派指做事、穿衣的旧作风，形容河水干净透明要用清澈。"}, {"text": "这台机器的价格已经很老派了。", "explanation": "这里应该用〈昂贵〉。老派指做事、穿衣的旧作风，说价格高要用昂贵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她穿很老派。", "corrected_sentence": "她穿得很老派。", "error_description": "“穿”后面带状态补语时要用“得”，应说“穿得很老派”；省略“得”就不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一点也老派。", "corrected_sentence": "他一点也不老派。", "error_description": "“一点也”后面的否定形式要用“不”，应说“他一点也不老派”；省略“不”就成了错误的肯定句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89078, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新派", "is_correct": true, "explanation": "新派与老派相对，指作风、做法的新式，与“她说话的方式很老派”正好相反。"}, {"text": "认真", "is_correct": false, "explanation": "认真与老派没有反义关系，它说的是做事态度严肃。"}, {"text": "温柔", "is_correct": false, "explanation": "温柔与老派没有反义关系，它说的是性情或态度柔和。"}, {"text": "大方", "is_correct": false, "explanation": "大方与老派没有反义关系，它说的是待人不拘谨。"}], "correct_answer": "新派", "explanations": {"新派": "新派与老派相对，指作风、做法的新式，与“她说话的方式很老派”正好相反。", "认真": "认真与老派没有反义关系，它说的是做事态度严肃。", "温柔": "温柔与老派没有反义关系，它说的是性情或态度柔和。", "大方": "大方与老派没有反义关系，它说的是待人不拘谨。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89078, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "时髦", "is_correct": true, "explanation": "时髦与老派相对，指紧跟潮流、新式，与“他做人的作风很老派”正好相反。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹与老派没有反义关系，它说的是场面喧闹。"}, {"text": "直爽", "is_correct": false, "explanation": "直爽与老派没有反义关系，它说的是性格坦率。"}, {"text": "伶俐", "is_correct": false, "explanation": "伶俐与老派没有反义关系，它说的是聪明机灵。"}], "correct_answer": "时髦", "explanations": {"时髦": "时髦与老派相对，指紧跟潮流、新式，与“他做人的作风很老派”正好相反。", "热闹": "热闹与老派没有反义关系，它说的是场面喧闹。", "直爽": "直爽与老派没有反义关系，它说的是性格坦率。", "伶俐": "伶俐与老派没有反义关系，它说的是聪明机灵。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89078, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "作风、习惯等保持旧式的，不时髦的。", "primary_collocate": null, "pronunciation": "lǎo pài", "ipa": "lau̯˨˩ pʰai̯˥˩", "syllable_count": 2, "sentences": [{"text": "他的衣服太老派，一点也不时髦。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老人的习惯很老派。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这首歌的风格有点老派。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话的方式很老派。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老派的男人常常给女士开门。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的装修很老派。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的待人作风有点老派。", "target_word": "老派", "complexity_tier": "T3", "furigana": "tā de dài rén zuò fēng yǒu diǎn lǎo pài", "sentence_source": "generated"}, {"text": "校长的作风比较老派。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在年轻人看来，写信是很老派的事。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做人的作风很老派，不太跟得上潮流。", "target_word": "老派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "作风习惯保持旧式、不时髦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a929c76-6771-4b07-b944-72f67b1dd6c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老派", "is_correct": true, "explanation": "老派指作风、习惯保持旧式，与“一点也不时髦”相呼应。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“快”说速度，不能用来形容衣服的样式。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”指味道，与衣服的样式无关。"}, {"text": "矮", "is_correct": false, "explanation": "语义：“矮”描述人的身高，不能用于形容衣服。"}], "explanations": {"老派": "老派指作风、习惯保持旧式，与“一点也不时髦”相呼应。", "快": "搭配：“快”说速度，不能用来形容衣服的样式。", "苦": "语义：“苦”指味道，与衣服的样式无关。", "矮": "语义：“矮”描述人的身高，不能用于形容衣服。"}, "sentence_index": 0, "correct_answer": "老派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的面积已经很老派了。", "explanation": "这里应该用〈宽敞〉。老派说作风、习惯的旧式，说面积大要用宽敞。"}, {"text": "这个地区的经济很老派。", "explanation": "这里应该用〈落后〉。老派说作风、习惯的旧式，形容经济水平要用落后。"}, {"text": "这是一个老派的传说。", "explanation": "这里应该用〈古老〉。老派说人的做事、说话作风，讲传说、历史要用古老。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老派", "is_correct": true, "explanation": "老派形容作风保持旧式，与“他的待人作风有点……”相符。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，无法用来形容待人作风。"}, {"text": "白", "is_correct": false, "explanation": "语义：“白”指颜色，无法用来形容作风。"}, {"text": "短", "is_correct": false, "explanation": "搭配：“短”说长度，不能用来形容待人作风。"}], "explanations": {"老派": "老派形容作风保持旧式，与“他的待人作风有点……”相符。", "咸": "语义：“咸”指味道，无法用来形容待人作风。", "白": "语义：“白”指颜色，无法用来形容作风。", "短": "搭配：“短”说长度，不能用来形容待人作风。"}, "sentence_index": 6, "correct_answer": "老派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯的亮度很老派。", "explanation": "这里应该用〈明亮〉。老派说作风、习惯的旧式，形容亮度要用明亮。"}, {"text": "这套设备的重量很老派了。", "explanation": "这里应该用〈沉重〉。老派指作风、习惯的旧式，形容重量要用沉重。"}, {"text": "这是一段老派的历史。", "explanation": "这里应该用〈久远〉。老派说做事、待人的旧作风，描述历史的年代久远要用久远。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说话的作风很老派着。", "corrected_sentence": "他说话的作风很老派。", "error_description": "形容词“老派”后面不能加“着”，应说“作风很老派”；多出的“着”要去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做事做很老派。", "corrected_sentence": "他做事做得很老派。", "error_description": "“做”后面带状态补语时要用“得”，应说“做得很老派”；省略“得”就不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
