INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89079, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "现有是现在已经有的。", "primary_collocate": null, "pronunciation": "xiàn yǒu", "ipa": "ɕjɛn⁵¹ joʊ²¹⁴", "syllable_count": 2, "sentences": [{"text": "先用现有的钱买吧。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现有的书我都看完了。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把现有的东西都拿出来。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们现有的人不够多。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用现有的食材做一顿饭。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现有的时间只够吃饭。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他卖掉了现有的车。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把现有的钱数一数。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们现有的全部力量。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现有的水只够喝一天。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现有的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "现在手里已经有的（钱、人、东西等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06c8ddc-088c-4454-b9ef-23726f1668db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89079, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未来", "is_correct": false, "explanation": "语义：未来的钱还没有，现在无法拿来用。"}, {"text": "现有", "is_correct": true, "explanation": "符合语境：指手里目前已经有的钱。"}, {"text": "幻想", "is_correct": false, "explanation": "语义：幻想的钱并不存在，不能用来买东西。"}, {"text": "大方", "is_correct": false, "explanation": "搭配：“大方”形容人的态度，不能修饰“钱”。"}], "explanations": {"未来": "语义：未来的钱还没有，现在无法拿来用。", "现有": "符合语境：指手里目前已经有的钱。", "幻想": "语义：幻想的钱并不存在，不能用来买东西。", "大方": "搭配：“大方”形容人的态度，不能修饰“钱”。"}, "sentence_index": 0, "correct_answer": "现有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下个月发工资后，我现有的钱会比现在多一倍。", "explanation": "〈现有〉指现在手里已经有的钱，不能用来说将来才会增加的钱；这里应该用〈将来的〉或〈以后的〉。"}, {"text": "我现有的存款早就花光了。", "explanation": "〈现有〉指现在实际拥有的。存款早已花光，不再现有，这里应该用〈原本的〉，指以前有过的。"}, {"text": "这个村子现有的老井早已不存在了。", "explanation": "〈现有〉指目前实际存在的事物。老井早已不存在，这里应该用〈原来的〉，指以前有过的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89079, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "假想", "is_correct": false, "explanation": "语义：假想的车并不真实存在，不能卖掉。"}, {"text": "健康", "is_correct": false, "explanation": "搭配：“健康”形容人或身体，不能修饰“车”。"}, {"text": "现有", "is_correct": true, "explanation": "符合语境：指他手里目前有的车，卖掉的就是这辆。"}, {"text": "未来", "is_correct": false, "explanation": "语义：未来的车还没有，现在不可能卖掉。"}], "explanations": {"假想": "语义：假想的车并不真实存在，不能卖掉。", "健康": "搭配：“健康”形容人或身体，不能修饰“车”。", "现有": "符合语境：指他手里目前有的车，卖掉的就是这辆。", "未来": "语义：未来的车还没有，现在不可能卖掉。"}, "sentence_index": 6, "correct_answer": "现有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书上说，现有的猛犸象生活在寒冷的地区。", "explanation": "〈现有〉指目前仍然存在的事物。猛犸象早已灭绝，这里应该用〈远古的〉，指很久以前存在过的。"}, {"text": "我们班现有的老师都是去年才调走的。", "explanation": "〈现有〉指目前在岗的人，去年已经调走的老师不再现有；这里应该用〈原来的〉。"}, {"text": "这个小区的路灯，现有的全部是明年才装好的。", "explanation": "〈现有〉表示已经存在，与“明年才装好”矛盾；这里应该用〈新装的〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用现有地钱买了一台电脑。", "corrected_sentence": "我用现有的钱买了一台电脑。", "error_description": "“现有”修饰名词“钱”时要用“的”，应说“现有的钱”；“现有地钱”用“地”错误（“地”用于修饰动词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "现有了的钱只够买一张票。", "corrected_sentence": "现有的钱只够买一张票。", "error_description": "“现有”是形容词，后面不能加“了的”；“现有了的钱”错误，应说“现有的钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
