INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89080, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，目前已经存在的。", "primary_collocate": null, "pronunciation": "xiàn yǒu", "ipa": "ɕjɛn⁵¹ joʊ²¹⁴", "syllable_count": 2, "sentences": [{"text": "我们要先用好现有的设备。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现有的办法都不太好用。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先看看现有的资料。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现有的条件还不够好。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校现有的教室不够用。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想改变现有的生活。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先用现有的方法试试。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现有的房子太小，住不下。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据现有的信息，他明天会来。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现有的规定需要改一改。", "target_word": "现有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "现有的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "目前已经存在的（事物、条件、办法等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06c8ddc-088c-4454-b9ef-23726f1668db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89080, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未来", "is_correct": false, "explanation": "语义：未来的设备还不存在，现在无法用好。"}, {"text": "现有", "is_correct": true, "explanation": "符合语境：指目前已经存在、可以直接使用的设备。"}, {"text": "假想", "is_correct": false, "explanation": "语义：假想的设备并不真实存在，不能拿来使用。"}, {"text": "报废", "is_correct": false, "explanation": "搭配：“用好”不能搭配已经报废的设备。"}], "explanations": {"未来": "语义：未来的设备还不存在，现在无法用好。", "现有": "符合语境：指目前已经存在、可以直接使用的设备。", "假想": "语义：假想的设备并不真实存在，不能拿来使用。", "报废": "搭配：“用好”不能搭配已经报废的设备。"}, "sentence_index": 0, "correct_answer": "现有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明年新建的校舍里，现有的教室会比现在多一倍。", "explanation": "〈现有〉指目前已经存在的事物。明年的教室还没有建成，这里应该用〈将来的〉，不能说“现有”。"}, {"text": "这座城市现有的老房子早已不存在了。", "explanation": "〈现有〉指目前实际存在的事物。老房子早已不存在，这里应该用〈原有〉，指以前有过的。"}, {"text": "我们班现有的班长已经毕业了。", "explanation": "〈现有〉与“已经毕业”前后矛盾：毕业的人不再是目前的班长。这里应该用〈原来的〉，指以前担任过的班长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虚构", "is_correct": false, "explanation": "语义：虚构的方法不是真实存在的，无法拿来试用。"}, {"text": "现有", "is_correct": true, "explanation": "符合语境：指目前已经存在、可以马上试用的方法。"}, {"text": "疲劳", "is_correct": false, "explanation": "搭配：“疲劳”形容人或状态，不能修饰“方法”。"}, {"text": "未来", "is_correct": false, "explanation": "语义：未来的方法还没有出现，现在无法试用。"}], "explanations": {"虚构": "语义：虚构的方法不是真实存在的，无法拿来试用。", "现有": "符合语境：指目前已经存在、可以马上试用的方法。", "疲劳": "搭配：“疲劳”形容人或状态，不能修饰“方法”。", "未来": "语义：未来的方法还没有出现，现在无法试用。"}, "sentence_index": 6, "correct_answer": "现有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科学家研究的是现有的恐龙。", "explanation": "〈现有〉指目前仍然存在的事物。恐龙早已灭绝，不再现有，这里应该用〈古代的〉。"}, {"text": "现有的规定早已取消了，大家都不再遵守。", "explanation": "〈现有〉指目前仍然有效或存在的。规定早已取消，不再存在，这里应该用〈过去的〉。"}, {"text": "教室里现有的黑板早就没有了。", "explanation": "〈现有〉指目前存在的事物。黑板早就没有了，这里应该用〈旧的〉，指以前用过、已经不在的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要先把现有地设备检查一遍。", "corrected_sentence": "我们要先把现有的设备检查一遍。", "error_description": "“现有”修饰名词“设备”时要用“的”，应说“现有的设备”；“现有地设备”用“地”错误（“地”用于修饰动词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们现有了的资料很少。", "corrected_sentence": "我们现有的资料很少。", "error_description": "“现有”是形容词，后面不能加“了的”；“现有了的资料”错误，应说“现有的资料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
