INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89081, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不由是自己忍不住,不想那样也那样了。", "primary_collocate": null, "pronunciation": "bù yóu", "ipa": "pu˥˩ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "听到这个好消息,他不由笑了。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着孩子的照片,妈妈不由想起了小时候。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影太感人了,我不由哭了起来。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他突然大叫一声,大家不由回头看他。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走进那间老房子,我不由停下了脚步。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了老师的话,他不由脸红了。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到雪地里的小狗,她不由蹲了下来。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闻到饭菜的香味,我不由咽了咽口水。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得太好笑了,我们不由大声笑起来。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在高高的山顶上,他不由感叹风景真美。", "target_word": "不由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不由得", "label": "复合"}, {"form": "不由自主", "label": "复合"}], "register": "中性", "sense_fingerprint": "副词:自己忍不住,不想那样也那样做了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 6 words above tier T1 (max 2): 闻到 (Zipf 3.82), 饭菜 (Zipf 3.39), 香味 (Zipf 3.72), 咽 (Zipf 3.31), 咽 (Zipf 3.31), 口水 (Zipf 3.5)']::text[], '9b9529bd-5bd4-47cc-94ca-e0bf014980b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89081, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不由", "is_correct": true, "explanation": "不由表示不能自主、忍不住，与“听到这个好消息”后自然笑出来的反应相符。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”表示急忙去做某事，与听到好消息后自然笑出来的情形不符。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示迫于无奈，与好消息带来的愉快心情相矛盾。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”通常修饰勉强去做的动作，不能用来描写听到好消息后自然的笑。"}], "explanations": {"不由": "不由表示不能自主、忍不住，与“听到这个好消息”后自然笑出来的反应相符。", "连忙": "语义：“连忙”表示急忙去做某事，与听到好消息后自然笑出来的情形不符。", "只好": "语义：“只好”表示迫于无奈，与好消息带来的愉快心情相矛盾。", "硬": "搭配：“硬”通常修饰勉强去做的动作，不能用来描写听到好消息后自然的笑。"}, "sentence_index": 0, "correct_answer": "不由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨天路滑，他不由会摔倒。", "explanation": "这里应该用〈不免〉。不由表示忍不住或不能自主，不能用来表示“难免会发生”的可能性。"}, {"text": "你不由笑一笑吧。", "explanation": "不由表示不能自主，是叙述已经发生的反应，不能用于要求或命令别人去做。"}, {"text": "明天我不由去北京开会。", "explanation": "不由表示不能自主，不能用于事先经过考虑的安排，去北京开会是有计划的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89081, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不由", "is_correct": true, "explanation": "不由表示不能自主，与看到小狗后忍不住蹲下的情形相符。"}, {"text": "不断", "is_correct": false, "explanation": "体貌：“不断”表示持续反复地进行，与“蹲了下来”这种一次完成的动作不符。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示延续原来的状态，与看到小狗后才出现的新动作相矛盾。"}, {"text": "乖乖", "is_correct": false, "explanation": "语义：“乖乖”表示听话地照做，与看到小狗后自然蹲下的反应不符。"}], "explanations": {"不由": "不由表示不能自主，与看到小狗后忍不住蹲下的情形相符。", "不断": "体貌：“不断”表示持续反复地进行，与“蹲了下来”这种一次完成的动作不符。", "仍然": "语义：“仍然”表示延续原来的状态，与看到小狗后才出现的新动作相矛盾。", "乖乖": "语义：“乖乖”表示听话地照做，与看到小狗后自然蹲下的反应不符。"}, "sentence_index": 6, "correct_answer": "不由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他不由考了满分。", "explanation": "不由表示忍不住或不能自主的心理或动作，考试得分是努力学习的结果，不能用“不由”来说明。"}, {"text": "他不由很有钱。", "explanation": "不由只能描写人忍不住的反应或动作，不能用来表示拥有财产或某种状态。"}, {"text": "这台电脑不由自动停了下来。", "explanation": "不由表示人不能自主的反应，电脑没有心理或意志，不能用“不由”描述它的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
