INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看见这场雨，他的不由叹了口气。", "corrected_sentence": "看见这场雨，他不由叹了口气。", "error_description": "“不由”是副词，后面不能加“的”变成定语修饰名词。“他的不由叹了口气”不成立，正确说法是“他不由叹了口气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '495c90be-1453-4ef9-9eb5-1da1bf4ebed1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
