INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89083, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "圣人是特别聪明、特别好的人，大家都很敬佩他。", "primary_collocate": null, "pronunciation": "shèng rén", "ipa": "ʂɤŋ˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "大家都说他是圣人，因为他又聪明又善良。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圣人也会犯错，何况我们普通人呢？", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不是圣人，难免会有缺点。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人帮助过很多人，村里人都叫他圣人。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不是圣人，没办法原谅所有人。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话做事都很得体，像个圣人一样。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都希望像圣人那样，做一个好人。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他遇到难题总能冷静地想出办法，同学们都佩服他，叫他圣人。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把他当成圣人，他也有生气的时候。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圣人从不骄傲，总是认真听别人说话。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位圣人", "label": "量词"}, {"form": "聖人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "又聪明又善良、让大家敬佩的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62e3c067-3c4e-4854-b164-7c1afd2d112c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89083, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "圣人", "is_correct": true, "explanation": "正确答案。圣人指特别聪明、品德很好、让人敬佩的人。"}, {"text": "生人", "is_correct": false, "explanation": "shēng（第一声）与 shèng（第四声）声调不同，生人意思是陌生人。"}, {"text": "成人", "is_correct": false, "explanation": "chéng 与 shèng 声母不同（ch/sh）且声调也不同，成人意思是长大的人。"}, {"text": "胜任", "is_correct": false, "explanation": "第二个音节 rèn（第四声）与 rén（第二声）声调不同，胜任意思是能够承担某项工作。"}, {"text": "神人", "is_correct": false, "explanation": "shén 与 shèng 韵尾不同（n/ng）且声调也不同，神人意思是有神通的人。"}], "explanations": {"圣人": "正确答案。圣人指特别聪明、品德很好、让人敬佩的人。", "生人": "shēng（第一声）与 shèng（第四声）声调不同，生人意思是陌生人。", "成人": "chéng 与 shèng 声母不同（ch/sh）且声调也不同，成人意思是长大的人。", "胜任": "第二个音节 rèn（第四声）与 rén（第二声）声调不同，胜任意思是能够承担某项工作。", "神人": "shén 与 shèng 韵尾不同（n/ng）且声调也不同，神人意思是有神通的人。"}, "sentence_index": null, "correct_answer": "圣人"}, "level_3": {"options": [{"text": "小偷", "is_correct": false, "explanation": "语义：小偷指偷东西的人，与“又聪明又善良”的评价相矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有聪明或善良的品质，不能用来评价一个人。"}, {"text": "圣人", "is_correct": true, "explanation": "“圣人”指品德和智慧都很高的人，正好与“又聪明又善良”相符。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“病人”不能与“又聪明又善良”这样的品质描述搭配。"}], "explanations": {"小偷": "语义：小偷指偷东西的人，与“又聪明又善良”的评价相矛盾。", "石头": "语义：石头没有聪明或善良的品质，不能用来评价一个人。", "圣人": "“圣人”指品德和智慧都很高的人，正好与“又聪明又善良”相符。", "病人": "搭配：“病人”不能与“又聪明又善良”这样的品质描述搭配。"}, "sentence_index": 0, "correct_answer": "圣人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们全家一起过圣人，很热闹。", "explanation": "这里应该用〈圣诞节〉。圣人指人，不能用来指节日，过节要说“圣诞节”。"}, {"text": "村里来了一只圣人，大家都去看他。", "explanation": "这里应该用〈位〉。圣人是人，量词要用“位”或“个”，“只”一般用于动物或小东西。"}, {"text": "这块石头是圣人。", "explanation": "这里应该用〈石像〉。圣人指人，石头只能雕成圣人的石像，不能说石头本身是圣人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89083, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "圣人", "is_correct": true, "explanation": "正确答案。圣人指特别聪明、品德很好、让人敬佩的人。"}, {"text": "僧人", "is_correct": false, "explanation": "sēng（第一声）与 shèng（第四声）声母和声调都不同，僧人意思是出家修行的人。"}, {"text": "证人", "is_correct": false, "explanation": "zhèng 与 shèng 声母不同（zh/sh），声调相同，证人意思是为事情作证的人。"}, {"text": "整人", "is_correct": false, "explanation": "zhěng（第三声）与 shèng（第四声）声母不同且声调也不同，整人意思是捉弄、折磨人。"}], "explanations": {"圣人": "正确答案。圣人指特别聪明、品德很好、让人敬佩的人。", "僧人": "sēng（第一声）与 shèng（第四声）声母和声调都不同，僧人意思是出家修行的人。", "证人": "zhèng 与 shèng 声母不同（zh/sh），声调相同，证人意思是为事情作证的人。", "整人": "zhěng（第三声）与 shèng（第四声）声母不同且声调也不同，整人意思是捉弄、折磨人。"}, "sentence_index": null, "correct_answer": "圣人"}, "level_3": {"options": [{"text": "坏人", "is_correct": false, "explanation": "语义：坏人与“做一个好人”的意思相反，句子自相矛盾。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人是对立的人，“希望像敌人那样做一个好人”不通。"}, {"text": "圣人", "is_correct": true, "explanation": "“圣人”是孩子们希望效仿的榜样，与“做一个好人”的语境相符。"}, {"text": "猪", "is_correct": false, "explanation": "语义：猪是动物，孩子们不会希望像猪那样做一个好人，句意不通。"}], "explanations": {"坏人": "语义：坏人与“做一个好人”的意思相反，句子自相矛盾。", "敌人": "语义：敌人是对立的人，“希望像敌人那样做一个好人”不通。", "圣人": "“圣人”是孩子们希望效仿的榜样，与“做一个好人”的语境相符。", "猪": "语义：猪是动物，孩子们不会希望像猪那样做一个好人，句意不通。"}, "sentence_index": 6, "correct_answer": "圣人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "假期我们去了圣人，很多游客在那里拍照。", "explanation": "这里应该用〈圣地〉。圣人指人，圣地才是可以去的地方，不能说去了“圣人”。"}, {"text": "这家餐厅的圣人很好吃，大家都爱来这里吃饭。", "explanation": "这里应该用〈菜〉。圣人指人，不能用来形容食物好吃。"}, {"text": "这辆圣人停在门口，颜色很漂亮。", "explanation": "这里应该用〈汽车〉。圣人指人，不能用来指车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爷爷是一只圣人，村里人都很尊敬他。", "corrected_sentence": "我爷爷是一位圣人，村里人都很尊敬他。", "error_description": "错误形式：“一只圣人”；正确形式：“一位圣人”。“圣人”指人，量词应用“位”，不能用“只”，“只”一般用于动物或小东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小弟弟很想圣人那样，帮助别人。", "corrected_sentence": "小弟弟很想像圣人那样，帮助别人。", "error_description": "错误形式：“想圣人那样”；正确形式：“想像圣人那样”。“圣人那样”前面要加动词“像”，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
