INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89084, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "品德最高尚、智慧最高超的人。", "primary_collocate": null, "pronunciation": "shèng rén", "ipa": "ʂɤŋ˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "后人都称孔子为圣人。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人认为圣人的品德最高尚。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了很多书，想成为圣人那样的人。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圣人的话，后人读了几千年。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在古书里，圣人是智慧最高的人。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了圣人的故事。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圣人治理国家，百姓都过得很好。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，圣人知道天下的道理。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们常说，圣人也有想不到的事。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对古人来说，做圣人是最高的理想。", "target_word": "圣人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位圣人", "label": "量词"}, {"form": "聖人", "label": "繁体"}], "register": "书面", "sense_fingerprint": "古代所说品德和智慧都达到最高境界的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62e3c067-3c4e-4854-b164-7c1afd2d112c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "圣人", "is_correct": true, "explanation": "正确答案。圣人指古代品德和智慧都达到最高境界的人。"}, {"text": "生人", "is_correct": false, "explanation": "shēng（第一声）与 shèng（第四声）声调不同，生人意思是陌生人。"}, {"text": "成人", "is_correct": false, "explanation": "chéng 与 shèng 声母不同（ch/sh）且声调也不同，成人意思是长大的人。"}, {"text": "证人", "is_correct": false, "explanation": "zhèng 与 shèng 声母不同（zh/sh），声调相同，证人意思是为事情作证的人。"}, {"text": "神人", "is_correct": false, "explanation": "shén 与 shèng 韵尾不同（n/ng）且声调也不同，神人意思是有神通的人。"}], "explanations": {"圣人": "正确答案。圣人指古代品德和智慧都达到最高境界的人。", "生人": "shēng（第一声）与 shèng（第四声）声调不同，生人意思是陌生人。", "成人": "chéng 与 shèng 声母不同（ch/sh）且声调也不同，成人意思是长大的人。", "证人": "zhèng 与 shèng 声母不同（zh/sh），声调相同，证人意思是为事情作证的人。", "神人": "shén 与 shèng 韵尾不同（n/ng）且声调也不同，神人意思是有神通的人。"}, "sentence_index": null, "correct_answer": "圣人"}, "level_3": {"options": [{"text": "皇帝", "is_correct": false, "explanation": "语义：皇帝是统治者，“后人都称孔子为皇帝”与史实不符。"}, {"text": "商人", "is_correct": false, "explanation": "语义：孔子不是商人，“称孔子为商人”说法不成立。"}, {"text": "圣人", "is_correct": true, "explanation": "“圣人”指古代品德智慧最高的人，孔子被后人尊为圣人。"}, {"text": "恶人", "is_correct": false, "explanation": "搭配：“后人都称……为恶人”与“后人都称”这种尊敬的说法不搭配。"}], "explanations": {"皇帝": "语义：皇帝是统治者，“后人都称孔子为皇帝”与史实不符。", "商人": "语义：孔子不是商人，“称孔子为商人”说法不成立。", "圣人": "“圣人”指古代品德智慧最高的人，孔子被后人尊为圣人。", "恶人": "搭配：“后人都称……为恶人”与“后人都称”这种尊敬的说法不搭配。"}, "sentence_index": 0, "correct_answer": "圣人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年冬天，我们全家一起过圣人。", "explanation": "这里应该用〈圣诞节〉。圣人指人，不能用来指节日，过节要说“圣诞节”。"}, {"text": "这只猫是圣人，每天都陪着我。", "explanation": "这里应该用〈宠物〉。圣人指人，猫只能说是宠物，不能说是圣人。"}, {"text": "这棵大树是圣人。", "explanation": "这里应该用〈神树〉。圣人指人，被当作神灵崇拜的树才叫神树，不能说大树本身是圣人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89084, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "圣人", "is_correct": true, "explanation": "正确答案。圣人指古代品德和智慧都达到最高境界的人。"}, {"text": "僧人", "is_correct": false, "explanation": "sēng（第一声）与 shèng（第四声）声母和声调都不同，僧人意思是出家修行的人。"}, {"text": "胜任", "is_correct": false, "explanation": "第二个音节 rèn（第四声）与 rén（第二声）声调不同，胜任意思是能够承担某项工作。"}, {"text": "整人", "is_correct": false, "explanation": "zhěng（第三声）与 shèng（第四声）声母不同且声调也不同，整人意思是捉弄、折磨人。"}], "explanations": {"圣人": "正确答案。圣人指古代品德和智慧都达到最高境界的人。", "僧人": "sēng（第一声）与 shèng（第四声）声母和声调都不同，僧人意思是出家修行的人。", "胜任": "第二个音节 rèn（第四声）与 rén（第二声）声调不同，胜任意思是能够承担某项工作。", "整人": "zhěng（第三声）与 shèng（第四声）声母不同且声调也不同，整人意思是捉弄、折磨人。"}, "sentence_index": null, "correct_answer": "圣人"}, "level_3": {"options": [{"text": "小偷", "is_correct": false, "explanation": "语义：小偷不能治理国家，“小偷治理国家”不通。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐是贫苦的人，不能用来指治理国家的人。"}, {"text": "圣人", "is_correct": true, "explanation": "“圣人”指治理国家、让百姓过好日子的理想人物，与句意相符。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：厨师与“治理国家”搭配不当。"}], "explanations": {"小偷": "语义：小偷不能治理国家，“小偷治理国家”不通。", "乞丐": "语义：乞丐是贫苦的人，不能用来指治理国家的人。", "圣人": "“圣人”指治理国家、让百姓过好日子的理想人物，与句意相符。", "厨师": "搭配：厨师与“治理国家”搭配不当。"}, "sentence_index": 6, "correct_answer": "圣人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们村来了一只圣人，大家都去看他。", "explanation": "这里应该用〈位〉。圣人是人，量词要用“位”或“个”，“只”一般用于动物或小东西。"}, {"text": "周末我们一家去了圣人，那里有很多游客。", "explanation": "这里应该用〈圣地〉。圣人指人，圣地才是可以去的地方，不能说去了“圣人”。"}, {"text": "这杯圣人太烫了，等一会儿再喝吧。", "explanation": "这里应该用〈茶〉。圣人指品德和智慧最高的人，不能指饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当时的人都把他看成圣人的。", "corrected_sentence": "当时的人都把他看成圣人。", "error_description": "错误形式：“看成圣人的”；正确形式：“看成圣人”。“把……看成……”后直接接名词作宾语，句末多出“的”，语法不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孔子是一只古代的圣人。", "corrected_sentence": "孔子是一位古代的圣人。", "error_description": "错误形式：“一只圣人”；正确形式：“一位圣人”。“圣人”指人，量词应用“位”，“只”一般用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89085, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89085, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89085, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "发达是变得很强，很多事做得很好。", "primary_collocate": null, "pronunciation": "fā dá", "ipa": "fa˥ ta˧˥", "syllable_count": 2, "sentences": [{"text": "他每天跑步，腿部肌肉特别发达。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗的嗅觉很发达，能找到很小的东西。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他四肢发达，可是头脑也不简单。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是游泳运动员，肩膀的肌肉很发达。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟的翅膀不发达，飞不高。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天练习游泳，手臂肌肉越来越发达了。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝙蝠的听觉非常发达，晚上也能飞。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员的心肺功能一般都很发达。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰的视觉很发达，能看到很远的东西。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象的鼻子很发达，能拿很重的东西。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "变得很强，很多事做得很好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89ee32a3-3677-402a-8adc-801a9e813d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89085, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发达", "is_correct": true, "explanation": "发达：形容肌肉强壮，与“腿部肌肉”搭配，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”多形容体型或建筑，不修饰肌肉。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”形容清洁的状态，不用来形容肌肉。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线或眼神，不用来描述肌肉。"}], "explanations": {"发达": "发达：形容肌肉强壮，与“腿部肌肉”搭配，符合句意。", "高大": "搭配：“高大”多形容体型或建筑，不修饰肌肉。", "干净": "语义：“干净”形容清洁的状态，不用来形容肌肉。", "明亮": "体貌：“明亮”形容光线或眼神，不用来描述肌肉。"}, "sentence_index": 0, "correct_answer": "发达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的反应很发达，球一飞过来就接住了。", "explanation": "这里应该用〈灵敏〉。发达指身体器官或能力变得强，人的反应快慢要用灵敏。"}, {"text": "这个孩子的食欲很发达，一顿能吃三大碗。", "explanation": "这里应该用〈旺盛〉。发达指身体器官或能力变得强，食欲的强弱要用旺盛，不说“食欲很发达”。"}, {"text": "这个孩子的脾气很发达，一句话就哭。", "explanation": "这里应该用〈大〉。发达指身体器官或能力变得强，脾气的大小要用大，不说“脾气很发达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89085, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发达", "is_correct": true, "explanation": "发达：形容听觉灵敏、强壮，与“听觉”搭配，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌好看，不用来修饰听觉。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，听觉不能是甜的。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“整齐”形容排列有序，不用来形容听觉。"}], "explanations": {"发达": "发达：形容听觉灵敏、强壮，与“听觉”搭配，符合句意。", "漂亮": "体貌：“漂亮”形容外貌好看，不用来修饰听觉。", "甜": "语义：“甜”形容味道，听觉不能是甜的。", "整齐": "语义：“整齐”形容排列有序，不用来形容听觉。"}, "sentence_index": 6, "correct_answer": "发达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的个子很发达，比同龄人高很多。", "explanation": "这里应该用〈高〉。发达指身体器官或能力变得强，身高要用高，不说“个子很发达”。"}, {"text": "他的胆子很发达，什么都敢做。", "explanation": "这里应该用〈大〉。发达指身体器官或能力变得强，胆子的大小要用大，不说“胆子很发达”。"}, {"text": "他的收藏很发达，很多人都来看。", "explanation": "这里应该用〈丰富〉。发达用于身体器官或能力的强壮，收藏的数量要用丰富。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的胳膊得发达，力气也大。", "corrected_sentence": "他的胳膊很发达，力气也大。", "error_description": "错误：“得”不能放在“胳膊”和“发达”之间表示程度。应在形容词前用程度副词“很”，说“胳膊很发达”，不能说“胳膊得发达”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老虎的牙齿很发达着，能咬碎骨头。", "corrected_sentence": "老虎的牙齿很发达，能咬碎骨头。", "error_description": "错误：“发达”后面多加了“着”。“很发达”表示性质状态，后面不能加“着”，应去掉“着”，写成“牙齿很发达”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89086, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "落后", "is_correct": true, "explanation": "反义：“落后”指经济、文化等发展水平低，与“发达”构成反义。"}, {"text": "温柔", "is_correct": false, "explanation": "“温柔”形容性情或态度，与“发达”没有反义关系。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容外观好看，与“发达”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容环境无声，与“发达”没有反义关系。"}], "correct_answer": "落后", "explanations": {"落后": "反义：“落后”指经济、文化等发展水平低，与“发达”构成反义。", "温柔": "“温柔”形容性情或态度，与“发达”没有反义关系。", "美丽": "“美丽”形容外观好看，与“发达”没有反义关系。", "安静": "“安静”形容环境无声，与“发达”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89086, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "落后", "is_correct": true, "explanation": "反义：“落后”指经济、事业等发展水平低，与“发达”构成反义。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事情或结构繁多，与“发达”没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”形容表面不光滑，与“发达”没有反义关系。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”形容事物明白、分明，与“发达”没有反义关系。"}], "correct_answer": "落后", "explanations": {"落后": "反义：“落后”指经济、事业等发展水平低，与“发达”构成反义。", "复杂": "“复杂”形容事情或结构繁多，与“发达”没有反义关系。", "粗糙": "“粗糙”形容表面不光滑，与“发达”没有反义关系。", "清晰": "“清晰”形容事物明白、分明，与“发达”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89086, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（事业、经济、文化等）兴盛，进步程度高。", "primary_collocate": null, "pronunciation": "fā dá", "ipa": "fa˥ ta˧˥", "syllable_count": 2, "sentences": [{"text": "日本的经济很发达。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的交通非常发达。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的文化很发达，有很多博物馆。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的网络不太发达，手机常常没有信号。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的地铁很发达，坐车很方便。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，我家乡的旅游业越来越发达了。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欧洲的铁路很发达，去哪儿都很方便。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育发达的地方，人们的生活也更好。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发达的交通让城市和乡村离得更近。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家乡工业不发达，年轻人都去外地工作。", "target_word": "发达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事业、经济、文化等兴盛，进步程度高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89ee32a3-3677-402a-8adc-801a9e813d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发达", "is_correct": true, "explanation": "发达：形容经济兴盛，与“经济”搭配，符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的外形，不说经济高大。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境或人的状态，不用来修饰经济。"}, {"text": "友好", "is_correct": false, "explanation": "搭配：“友好”多用于人与人、国家之间的关系，不修饰经济。"}], "explanations": {"发达": "发达：形容经济兴盛，与“经济”搭配，符合句意。", "高大": "体貌：“高大”形容人或物的外形，不说经济高大。", "安静": "语义：“安静”形容环境或人的状态，不用来修饰经济。", "友好": "搭配：“友好”多用于人与人、国家之间的关系，不修饰经济。"}, "sentence_index": 0, "correct_answer": "发达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个工厂的设备很发达，生产效率提高了很多。", "explanation": "这里应该用〈先进〉。发达用于经济、文化、交通等领域的兴盛，设备的先进程度要用先进。"}, {"text": "这个家庭的收入很发达，每年都能存下不少钱。", "explanation": "这里应该用〈富裕〉。发达说经济、事业的兴盛，家庭收入多、生活宽裕要用富裕。"}, {"text": "这家公司的规模很发达，员工有好几万人。", "explanation": "这里应该用〈庞大〉。发达说经济、事业的兴盛，公司规模大要用庞大，不说“规模很发达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发达", "is_correct": true, "explanation": "发达：形容铁路兴盛、便利，与“铁路”搭配，符合句意。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”形容人或动物的身材，不用于形容铁路。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的态度，铁路不能热情。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的头脑，不修饰铁路。"}], "explanations": {"发达": "发达：形容铁路兴盛、便利，与“铁路”搭配，符合句意。", "瘦小": "体貌：“瘦小”形容人或动物的身材，不用于形容铁路。", "热情": "语义：“热情”形容人的态度，铁路不能热情。", "聪明": "语义：“聪明”形容人的头脑，不修饰铁路。"}, "sentence_index": 6, "correct_answer": "发达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支部队很发达，士兵都很有经验。", "explanation": "这里应该用〈强大〉。发达用于事业、经济、文化等的兴盛，军队的实力要用强大。"}, {"text": "这个小县城的人口很发达，街上每天都很热闹。", "explanation": "这里应该用〈众多〉。发达说经济、事业的兴盛，人数多要用众多，不说“人口很发达”。"}, {"text": "他的工作经验很发达，做事很快。", "explanation": "这里应该用〈丰富〉。发达用于事业、经济、文化等的兴盛，经验的多少要用丰富。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个省的交通得发达。", "corrected_sentence": "这个省的交通很发达。", "error_description": "错误：“得”是结构助词，不能直接放在“交通”和“发达”之间表示程度。应在形容词前用程度副词“很”，说“交通很发达”，不能说“交通得发达”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "北方的工业比南方发达多得。", "corrected_sentence": "北方的工业比南方发达得多。", "error_description": "“比”字句中，“发达”后面的程度补语要用“得”引出，应说“发达得多”，不能说“发达多得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
