INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89087, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中学是小学以后上的学校。", "primary_collocate": null, "pronunciation": "zhōng xué", "ipa": "ʈʂʊŋ˥ ɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "我今年小学毕业，下个月上中学。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学以后，孩子们就去上中学。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐在中学学英语。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所中学离我家很近。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小学在乡下，中学在城里。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在中学里认识，现在还是好朋友。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中学的功课比小学多得多。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟明年要考中学了。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说他的中学在山上。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学毕业后，你想去哪个中学？", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "中学生", "label": "复合"}], "register": "中性", "sense_fingerprint": "小学毕业后上的学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f824fbd0-5911-4073-b89d-fbb10fb08bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89087, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中学", "is_correct": true, "explanation": "正确：“小学毕业”之后升入的学校是中学，符合“下个月上”的语境。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：句中已说“小学毕业”，之后不会再上幼儿园，与语境矛盾。"}, {"text": "小学", "is_correct": false, "explanation": "语义：已经小学毕业，不会再去上小学，与“小学毕业”矛盾。"}, {"text": "大学", "is_correct": false, "explanation": "语义：小学毕业后先上中学，不能直接上大学。"}], "explanations": {"中学": "正确：“小学毕业”之后升入的学校是中学，符合“下个月上”的语境。", "幼儿园": "语义：句中已说“小学毕业”，之后不会再上幼儿园，与语境矛盾。", "小学": "语义：已经小学毕业，不会再去上小学，与“小学毕业”矛盾。", "大学": "语义：小学毕业后先上中学，不能直接上大学。"}, "sentence_index": 0, "correct_answer": "中学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家附近新建了一只中学。", "explanation": "量词用错：〈中学〉是学校，应用〈所〉，“只”用于动物。"}, {"text": "我中学了三年，然后去工作了。", "explanation": "词性用错：〈中学〉是名词，不能直接作动词，应说“上中学”。"}, {"text": "我下个月要去中学读博士。", "explanation": "语义用错：〈中学〉是小学之后、大学之前的学校，读博士应说〈大学〉或〈研究生院〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89087, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中学", "is_correct": true, "explanation": "正确：中学是小学之后的学校，学制更长，功课比小学多，符合比较的语境。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院没有“功课”，比较功课多少说不通。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市不布置功课，句子说不通。"}, {"text": "理发店", "is_correct": false, "explanation": "搭配：“功课”指学习任务，理发店不存在功课，二者不搭配。"}], "explanations": {"中学": "正确：中学是小学之后的学校，学制更长，功课比小学多，符合比较的语境。", "医院": "语义：医院没有“功课”，比较功课多少说不通。", "超市": "语义：超市不布置功课，句子说不通。", "理发店": "搭配：“功课”指学习任务，理发店不存在功课，二者不搭配。"}, "sentence_index": 6, "correct_answer": "中学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我弟弟是一所中学，今年十二岁。", "explanation": "语义用错：〈中学〉指学校，不指人。应说“我弟弟在中学读书”。"}, {"text": "我把中学搬到了新家。", "explanation": "语义用错：把〈中学〉当成了可以搬动的物品（如“家具”），但〈中学〉指学校这一机构；学校迁址应说“迁到新校址”。"}, {"text": "中学是一条河，流过我们的村子。", "explanation": "语义用错：〈中学〉是学校，不是河流，与“流过村子”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
