INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89088, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小学以上、大学以下的学校,分初中和高中。", "primary_collocate": null, "pronunciation": "zhōng xué", "ipa": "ʈʂʊŋ˥ ɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "中学分初中和高中，一共六年。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在中学学了六年英语。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所中学有初中，也有高中。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从中学考上了北京的大学。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中学在小学和大学之间。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有五所中学。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们中学的操场很大。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在中学时，每天骑车上学。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在一所中学教数学。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中学毕业以后，他想去上大学。", "target_word": "中学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "中学生", "label": "复合"}], "register": "中性", "sense_fingerprint": "介于小学与大学之间、分初中和高中的学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f824fbd0-5911-4073-b89d-fbb10fb08bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中学", "is_correct": true, "explanation": "正确：中学分初中和高中，学制六年，符合句意。"}, {"text": "小学", "is_correct": false, "explanation": "语义：小学不分初中和高中，这种说法与小学的学制不符。"}, {"text": "大学", "is_correct": false, "explanation": "语义：大学不分初中和高中，初中、高中是中学的阶段。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园不“分初中和高中”，也不是六年制。"}], "explanations": {"中学": "正确：中学分初中和高中，学制六年，符合句意。", "小学": "语义：小学不分初中和高中，这种说法与小学的学制不符。", "大学": "语义：大学不分初中和高中，初中、高中是中学的阶段。", "幼儿园": "语义：幼儿园不“分初中和高中”，也不是六年制。"}, "sentence_index": 0, "correct_answer": "中学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家附近新建了一棵中学。", "explanation": "量词用错：〈中学〉是学校，应用〈所〉，“棵”用于植物。"}, {"text": "我在中学教大学生，每周三次。", "explanation": "语义用错：〈中学〉不招收大学生，教大学生应说〈大学〉。"}, {"text": "她中学了四年，成绩一直很好。", "explanation": "词性用错：〈中学〉是名词，不能作动词，应说“上中学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中学", "is_correct": true, "explanation": "正确：操场属于学校，“我们中学的操场”指我们就读的学校。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店不设操场，句子说不通。"}, {"text": "地铁站", "is_correct": false, "explanation": "语义：地铁站没有操场，“我们地铁站的操场”说不通。"}, {"text": "菜市场", "is_correct": false, "explanation": "搭配：操场一般属于学校或机关，菜市场不与“操场”搭配。"}], "explanations": {"中学": "正确：操场属于学校，“我们中学的操场”指我们就读的学校。", "理发店": "语义：理发店不设操场，句子说不通。", "地铁站": "语义：地铁站没有操场，“我们地铁站的操场”说不通。", "菜市场": "搭配：操场一般属于学校或机关，菜市场不与“操场”搭配。"}, "sentence_index": 6, "correct_answer": "中学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把中学放进书包里，带去了学校。", "explanation": "语义用错：把〈中学〉当成了可以装进书包的物品（如“书”“本子”），但〈中学〉指学校这一机构，不能放进书包。"}, {"text": "他是我的中学，我们一起长大了。", "explanation": "语义用错：〈中学〉指学校，不指人。"}, {"text": "爸爸每天开着中学去公司上班。", "explanation": "语义用错：把〈中学〉当成了交通工具（如“汽车”），但〈中学〉是学校，不能开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '751ddf0a-a3cf-4de5-88b6-3dd71710d17d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
