INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89089, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "职业教育是教人学会一种工作本领的学校教育。", "primary_collocate": null, "pronunciation": "zhí yè jiào yù", "ipa": "ʈʂɻ̩˧˥ jɛ˥˩ tɕjau˥˩ y˥˩", "syllable_count": 4, "sentences": [{"text": "他在职业教育学校学会了做菜。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上了两年职业教育，她能当护士了。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈希望我接受职业教育，学一门手艺。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "职业教育学校里有修车和电脑课。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受过职业教育，现在是一名电工。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的职业教育课，学生每周去工厂练习。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想早点工作，可以先读职业教育。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐在职业教育学校学了三年美发。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "职业教育能让你学会一门本领，毕业就有工作。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从职业教育学校毕业后，马上找到了工作。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "職業教育", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学校里教人一门工作本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82b70c50-9dc1-4dbc-90ce-dbfb6117b756') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89089, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职业教育", "is_correct": true, "explanation": "正确：“职业教育学校”是学校的类型，与“学会了做菜”相符。"}, {"text": "美术", "is_correct": false, "explanation": "语义：美术学校不教做菜，与“学会了做菜”矛盾。"}, {"text": "体育", "is_correct": false, "explanation": "语义：体育学校不教做菜，与句意不符。"}, {"text": "大学", "is_correct": false, "explanation": "搭配：“大学学校”是重复说法，不能这样搭配。"}], "explanations": {"职业教育": "正确：“职业教育学校”是学校的类型，与“学会了做菜”相符。", "美术": "语义：美术学校不教做菜，与“学会了做菜”矛盾。", "体育": "语义：体育学校不教做菜，与句意不符。", "大学": "搭配：“大学学校”是重复说法，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "职业教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弟弟在职业教育修车，学得很快。", "explanation": "这里应该用〈学校〉。职业教育是教育类型，不能作为修车的场所，要说“在职业教育学校修车”。"}, {"text": "他在职业教育里买了一辆自行车。", "explanation": "这里应该用〈商店〉。职业教育是教育类型，不是可以买东西的场所，要说“在商店里买”。"}, {"text": "我姐姐把职业教育带回家，学了三年美发。", "explanation": "这里应该用〈课本〉。职业教育是抽象的教育类型，不能“带回家”，带回家的是书本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89089, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职业教育", "is_correct": true, "explanation": "正确：“先读职业教育”符合“想早点工作”的目的。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“读”不搭配“电视”，一般说“看电视”。"}, {"text": "童话", "is_correct": false, "explanation": "语义：读童话与“想早点工作”的目的无关。"}, {"text": "驾照", "is_correct": false, "explanation": "搭配：“读”不搭配“驾照”，一般说“考驾照”。"}], "explanations": {"职业教育": "正确：“先读职业教育”符合“想早点工作”的目的。", "电视": "搭配：“读”不搭配“电视”，一般说“看电视”。", "童话": "语义：读童话与“想早点工作”的目的无关。", "驾照": "搭配：“读”不搭配“驾照”，一般说“考驾照”。"}, "sentence_index": 6, "correct_answer": "职业教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从职业教育的操场跑出来。", "explanation": "这里应该用〈学校〉。职业教育是教育类型，不是可以跑出来的场所，应说“从职业教育学校跑出来”。"}, {"text": "他在职业教育上班了两年，学会了修车。", "explanation": "这里应该用〈工厂〉。上班的地点是工厂，职业教育是教育类型，不能作为工作地点。"}, {"text": "她在职业教育实习，学会了护理。", "explanation": "这里应该用〈医院〉。实习的地点是医院，职业教育是教育类型，不能作为实习场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表哥职业教育学校学了开车。", "corrected_sentence": "我表哥在职业教育学校学了开车。", "error_description": "缺少介词：表示动作地点要说“在职业教育学校学”，不能把“职业教育学校”直接放在动词前，应加“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "职业教育比普通教育很重要。", "corrected_sentence": "职业教育比普通教育更重要。", "error_description": "比字句中不能用“很”修饰形容词，应说“更重要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
