INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以培养学生从事某种职业所需的知识和技能为目的的教育。", "primary_collocate": null, "pronunciation": "zhí yè jiào yù", "ipa": "ʈʂɻ̩˧˥ jɛ˥˩ tɕjau˥˩ y˥˩", "syllable_count": 4, "sentences": [{"text": "国家越来越重视职业教育。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "职业教育让学生学到工作需要的技能。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校的职业教育办得很好。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他初中毕业后选择了职业教育。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府每年为职业教育投入很多钱。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "职业教育和普通教育一样重要。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多工厂和学校一起做职业教育。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在职业教育方面工作了十年。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发展职业教育，可以帮助年轻人找到工作。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "职业教育的老师常常要有工作经验。", "target_word": "职业教育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "職業教育", "label": "繁体"}], "register": "中性", "sense_fingerprint": "培养职业知识和技能的教育类型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82b70c50-9dc1-4dbc-90ce-dbfb6117b756') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职业教育", "is_correct": true, "explanation": "正确：“重视”的对象是职业教育这类教育，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“重视”多用于抽象事务，不说“重视冰箱”。"}, {"text": "袜子", "is_correct": false, "explanation": "搭配：“袜子”是具体的日用品，不说“重视袜子”。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“雨伞”是具体日用品，不说“国家重视雨伞”。"}], "explanations": {"职业教育": "正确：“重视”的对象是职业教育这类教育，符合句意。", "冰箱": "搭配：“重视”多用于抽象事务，不说“重视冰箱”。", "袜子": "搭配：“袜子”是具体的日用品，不说“重视袜子”。", "雨伞": "搭配：“雨伞”是具体日用品，不说“国家重视雨伞”。"}, "sentence_index": 0, "correct_answer": "职业教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他初中毕业后选择了一所职业教育。", "explanation": "这里应该用〈种〉。职业教育是一类教育，量词用“种”，“所”用于学校，不用于教育类型。"}, {"text": "他拿到了职业教育。", "explanation": "这里应该用〈学历〉。拿到的是学历或证书，职业教育是一类教育，不能“拿到”。"}, {"text": "他每天穿着职业教育去上班。", "explanation": "这里应该用〈工作服〉。职业教育是教育类型，不能“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职业教育", "is_correct": true, "explanation": "正确：“一起做”的是职业教育，符合句意。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：“病毒”是有害事物，工厂和学校不会“一起做”它。"}, {"text": "冠军", "is_correct": false, "explanation": "搭配：“做”不搭配“冠军”，一般说“争冠军”。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“感情”应说“培养感情”，不说“做感情”。"}], "explanations": {"职业教育": "正确：“一起做”的是职业教育，符合句意。", "病毒": "语义：“病毒”是有害事物，工厂和学校不会“一起做”它。", "冠军": "搭配：“做”不搭配“冠军”，一般说“争冠军”。", "感情": "搭配：“感情”应说“培养感情”，不说“做感情”。"}, "sentence_index": 6, "correct_answer": "职业教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他选修了一门职业教育。", "explanation": "这里应该用〈课程〉。职业教育是教育类型，不能像课程那样被“选修”。"}, {"text": "他去年考上了职业教育。", "explanation": "这里应该用〈学校〉。考上的是学校，职业教育是教育类型，不能“考上”。"}, {"text": "这份职业教育需要很多经验。", "explanation": "这里应该用〈工作〉。需要经验的是工作，职业教育是教育类型，不能充当工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市正在推广一所新的职业教育。", "corrected_sentence": "这个城市正在推广一种新的职业教育。", "error_description": "量词错误：职业教育是一类教育，应说“一种”，“所”用于学校，不能用于职业教育。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校把职业教育办很好。", "corrected_sentence": "这所学校把职业教育办得很好。", "error_description": "补语标记“得”缺失：“办”后带程度补语“很好”，中间必须用“得”引出，应说“办得很好”，不能说“办很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33fdaf12-d7a9-480c-9b1e-82ea21faf955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
