INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89091, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "皮肤是包在我们身体外面的一层。", "primary_collocate": null, "pronunciation": "pí fū", "ipa": "pʰi˧˥ fu˥", "syllable_count": 2, "sentences": [{"text": "皮肤是包在身体外面的一层。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天天气很干，我的皮肤也变干了。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天出门，要保护好皮肤。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的皮肤很白，像牛奶一样。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海边玩了几天，皮肤晒黑了。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完热水澡，皮肤有点红。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的皮肤很容易过敏，不能用这种水。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子的皮肤又软又嫩。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大了，吹得我脸上的皮肤很疼。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看了看我手上的皮肤，说没问题。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "皮膚", "label": "繁体"}, {"form": "一层皮肤", "label": "量词"}, {"form": "皮肤病", "label": "复合"}], "register": "中性", "sense_fingerprint": "皮肤|包在身体外面的一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89ee32a3-3677-402a-8adc-801a9e813d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89091, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皮肤", "is_correct": true, "explanation": "皮肤：指包在身体外面的一层，与句中的定义相符。"}, {"text": "骨头", "is_correct": false, "explanation": "语义：“骨头”位于身体内部，不是包在身体外面的一层。"}, {"text": "指甲", "is_correct": false, "explanation": "搭配：“指甲”只长在手指和脚趾末端，不能说是包在全身外面的一层。"}, {"text": "血液", "is_correct": false, "explanation": "语义：“血液”是流动在血管中的液体，不是一层。"}], "explanations": {"皮肤": "皮肤：指包在身体外面的一层，与句中的定义相符。", "骨头": "语义：“骨头”位于身体内部，不是包在身体外面的一层。", "指甲": "搭配：“指甲”只长在手指和脚趾末端，不能说是包在全身外面的一层。", "血液": "语义：“血液”是流动在血管中的液体，不是一层。"}, "sentence_index": 0, "correct_answer": "皮肤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她有一只很白的皮肤，像牛奶一样。", "explanation": "这里应该用〈层〉。皮肤是覆在身体外面的一层，量词要用“层”，不用“只”。"}, {"text": "这件外套的皮肤很软，穿起来很舒服。", "explanation": "这里应该用〈皮革〉。皮肤指人或动物身体表面的组织，外套的皮料要用皮革。"}, {"text": "这个苹果的皮肤很薄，很容易坏。", "explanation": "这里应该用〈外皮〉。皮肤指人或动物身体的表面，水果的外层要说外皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89091, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皮肤", "is_correct": true, "explanation": "皮肤：包在身体表面的组织，容易过敏，与句意相符。"}, {"text": "膝盖", "is_correct": false, "explanation": "语义：“膝盖”是关节部位，一般不说它容易过敏。"}, {"text": "血管", "is_correct": false, "explanation": "语义：“血管”位于身体内部，不会因这种水而过敏。"}, {"text": "墙壁", "is_correct": false, "explanation": "搭配：“过敏”需要以人或器官作主语，墙壁不能过敏。"}], "explanations": {"皮肤": "皮肤：包在身体表面的组织，容易过敏，与句意相符。", "膝盖": "语义：“膝盖”是关节部位，一般不说它容易过敏。", "血管": "语义：“血管”位于身体内部，不会因这种水而过敏。", "墙壁": "搭配：“过敏”需要以人或器官作主语，墙壁不能过敏。"}, "sentence_index": 6, "correct_answer": "皮肤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我手上有一根皮肤，医生看了看，说没问题。", "explanation": "这里应该用〈层〉。皮肤是覆在身体表面的一层，量词要用“层”，不用“根”。"}, {"text": "这个西瓜的皮肤很硬，不好切。", "explanation": "这里应该用〈果皮〉。皮肤指人或动物身体表面的组织，西瓜的外皮要用果皮。"}, {"text": "这棵树的皮肤很粗糙，有很多裂纹。", "explanation": "这里应该用〈树皮〉。皮肤指身体表面的组织，树的外皮要用树皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89091, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的脸上有一个薄薄的皮肤。", "corrected_sentence": "他的脸上有一层薄薄的皮肤。", "error_description": "“皮肤”的量词应用“层”，不能用“个”。正确说法：一层薄薄的皮肤。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89091, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生检查了他全身的皮肤们。", "corrected_sentence": "医生检查了他全身的皮肤。", "error_description": "“皮肤”不能加“们”表示复数。说全身的皮肤时，直接用“皮肤”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
