INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89092, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "包在人和动物体表面的一层组织。", "primary_collocate": null, "pronunciation": "pí fū", "ipa": "pʰi˧˥ fu˥", "syllable_count": 2, "sentences": [{"text": "人和动物的身体外面都有皮肤。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象的皮肤又厚又硬。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛇的皮肤上有很多小圆点。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青蛙的皮肤总是湿湿的。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，皮肤是人体最大的器官。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗的皮肤上长了红点，要去看医生。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮肤受伤后，身体会慢慢长出新的皮肤。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼的皮肤上有一层小小的鳞。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的皮肤比年轻人的更薄。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热的时候，人的皮肤会出汗。", "target_word": "皮肤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "皮膚", "label": "繁体"}, {"form": "一层皮肤", "label": "量词"}, {"form": "皮肤科", "label": "复合"}], "register": "中性", "sense_fingerprint": "皮肤|人和动物体表的组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89ee32a3-3677-402a-8adc-801a9e813d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "皮肤", "is_correct": true, "explanation": "皮肤：包在人和动物体表的组织，身体外面都有，与句意相符。"}, {"text": "骨骼", "is_correct": false, "explanation": "语义：“骨骼”位于身体内部，不在身体外面。"}, {"text": "内脏", "is_correct": false, "explanation": "语义：“内脏”位于身体内部，不在身体外面。"}, {"text": "尾巴", "is_correct": false, "explanation": "体貌：“尾巴”只有部分动物有，人没有，不能说人和动物都有。"}], "explanations": {"皮肤": "皮肤：包在人和动物体表的组织，身体外面都有，与句意相符。", "骨骼": "语义：“骨骼”位于身体内部，不在身体外面。", "内脏": "语义：“内脏”位于身体内部，不在身体外面。", "尾巴": "体貌：“尾巴”只有部分动物有，人没有，不能说人和动物都有。"}, "sentence_index": 0, "correct_answer": "皮肤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只青蛙有一个皮肤，总是湿湿的。", "explanation": "这里应该用〈层〉。皮肤是覆在身体表面的一层组织，量词用“层”，不用“个”。"}, {"text": "这件皮袄的皮肤很厚，冬天穿很暖和。", "explanation": "这里应该用〈皮毛〉。皮肤指人或动物身体表面的组织，皮袄的毛皮材料要用皮毛。"}, {"text": "这个橘子的皮肤很厚，不好剥。", "explanation": "这里应该用〈果皮〉。皮肤指人或动物身体表面，橘子的外皮要用果皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皮肤", "is_correct": true, "explanation": "皮肤：身体表面的组织，受伤后会重新长出，与句意相符。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是工具，身体不会长出眼镜。"}, {"text": "轮胎", "is_correct": false, "explanation": "语义：“轮胎”不是身体的组织，身体不会长出轮胎。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“长出”不能与“钥匙”搭配。"}], "explanations": {"皮肤": "皮肤：身体表面的组织，受伤后会重新长出，与句意相符。", "眼镜": "语义：“眼镜”是工具，身体不会长出眼镜。", "轮胎": "语义：“轮胎”不是身体的组织，身体不会长出轮胎。", "钥匙": "搭配：“长出”不能与“钥匙”搭配。"}, "sentence_index": 6, "correct_answer": "皮肤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "热的时候，人身上的一颗皮肤会出汗。", "explanation": "这里应该用〈层〉。皮肤是覆在身体表面的一层组织，量词用“层”，不用“颗”。"}, {"text": "这棵老树的皮肤很粗糙，摸起来扎手。", "explanation": "这里应该用〈树皮〉。皮肤指人或动物身体表面的组织，树的外皮要用树皮。"}, {"text": "这双鞋的皮肤很软，穿着很舒服。", "explanation": "这里应该用〈皮革〉。皮肤指身体表面的组织，鞋子的皮料要用皮革。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只青蛙有一条湿湿的皮肤。", "corrected_sentence": "这只青蛙有一层湿湿的皮肤。", "error_description": "“皮肤”的量词应用“层”，“条”用于细长的东西，不能修饰皮肤。正确说法：一层湿湿的皮肤。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他全身的皮肤们都被晒伤了。", "corrected_sentence": "他全身的皮肤都被晒伤了。", "error_description": "“皮肤”不能加“们”表示复数。说全身的皮肤时，直接用“皮肤”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6242c77e-0bac-4651-b20d-8d55972b9ed3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
