INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89094, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89094, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指兄弟的儿子，即侄子。", "primary_collocate": null, "pronunciation": "cóng zǐ", "ipa": "tsʰʊŋ˧˥ tsɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我哥哥的儿子是我的从子，今年十岁。", "target_word": "从子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的从子很聪明，常常来家里问他问题。", "target_word": "从子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只有一个从子，他是弟弟的儿子。", "target_word": "从子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李叔叔带着他的从子去公园放风筝。", "target_word": "从子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张没有儿子，把从子当成自己的孩子。", "target_word": "从子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他哥哥的孩子叫小明，小明是他的从子。", "target_word": "从子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给从子买了一本书，他高兴极了。", "target_word": "从子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从子考上了大学，我这个叔叔很骄傲。", "target_word": "从子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的从子在国外工作，每年春节才回家。", "target_word": "从子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叔父一直把这个从子当作亲生儿子抚养。", "target_word": "从子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "從子", "label": "繁体"}], "register": "书面", "sense_fingerprint": "称呼兄弟的儿子，即侄子，带书面色彩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9d93ac-c6bc-4928-bb2a-fd55abc1e2cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从子", "is_correct": true, "explanation": "正确：从子指兄弟的儿子，与“我哥哥的儿子”相符。"}, {"text": "外甥", "is_correct": false, "explanation": "语义：外甥指姐妹的儿子，与“我哥哥的儿子”矛盾。"}, {"text": "侄女", "is_correct": false, "explanation": "语义：侄女指兄弟的女儿，与“儿子”矛盾。"}, {"text": "令郎", "is_correct": false, "explanation": "语域：令郎是敬称，用于称呼别人的儿子，不用来说自己的侄子。"}], "explanations": {"从子": "正确：从子指兄弟的儿子，与“我哥哥的儿子”相符。", "外甥": "语义：外甥指姐妹的儿子，与“我哥哥的儿子”矛盾。", "侄女": "语义：侄女指兄弟的女儿，与“儿子”矛盾。", "令郎": "语域：令郎是敬称，用于称呼别人的儿子，不用来说自己的侄子。"}, "sentence_index": 0, "correct_answer": "从子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐姐的儿子今年十岁，是我的从子。", "explanation": "这里应该用〈外甥〉。外甥指姐妹的儿子，从子指兄弟的儿子，不能用来称呼姐姐的儿子。"}, {"text": "我哥哥的女儿今年十岁，是我的从子。", "explanation": "这里应该用〈侄女〉。侄女指兄弟的女儿；从子指兄弟的儿子，是男性，不能指女儿。"}, {"text": "我哥哥的孙子是我的从子，他今年五岁。", "explanation": "这里应该用〈侄孙〉。侄孙指侄子的儿子，即哥哥的孙子；从子指兄弟的儿子，不指孙辈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从子", "is_correct": true, "explanation": "正确：从子指兄弟的儿子，这里指受赠的侄子。"}, {"text": "令侄", "is_correct": false, "explanation": "语域：令侄是敬称，用于称呼别人的侄子，用来说自己的侄子不合语域。"}, {"text": "外甥女", "is_correct": false, "explanation": "语义：外甥女是女性，与后半句的“他”矛盾。"}, {"text": "嫂子", "is_correct": false, "explanation": "语义：嫂子是女性，与“他”矛盾，也不是晚辈。"}], "explanations": {"从子": "正确：从子指兄弟的儿子，这里指受赠的侄子。", "令侄": "语域：令侄是敬称，用于称呼别人的侄子，用来说自己的侄子不合语域。", "外甥女": "语义：外甥女是女性，与后半句的“他”矛盾。", "嫂子": "语义：嫂子是女性，与“他”矛盾，也不是晚辈。"}, "sentence_index": 6, "correct_answer": "从子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我舅舅家的小儿子是我的从子，我们常一起玩。", "explanation": "这里应该用〈表弟〉。表弟指舅舅家的男孩；从子指兄弟的儿子，不指舅舅家的孩子。"}, {"text": "我妹妹的女儿是我的从子，她今年五岁。", "explanation": "这里应该用〈外甥女〉。外甥女指姐妹的女儿；从子指兄弟的儿子，是男性，与妹妹无关。"}, {"text": "我女儿的儿子是我的从子，他今年五岁。", "explanation": "这里应该用〈外孙〉。外孙指女儿的儿子；从子指兄弟的儿子，与女儿无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我二叔家有一只从子，他很会踢足球。", "corrected_sentence": "我二叔家有一个从子，他很会踢足球。", "error_description": "“从子”指人，量词应用“个”，不能用“只”，应说“一个从子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个暑假，我的两从子要来北京玩。", "corrected_sentence": "这个暑假，我的两个从子要来北京玩。", "error_description": "数词“两”修饰“从子”时需要量词“个”，应说“两个从子”，不说“两从子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df7e2956-75fe-40d5-a35f-af5b37bc4892') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
