INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由水滴或冰晶聚集而成、飘浮在空中的物体。", "primary_collocate": null, "pronunciation": "yún", "ipa": "yn˧˥", "syllable_count": 1, "sentences": [{"text": "天上有很多云。", "target_word": "云", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天的云很白。", "target_word": "云", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山上的云慢慢飘走了。", "target_word": "云", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机从云上飞过。", "target_word": "云", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云越来越多，要下雨了。", "target_word": "云", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "云把太阳挡住了。", "target_word": "云", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们爬到了云的上面。", "target_word": "云", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看，那朵云像一只兔子。", "target_word": "云", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外的云红红的，真美。", "target_word": "云", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山很高，云在山腰飘着。", "target_word": "云", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "朵", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "白云", "label": "复合"}, {"form": "乌云", "label": "复合"}, {"form": "云朵", "label": "复合"}, {"form": "雲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "空中由水滴或冰晶聚成的云", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07800451-dd71-4009-8d4c-1927c61a756d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89096, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "云", "is_correct": true, "explanation": "云（yún）：飘浮在天空中、由水滴或冰晶聚成的物体。"}, {"text": "运", "is_correct": false, "explanation": "yùn（第四声）与 yún（第二声）声调不同，意思是运动、运气。"}, {"text": "允", "is_correct": false, "explanation": "yǔn（第三声）与 yún（第二声）声调不同，意思是允许。"}, {"text": "晕", "is_correct": false, "explanation": "yūn（第一声）与 yún（第二声）声调不同，意思是头晕、眩晕。"}, {"text": "孕", "is_correct": false, "explanation": "yùn（第四声）与 yún（第二声）声调不同，意思是怀孕。"}], "explanations": {"云": "云（yún）：飘浮在天空中、由水滴或冰晶聚成的物体。", "运": "yùn（第四声）与 yún（第二声）声调不同，意思是运动、运气。", "允": "yǔn（第三声）与 yún（第二声）声调不同，意思是允许。", "晕": "yūn（第一声）与 yún（第二声）声调不同，意思是头晕、眩晕。", "孕": "yùn（第四声）与 yún（第二声）声调不同，意思是怀孕。"}, "sentence_index": null, "correct_answer": "云"}, "level_3": {"options": [{"text": "云", "is_correct": true, "explanation": "云：飘在天上的水汽凝结物，与“天上有很多”相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：天上只有一个太阳，不能说“很多”。"}, {"text": "湖", "is_correct": false, "explanation": "体貌：湖是地面上静止的水面，形体不会飘浮在天上。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子建在地面上，不会出现在天上。"}], "explanations": {"云": "云：飘在天上的水汽凝结物，与“天上有很多”相符。", "太阳": "语义：天上只有一个太阳，不能说“很多”。", "湖": "体貌：湖是地面上静止的水面，形体不会飘浮在天上。", "房子": "语义：房子建在地面上，不会出现在天上。"}, "sentence_index": 0, "correct_answer": "云"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天上飘着一只云，白白的。", "explanation": "这里应该用〈朵〉或〈片〉。“只”用于动物或成对的东西，云不用“只”。"}, {"text": "厨房里冒出了很多云。", "explanation": "这里应该用〈烟〉。云指天上飘浮的水汽凝结物，厨房里冒出的是燃烧产生的烟。"}, {"text": "天上下起了大云。", "explanation": "这里应该用〈雨〉。下雨不能说“下云”，云不会落下来，落下来的是雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89096, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "云", "is_correct": true, "explanation": "云（yún）：飘浮在天空中、由水滴或冰晶聚成的物体。"}, {"text": "韵", "is_correct": false, "explanation": "yùn（第四声）与 yún（第二声）声调不同，意思是韵律、押韵。"}, {"text": "圆", "is_correct": false, "explanation": "yuán 与 yún 韵母不同，声调相同，意思是圆形。"}, {"text": "元", "is_correct": false, "explanation": "yuán 与 yún 韵母不同，声调相同，意思是货币单位“元”。"}, {"text": "熨", "is_correct": false, "explanation": "yùn（第四声）与 yún（第二声）声调不同，意思是用熨斗把衣服烫平。"}], "explanations": {"云": "云（yún）：飘浮在天空中、由水滴或冰晶聚成的物体。", "韵": "yùn（第四声）与 yún（第二声）声调不同，意思是韵律、押韵。", "圆": "yuán 与 yún 韵母不同，声调相同，意思是圆形。", "元": "yuán 与 yún 韵母不同，声调相同，意思是货币单位“元”。", "熨": "yùn（第四声）与 yún（第二声）声调不同，意思是用熨斗把衣服烫平。"}, "sentence_index": null, "correct_answer": "云"}, "level_3": {"options": [{"text": "云", "is_correct": true, "explanation": "云：飘在空中的物体，人可以爬到山上，山上方有云。"}, {"text": "声音", "is_correct": false, "explanation": "体貌：声音没有形体，无法爬到它的上面。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见、摸不着，无法爬到它的上面。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子只是光被挡住后留下的暗处，无法爬到它的上面。"}], "explanations": {"云": "云：飘在空中的物体，人可以爬到山上，山上方有云。", "声音": "体貌：声音没有形体，无法爬到它的上面。", "空气": "语义：空气看不见、摸不着，无法爬到它的上面。", "影子": "语义：影子只是光被挡住后留下的暗处，无法爬到它的上面。"}, "sentence_index": 6, "correct_answer": "云"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山上飘着一座云，又高又白。", "explanation": "这里应该用〈朵〉或〈片〉。“座”用于山、房屋等大型固定的东西，云不用“座”。"}, {"text": "茶杯上方飘着云。", "explanation": "这里应该用〈热气〉。茶杯上方升起的是热气，云是天上的水汽凝结物。"}, {"text": "屋子里飞满了云。", "explanation": "这里应该用〈灰尘〉。屋里飞的是灰尘，云只在天空中飘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天边飘来一个云。", "corrected_sentence": "天边飘来一朵云。", "error_description": "量词错误：“云”应与量词“朵”搭配，说“一朵云”，不说“一个云”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山腰上飘着一颗云。", "corrected_sentence": "山腰上飘着一片云。", "error_description": "量词错误：“颗”用于星星、珠子这类小而圆的东西，云不用“颗”。应说“一片云”，不说“一颗云”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
