INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89098, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听凭；任凭，不加干涉。", "primary_collocate": null, "pronunciation": "tīng rèn", "ipa": "tʰiŋ˥ ʐən˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈不能听任孩子整天玩手机。", "target_word": "听任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听任别人批评，一句话也不说。", "target_word": "听任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师听任学生自己选题目。", "target_word": "听任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能听任环境变坏。", "target_word": "听任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她听任头发长长，一直没有剪。", "target_word": "听任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听任事情发展，什么也没做。", "target_word": "听任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母听任孩子自己决定未来。", "target_word": "听任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生不会听任病人乱吃药。", "target_word": "听任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人听任孙女在院子里养了一只猫。", "target_word": "听任", "complexity_tier": "T3", "furigana": "lǎorén tīngrèn sūnnǚ zài yuànzi lǐ yǎng le yì zhī māo", "sentence_source": "generated"}, {"text": "公司不能听任问题一直存在。", "target_word": "听任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听任着", "label": "体标"}], "register": "书面", "sense_fingerprint": "任凭事情发展而不加干涉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a929c76-6771-4b07-b944-72f67b1dd6c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是赞赏美好的事物，与“整天玩手机”这种消极行为不相合。"}, {"text": "听任", "is_correct": true, "explanation": "“听任”指不加干涉、任其发展，与“不能”和“整天玩手机”的消极行为相合。"}, {"text": "布置", "is_correct": false, "explanation": "搭配：“布置”搭配任务、作业，不能说“布置孩子整天玩手机”。"}, {"text": "鞭策", "is_correct": false, "explanation": "语义：“鞭策”是督促人上进，与“整天玩手机”的消极行为相矛盾。"}], "explanations": {"欣赏": "语义：“欣赏”是赞赏美好的事物，与“整天玩手机”这种消极行为不相合。", "听任": "“听任”指不加干涉、任其发展，与“不能”和“整天玩手机”的消极行为相合。", "布置": "搭配：“布置”搭配任务、作业，不能说“布置孩子整天玩手机”。", "鞭策": "语义：“鞭策”是督促人上进，与“整天玩手机”的消极行为相矛盾。"}, "sentence_index": 0, "correct_answer": "听任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们听任了老师的劝告，马上回到座位上。", "explanation": "这里应该用〈听从〉。听任表示不加干涉、任其发展，不能用来表示接受别人的劝告；服从劝告要用听从。"}, {"text": "老师听任了学生的意见，重新安排了座位。", "explanation": "这里应该用〈听取〉。听任表示不加干涉、任其发展，不能用来表示认真考虑别人的意见；考虑意见要用听取。"}, {"text": "他听任了朋友的谣言，就辞了职。", "explanation": "这里应该用〈听信〉。听任表示不加干涉，不能用来表示相信别人的话；轻信谣言要用听信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修改", "is_correct": false, "explanation": "语义：“修改”是改动已有的东西，不能用来指孩子对未来的决定。"}, {"text": "撤销", "is_correct": false, "explanation": "语义：“撤销”指取消已经定下的事，与“自己决定未来”不相合。"}, {"text": "听任", "is_correct": true, "explanation": "“听任”指不加干涉、任其发展，与“孩子自己决定未来”的句意相合。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”搭配作业、试卷，不能说“批改孩子自己决定未来”。"}], "explanations": {"修改": "语义：“修改”是改动已有的东西，不能用来指孩子对未来的决定。", "撤销": "语义：“撤销”指取消已经定下的事，与“自己决定未来”不相合。", "听任": "“听任”指不加干涉、任其发展，与“孩子自己决定未来”的句意相合。", "批改": "搭配：“批改”搭配作业、试卷，不能说“批改孩子自己决定未来”。"}, "sentence_index": 6, "correct_answer": "听任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司立即听任了这份申请，马上签了字。", "explanation": "这里应该用〈批准〉。听任表示不加干涉、任其发展，不能用来表示同意申请；同意申请要用批准。"}, {"text": "警察听任了门外的敲门声，赶紧跑去开门。", "explanation": "这里应该用〈听见〉。听任表示不加干涉、任其发展，不能用来表示听到声音；听到声音要用听见。"}, {"text": "工人听任了坏掉的水管，马上找来工具把它修好了。", "explanation": "这里应该用〈修理〉。听任表示不加干涉，句中却马上动手修好水管，与“听任”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他听任那只孩子自己选择颜色。", "corrected_sentence": "他听任那个孩子自己选择颜色。", "error_description": "量词错误：“孩子”指人，应用“个”计量，不能用“只”（“只”多用于动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父亲不能听任了孩子在河边玩水。", "corrected_sentence": "父亲不能听任孩子在河边玩水。", "error_description": "体标错误：“不能”表示不允许，与表示完成的“了”不能同用；应说“不能听任孩子”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
