INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89101, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "恰当是说做得刚刚好，不多也不少。", "primary_collocate": null, "pronunciation": "qià dàng", "ipa": "tɕʰja˥˩ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这道菜的盐放得很恰当。", "target_word": "恰当", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次的价格定得很恰当。", "target_word": "恰当", "complexity_tier": "T3", "furigana": "zhè cì de jià gé dìng de hěn qià dàng.", "sentence_source": "generated"}, {"text": "水温不高也不低，非常恰当。", "target_word": "恰当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们的作业量很恰当。", "target_word": "恰当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间里的灯光亮度恰当，不太亮也不太暗。", "target_word": "恰当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把时间安排得恰当，不早也不晚。", "target_word": "恰当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗汤的咸淡很恰当。", "target_word": "恰当", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的菜量恰当，一个人刚好吃完。", "target_word": "恰当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里的温度恰当，不冷也不热。", "target_word": "恰当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "米饭的水加得很恰当。", "target_word": "恰当", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "恰當", "label": "繁体"}, {"form": "不恰当", "label": "否定"}, {"form": "恰当地", "label": "状语"}], "register": "书面", "sense_fingerprint": "分量、程度刚刚好，不多不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6647e966-3b9b-4961-8f34-a054baa978bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89101, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恰当", "is_correct": true, "explanation": "“恰当”指分量刚刚好，盐放得不多不少，与句意相符。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容摆放得有条理，不用来说调味料的分量。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外观好看或做事出色，不用来评价盐的用量。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：“凉快”指温度让人舒适，与盐的用量无关。"}], "explanations": {"恰当": "“恰当”指分量刚刚好，盐放得不多不少，与句意相符。", "整齐": "搭配：“整齐”形容摆放得有条理，不用来说调味料的分量。", "漂亮": "体貌：“漂亮”形容外观好看或做事出色，不用来评价盐的用量。", "凉快": "语义：“凉快”指温度让人舒适，与盐的用量无关。"}, "sentence_index": 0, "correct_answer": "恰当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山很恰当，抬头看不到山顶。", "explanation": "这里应该用〈高〉。恰当指分量或程度刚好，不用来形容山的高矮。"}, {"text": "他的脾气很恰当，从不发火。", "explanation": "这里应该用〈温和〉。恰当指分寸或程度刚好，不用来形容人的性格脾气。"}, {"text": "这个苹果很恰当，大得一只手拿不住。", "explanation": "这里应该用〈大〉。恰当指分量或程度刚好，不用来形容苹果的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89101, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恰当", "is_correct": true, "explanation": "“恰当”指咸淡刚刚好，与句意相符。"}, {"text": "美观", "is_correct": false, "explanation": "体貌：“美观”形容外形好看，不用来评价汤的咸淡。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”说温度低，不能用来描述咸淡。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”形容物体坚固，不能用来说咸淡。"}], "explanations": {"恰当": "“恰当”指咸淡刚刚好，与句意相符。", "美观": "体貌：“美观”形容外形好看，不用来评价汤的咸淡。", "冷": "语义：“冷”说温度低，不能用来描述咸淡。", "结实": "语义：“结实”形容物体坚固，不能用来说咸淡。"}, "sentence_index": 6, "correct_answer": "恰当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子很恰当，爱说爱笑。", "explanation": "这里应该用〈活泼〉。恰当指分寸或程度刚好，不用来形容人的性格。"}, {"text": "她的脸很恰当，很耐看。", "explanation": "这里应该用〈漂亮〉。恰当不用来形容人的外貌。"}, {"text": "那座楼很恰当，远远就能看见。", "explanation": "这里应该用〈高大〉。恰当指分寸刚好，不用来形容建筑的体积与高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89101, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他按照恰当地比例调了酱汁。", "corrected_sentence": "他按照恰当的比例调了酱汁。", "error_description": "“恰当”修饰名词“比例”时要用“的”，不用“地”；“地”是状语的标志，后面不能直接接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89101, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把分量定很恰当。", "corrected_sentence": "他把分量定得很恰当。", "error_description": "补语要用“得”连接：“定得很恰当”。这里漏掉了“得”，应为“定得”，不能直接说“定很恰当”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
