INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89102, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "合适，妥当，没有不合适的地方。", "primary_collocate": null, "pronunciation": "qià dàng", "ipa": "tɕʰja˥˩ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的回答很恰当。", "target_word": "恰当", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在会议上这样说话不太恰当。", "target_word": "恰当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你用这个词不恰当，应该换一个。", "target_word": "恰当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师对这件事的处理很恰当。", "target_word": "恰当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "给老人送这样的礼物，恰当吗？", "target_word": "恰当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个题目的名字起得很恰当。", "target_word": "恰当", "complexity_tier": "T3", "furigana": "zhè ge tí mù de míng zi qǐ de hěn qià dàng.", "sentence_source": "generated"}, {"text": "他对朋友说了一句很恰当的话。", "target_word": "恰当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加婚礼穿成这样，恐怕不恰当。", "target_word": "恰当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理选了一个恰当的时间开会。", "target_word": "恰当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到问题，要用恰当的方法解决。", "target_word": "恰当", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "恰當", "label": "繁体"}, {"form": "不恰当", "label": "否定"}, {"form": "恰当地", "label": "状语"}], "register": "书面", "sense_fingerprint": "言语、做法、用词合适妥当", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6647e966-3b9b-4961-8f34-a054baa978bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恰当", "is_correct": true, "explanation": "“恰当”指言语或做法合适妥当，与“回答很好”的句意相符。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”形容物体坚固，不能用来评价回答。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线明亮，不用来形容回答的好坏。"}, {"text": "美观", "is_correct": false, "explanation": "体貌：“美观”形容外形好看，不能用来评价回答。"}], "explanations": {"恰当": "“恰当”指言语或做法合适妥当，与“回答很好”的句意相符。", "结实": "语义：“结实”形容物体坚固，不能用来评价回答。", "亮": "语义：“亮”指光线明亮，不用来形容回答的好坏。", "美观": "体貌：“美观”形容外形好看，不能用来评价回答。"}, "sentence_index": 0, "correct_answer": "恰当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身材很恰当，又高又瘦。", "explanation": "这里应该用〈匀称〉。恰当指言语、做法合适，不用来形容体形。"}, {"text": "他的声音很恰当，又响又亮。", "explanation": "这里应该用〈洪亮〉。恰当指言语、做法合适，不用来形容声音的大小。"}, {"text": "他的字写得很恰当，一行一行很整齐。", "explanation": "这里应该用〈整齐〉。恰当不用来形容字迹排列的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恰当", "is_correct": true, "explanation": "“恰当”指话语合适妥当，与“对朋友说了一句很好的话”相符。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”形容地势很斜，不能修饰话语。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”形容空间小，不能用来修饰话语。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列有序，不用来修饰一句话。"}], "explanations": {"恰当": "“恰当”指话语合适妥当，与“对朋友说了一句很好的话”相符。", "陡峭": "语义：“陡峭”形容地势很斜，不能修饰话语。", "狭窄": "语义：“狭窄”形容空间小，不能用来修饰话语。", "整齐": "搭配：“整齐”形容排列有序，不用来修饰一句话。"}, "sentence_index": 6, "correct_answer": "恰当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的水很恰当，清澈见底。", "explanation": "这里应该用〈清澈〉。恰当指言语、做法合适，不用来形容水的清浅透明。"}, {"text": "这块石头很恰当，一敲就碎。", "explanation": "这里应该用〈脆〉。恰当指言语、做法合适，不用来形容石头的软硬。"}, {"text": "这段山路很恰当，走起来很累。", "explanation": "这里应该用〈陡峭〉。恰当不用来形容地势的坡度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "用恰当地语言回答问题，才显得礼貌。", "corrected_sentence": "用恰当的语言回答问题，才显得礼貌。", "error_description": "“恰当”修饰名词“语言”时要用“的”，不用“地”；“地”用来修饰动词，后面不能直接接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说话说很恰当，大家都满意。", "corrected_sentence": "他说话说得很恰当，大家都满意。", "error_description": "补语要用“得”连接：“说得很恰当”。这里漏掉了“得”，应为“说得”，不能直接说“说很恰当”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd1dee54-afbc-401f-8266-6ee2a84a3622') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
