INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89103, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "到时是说到了那个时候。", "primary_collocate": null, "pronunciation": "dào shí", "ipa": "tɑʊ˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "你把地址发给我，到时我自己去。", "target_word": "到时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还小，到时他就懂了。", "target_word": "到时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九月新学期开始，到时我们就忙了。", "target_word": "到时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不够没关系，到时我借给你。", "target_word": "到时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先别告诉她，到时给她一个惊喜。", "target_word": "到时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们八点见，到时别迟到。", "target_word": "到时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天快到了，到时花都会开。", "target_word": "到时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车票我来订，到时你准时到就行。", "target_word": "到时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说下周考试，到时要带笔。", "target_word": "到时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别着急，到时一定有办法。", "target_word": "到时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "说话时指将来的那个时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 车票 (Zipf 3.93), 准时 (Zipf 3.94), 就行 (Zipf 3.74)']::text[], '216324cd-0d1f-4db4-b00d-b0895e448e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89103, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "到时", "is_correct": true, "explanation": "正确答案：到时（dào shí），意思是说到将来的那个时候。"}, {"text": "倒是", "is_correct": false, "explanation": "倒是（dàoshì）与 dào shí 第二个音节声调不同（shì 与 shí），意思是表示转折或让步的副词。"}, {"text": "导师", "is_correct": false, "explanation": "导师（dǎoshī）与 dào shí 两个音节的声调都不同，意思是指导学生的老师。"}, {"text": "道士", "is_correct": false, "explanation": "道士（dàoshi）第二个音节读轻声，与 shí 不同，意思是道教的修行人员。"}], "explanations": {"到时": "正确答案：到时（dào shí），意思是说到将来的那个时候。", "倒是": "倒是（dàoshì）与 dào shí 第二个音节声调不同（shì 与 shí），意思是表示转折或让步的副词。", "导师": "导师（dǎoshī）与 dào shí 两个音节的声调都不同，意思是指导学生的老师。", "道士": "道士（dàoshi）第二个音节读轻声，与 shí 不同，意思是道教的修行人员。"}, "sentence_index": null, "correct_answer": "到时"}, "level_3": {"options": [{"text": "到时", "is_correct": true, "explanation": "“到时”指将来的那个时候，与“发地址给我”之后“我自己去”的先后安排相合。"}, {"text": "终于", "is_correct": false, "explanation": "语义：“终于”表示经过较长过程后出现的结果，与“发地址给我”这一先后安排不符。"}, {"text": "原来", "is_correct": false, "explanation": "语义：“原来”指先前的情况，不能指将来的时候。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”多用于意外发生的事，不能与事先安排好的“我自己去”搭配。"}], "explanations": {"到时": "“到时”指将来的那个时候，与“发地址给我”之后“我自己去”的先后安排相合。", "终于": "语义：“终于”表示经过较长过程后出现的结果，与“发地址给我”这一先后安排不符。", "原来": "语义：“原来”指先前的情况，不能指将来的时候。", "忽然": "搭配：“忽然”多用于意外发生的事，不能与事先安排好的“我自己去”搭配。"}, "sentence_index": 0, "correct_answer": "到时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去年我在北京工作，到时经常下雪。", "explanation": "这里应该用〈当时〉。“到时”指将来的那个时候，叙述过去的情况要用“当时”。"}, {"text": "刚才我在厨房，到时听见了敲门声。", "explanation": "这里应该用〈当时〉。“到时”指将来的那个时候，描述刚刚发生的事要用“当时”。"}, {"text": "当年我们一起读书，到时常常去图书馆。", "explanation": "这里应该用〈那时〉。“到时”指将来的那个时候，回忆过去的情形要用“那时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89103, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到时", "is_correct": true, "explanation": "“到时”指将来的那个时候，与“春天快到了”之后花开的情况相合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去有过的情况，不能指“春天快到了”之后的将来时刻。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时发生，与“花都会开”这种整体的将来情况不合。"}, {"text": "一度", "is_correct": false, "explanation": "语义：“一度”指过去的某一段时间，不能指将来的时候。"}], "explanations": {"到时": "“到时”指将来的那个时候，与“春天快到了”之后花开的情况相合。", "曾经": "语义：“曾经”指过去有过的情况，不能指“春天快到了”之后的将来时刻。", "偶尔": "语义：“偶尔”表示有时发生，与“花都会开”这种整体的将来情况不合。", "一度": "语义：“一度”指过去的某一段时间，不能指将来的时候。"}, "sentence_index": 6, "correct_answer": "到时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天晚上十点，到时我已经睡了。", "explanation": "这里应该用〈那时〉。“到时”指将来的那个时候，说过去的时间要用“那时”。"}, {"text": "现在到时他正在开会。", "explanation": "这里应该用〈此时〉。“到时”指将来的某个时刻，不能用来指现在正在进行的事。"}, {"text": "到时下雨，他都带伞。", "explanation": "这里应该用〈每次〉。“到时”只指将来某个时刻，不能表示反复出现的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很到时我们再商量一下吧。", "corrected_sentence": "到时我们再商量一下吧。", "error_description": "“到时”是时间副词，不能受程度副词“很”修饰。应为“到时我们再商量一下吧”，删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年到时我还在上学。", "corrected_sentence": "去年那时我还在上学。", "error_description": "“到时”只指将来的那个时候，不能用于过去。说过去的时间应该用“那时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97678c2-93b8-41c8-a793-08b9f2880391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
