INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "带有花纹或杂色的毛织物，多用于制作外衣。", "primary_collocate": null, "pronunciation": "huā ní", "ipa": "xwa˥ ni˧˥", "syllable_count": 2, "sentences": [{"text": "这件外衣的料子是花呢。", "target_word": "花呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "灰色花呢看起来很稳重。", "target_word": "花呢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里的花呢都打折了。", "target_word": "花呢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂专门生产花呢。", "target_word": "花呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他挑了一块深蓝色的花呢。", "target_word": "花呢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花呢摸起来比较厚实。", "target_word": "花呢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她穿着一件花呢做的外衣。", "target_word": "花呢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁缝用花呢给客人做了一套西装。", "target_word": "花呢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种花呢适合做秋冬的外衣。", "target_word": "花呢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店卖的花呢颜色很多，价格也不贵。", "target_word": "花呢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块花呢", "label": "量词"}, {"form": "花呢大衣", "label": "复合"}, {"form": "花呢西装", "label": "复合"}], "register": "通用", "sense_fingerprint": "带花纹或杂色的毛织物，多做外衣面料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a929c76-6771-4b07-b944-72f67b1dd6c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花朵", "is_correct": false, "explanation": "语义：花朵是植物，不能作外衣的料子。"}, {"text": "花呢", "is_correct": true, "explanation": "“花呢”是毛织物，是外衣常用的料子，与句意相合。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能作衣服的面料。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“料子”指布料或材质，不能说“这件外衣的料子是颜色”。"}], "explanations": {"花朵": "语义：花朵是植物，不能作外衣的料子。", "花呢": "“花呢”是毛织物，是外衣常用的料子，与句意相合。", "面包": "语义：面包是食物，不能作衣服的面料。", "颜色": "搭配：“料子”指布料或材质，不能说“这件外衣的料子是颜色”。"}, "sentence_index": 0, "correct_answer": "花呢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双靴子是用花呢做的，防水。", "explanation": "这里应该用〈橡胶〉。花呢是毛织物，不防水，防水的靴子要用橡胶。"}, {"text": "我用花呢煮了一锅汤。", "explanation": "这里应该用〈蔬菜〉。花呢是毛织物，不能用来煮汤，煮汤要用蔬菜。"}, {"text": "这个茶壶是用花呢做的，能烧水。", "explanation": "这里应该用〈金属〉。花呢是毛织物，不能烧水，茶壶要用金属或陶瓷做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面条", "is_correct": false, "explanation": "语义：面条是食物，不能用来做外衣。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头硬而沉，不能用来做衣服的料子。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不是布料，不能用来做外衣。"}, {"text": "花呢", "is_correct": true, "explanation": "“花呢”是毛织物，可以做外衣，说“一件花呢做的外衣”相合。"}], "explanations": {"面条": "语义：面条是食物，不能用来做外衣。", "石头": "语义：石头硬而沉，不能用来做衣服的料子。", "小说": "语义：小说是文学作品，不是布料，不能用来做外衣。", "花呢": "“花呢”是毛织物，可以做外衣，说“一件花呢做的外衣”相合。"}, "sentence_index": 6, "correct_answer": "花呢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用花呢擦掉了铅笔字。", "explanation": "这里应该用〈橡皮〉。花呢是毛织物，擦掉铅笔字要用橡皮。"}, {"text": "下雨了，她撑开了花呢。", "explanation": "这里应该用〈雨伞〉。花呢是布料，不能挡雨，撑开挡雨要用雨伞。"}, {"text": "这扇窗户是用花呢做的。", "explanation": "这里应该用〈玻璃〉。花呢是毛织物，不能做窗户，窗户要用玻璃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的花呢质量很好，我买了一条。", "corrected_sentence": "这家店的花呢质量很好，我买了一块。", "error_description": "量词错误：花呢是布料，应用“块”计量，不能用“条”（“条”用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她吃了一块灰色花呢，准备做外套。", "corrected_sentence": "她买了一块灰色花呢，准备做外套。", "error_description": "搭配错误：“花呢”是布料，不能“吃”，应说“买”；“吃”只能用于食物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dd20cd9-7990-479b-a00f-105ca6b91a7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
