INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89107, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "等级是从高到低分成的一级一级。", "primary_collocate": null, "pronunciation": "děng jí", "ipa": "tɤŋ²¹⁴ tɕi³⁵", "syllable_count": 2, "sentences": [{"text": "这个国家以前有很严格的等级。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代社会分成不同的等级。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里的等级太多，工作很慢。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不看重等级，对谁都很客气。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在古代的宫廷里，大臣有不同的等级。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队里有清楚的等级，下级要听上级的。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的等级比我高，所以我要听他的。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，穿什么衣服要看你的等级。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的等级很清楚，从经理到工人一共有六级。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人和人没有高低等级，大家都是平等的。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个等级", "label": "量词"}, {"form": "等级制度", "label": "复合"}, {"form": "等級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "社会、组织中从高到低的地位层级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b64ca331-cee2-4a4d-bcc5-b9b5a93b48c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89107, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "等级", "is_correct": true, "explanation": "正确答案：等级（děng jí），指从高到低分成的一级一级。"}, {"text": "登记", "is_correct": false, "explanation": "dēng 与 děng 声调不同，jì 与 jí 声调也不同，意思是登记（把情况记录在册）。"}, {"text": "登基", "is_correct": false, "explanation": "dēng jī 与 děng jí 两个音节声调都不同，意思是登基（皇帝即位）。"}, {"text": "等积", "is_correct": false, "explanation": "第二音节 jī 与 jí 只有声调不同，意思是等积（面积相等）。"}], "explanations": {"等级": "正确答案：等级（děng jí），指从高到低分成的一级一级。", "登记": "dēng 与 děng 声调不同，jì 与 jí 声调也不同，意思是登记（把情况记录在册）。", "登基": "dēng jī 与 děng jí 两个音节声调都不同，意思是登基（皇帝即位）。", "等积": "第二音节 jī 与 jí 只有声调不同，意思是等积（面积相等）。"}, "sentence_index": null, "correct_answer": "等级"}, "level_3": {"options": [{"text": "等级", "is_correct": true, "explanation": "正确答案：等级指社会中从高到低的层级，与“很严格的”相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“严格的”修饰规定或制度，不能修饰天气。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”没有严格与否之分，与“很严格的”不相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是物体，不能说“很严格的”。"}], "explanations": {"等级": "正确答案：等级指社会中从高到低的层级，与“很严格的”相符。", "天气": "搭配：“严格的”修饰规定或制度，不能修饰天气。", "颜色": "语义：“颜色”没有严格与否之分，与“很严格的”不相符。", "窗户": "语义：“窗户”是物体，不能说“很严格的”。"}, "sentence_index": 0, "correct_answer": "等级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都要喝一杯等级。", "explanation": "这里应该用〈咖啡〉。“等级”指地位的高低层级，不能喝。"}, {"text": "这里离车站的等级很远，我们走路去吧。", "explanation": "这里应该用〈距离〉。“等级”指层次的高低，不能用来说路程的远近。"}, {"text": "他的等级比以前增加了三公斤。", "explanation": "这里应该用〈体重〉。“等级”指层次，不能用公斤来计量体重的增减。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89107, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "等级", "is_correct": true, "explanation": "正确答案：等级（děng jí），指从高到低分成的一级一级。"}, {"text": "省级", "is_correct": false, "explanation": "shěng 与 děng 声母不同（sh 与 d），声调相同，意思是省级（省一级的）。"}, {"text": "党籍", "is_correct": false, "explanation": "dǎng 与 děng 元音不同（a 与 e），声调相同，意思是党籍（党员的身份）。"}, {"text": "顶级", "is_correct": false, "explanation": "dǐng 与 děng 韵母不同（ing 与 eng），声调相同，意思是顶级（最高水平的）。"}], "explanations": {"等级": "正确答案：等级（děng jí），指从高到低分成的一级一级。", "省级": "shěng 与 děng 声母不同（sh 与 d），声调相同，意思是省级（省一级的）。", "党籍": "dǎng 与 děng 元音不同（a 与 e），声调相同，意思是党籍（党员的身份）。", "顶级": "dǐng 与 děng 韵母不同（ing 与 eng），声调相同，意思是顶级（最高水平的）。"}, "sentence_index": null, "correct_answer": "等级"}, "level_3": {"options": [{"text": "等级", "is_correct": true, "explanation": "正确答案：等级指地位的层级，与“比我高，所以我要听他的”相符。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不能说高低，与“比我高，所以我要听他的”不符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“高”不用来形容味道，且与“要听他的”的语境不通。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：“拖鞋”不是人，没有地位层级，也不会让人听从。"}], "explanations": {"等级": "正确答案：等级指地位的层级，与“比我高，所以我要听他的”相符。", "名字": "语义：“名字”不能说高低，与“比我高，所以我要听他的”不符。", "味道": "搭配：“高”不用来形容味道，且与“要听他的”的语境不通。", "拖鞋": "语义：“拖鞋”不是人，没有地位层级，也不会让人听从。"}, "sentence_index": 6, "correct_answer": "等级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的等级很快，比别的车都好。", "explanation": "这里应该用〈速度〉。“等级”指层级或质量的分级，不能用来说车的快慢。"}, {"text": "这个菜的等级很好吃，我很喜欢。", "explanation": "这里应该用〈味道〉。“等级”指地位的层级，不能说好吃。"}, {"text": "他是大学一等级的学生，每天都很忙。", "explanation": "这里应该用〈年级〉。“等级”指层次高低，不能用来说学校的学年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89107, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古代社会分成两等级。", "corrected_sentence": "古代社会分成两个等级。", "error_description": "“两”与“等级”之间要加量词“个”，应说“两个等级”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89107, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的等级高我，他负责安排工作。", "corrected_sentence": "他的等级比我高，他负责安排工作。", "error_description": "“高”与“我”之间要用“比”，比较结构应说“比我高”，不能说“高我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
