INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "按质量、程度等分成的级别。", "primary_collocate": null, "pronunciation": "děng jí", "ipa": "tɤŋ²¹⁴ tɕi³⁵", "syllable_count": 2, "sentences": [{"text": "这种茶叶分成三个等级。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果的等级越高，价格也越高。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店按服务分等级，等级高的更贵。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的成绩分五个等级。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把作业分成了A、B、C三个等级。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的质量等级很高。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的汉语水平是什么等级？", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院是全市最高等级的医院。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛肉有好几个等级，价格差别很大。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天空气质量的等级是良好。", "target_word": "等级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个等级", "label": "量词"}, {"form": "等级制度", "label": "复合"}, {"form": "等級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按质量、水平、程度划分的级别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b64ca331-cee2-4a4d-bcc5-b9b5a93b48c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89108, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "等级", "is_correct": true, "explanation": "正确答案：等级（děng jí），指按质量、程度等分成的级别。"}, {"text": "登记", "is_correct": false, "explanation": "dēng 与 děng 声调不同，jì 与 jí 声调也不同，意思是登记（把情况记录在册）。"}, {"text": "登基", "is_correct": false, "explanation": "dēng jī 与 děng jí 两个音节声调都不同，意思是登基（皇帝即位）。"}, {"text": "等积", "is_correct": false, "explanation": "第二音节 jī 与 jí 只有声调不同，意思是等积（面积相等）。"}], "explanations": {"等级": "正确答案：等级（děng jí），指按质量、程度等分成的级别。", "登记": "dēng 与 děng 声调不同，jì 与 jí 声调也不同，意思是登记（把情况记录在册）。", "登基": "dēng jī 与 děng jí 两个音节声调都不同，意思是登基（皇帝即位）。", "等积": "第二音节 jī 与 jí 只有声调不同，意思是等积（面积相等）。"}, "sentence_index": null, "correct_answer": "等级"}, "level_3": {"options": [{"text": "等级", "is_correct": true, "explanation": "正确答案：等级指按质量分成的级别，与“分成三个……”相符。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”是动物，不能把茶叶分成小猫。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”是称呼，与茶叶的分类不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“分成……年龄”搭配不当，茶叶没有年龄。"}], "explanations": {"等级": "正确答案：等级指按质量分成的级别，与“分成三个……”相符。", "小猫": "语义：“小猫”是动物，不能把茶叶分成小猫。", "名字": "语义：“名字”是称呼，与茶叶的分类不符。", "年龄": "搭配：“分成……年龄”搭配不当，茶叶没有年龄。"}, "sentence_index": 0, "correct_answer": "等级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家酒店的等级在火车站旁边。", "explanation": "这里应该用〈位置〉。“等级”指质量的级别，不能说在哪里。"}, {"text": "这件衣服的等级很便宜，我买了它。", "explanation": "这里应该用〈价格〉。“等级”指质量的分级，不能用“便宜”来说价钱。"}, {"text": "这个孩子的等级比去年增加了五公斤。", "explanation": "这里应该用〈体重〉。“等级”指质量或程度的级别，不能用公斤来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89108, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "等级", "is_correct": true, "explanation": "正确答案：等级（děng jí），指按质量、程度等分成的级别。"}, {"text": "省级", "is_correct": false, "explanation": "shěng 与 děng 声母不同（sh 与 d），声调相同，意思是省级（省一级的）。"}, {"text": "党籍", "is_correct": false, "explanation": "dǎng 与 děng 元音不同（a 与 e），声调相同，意思是党籍（党员的身份）。"}, {"text": "顶级", "is_correct": false, "explanation": "dǐng 与 děng 韵母不同（ing 与 eng），声调相同，意思是顶级（最高水平的）。"}], "explanations": {"等级": "正确答案：等级（děng jí），指按质量、程度等分成的级别。", "省级": "shěng 与 děng 声母不同（sh 与 d），声调相同，意思是省级（省一级的）。", "党籍": "dǎng 与 děng 元音不同（a 与 e），声调相同，意思是党籍（党员的身份）。", "顶级": "dǐng 与 děng 韵母不同（ing 与 eng），声调相同，意思是顶级（最高水平的）。"}, "sentence_index": null, "correct_answer": "等级"}, "level_3": {"options": [{"text": "等级", "is_correct": true, "explanation": "正确答案：等级指按质量、水平划分的级别，可以问“是什么等级”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与汉语水平无关，不能问“是什么颜色”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：汉语水平不是有味道的东西，不能问“是什么味道”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是人的身体指标，与“汉语水平”搭配不通。"}], "explanations": {"等级": "正确答案：等级指按质量、水平划分的级别，可以问“是什么等级”。", "颜色": "语义：“颜色”与汉语水平无关，不能问“是什么颜色”。", "味道": "语义：汉语水平不是有味道的东西，不能问“是什么味道”。", "体重": "搭配：“体重”是人的身体指标，与“汉语水平”搭配不通。"}, "sentence_index": 6, "correct_answer": "等级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的等级是一米八，比我高很多。", "explanation": "这里应该用〈身高〉。“等级”指级别，不能用来说身高。"}, {"text": "这种牛肉的等级是红色的。", "explanation": "这里应该用〈颜色〉。“等级”指质量的级别，没有红色之分。"}, {"text": "她在小学读二等级，成绩很好。", "explanation": "这里应该用〈年级〉。“等级”指质量或程度的分级，不能用来说学校的年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批茶叶分成两级等级。", "corrected_sentence": "这批茶叶分成两个等级。", "error_description": "“级”与“等级”重复，量词应用“个”，应说“两个等级”，不能说“两级等级”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种苹果分成四只等级。", "corrected_sentence": "这种苹果分成四个等级。", "error_description": "量词错误：“等级”要用量词“个”，不能用“只”（“只”多用于动物）。应为“四个等级”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b15a089-917b-497e-b4e9-c7cb81f1a235') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89109, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸福", "is_correct": true, "explanation": "反义：“幸福”与“悲惨”相对，指生活美满、没有痛苦。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”描述智力，与“悲惨”所指的遭遇没有相对关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无反义关系：“清楚”与“模糊”相对，与“悲惨”无关。"}, {"text": "美丽", "is_correct": false, "explanation": "无反义关系：“美丽”与“丑陋”相对，不与“悲惨”相对。"}], "correct_answer": "幸福", "explanations": {"幸福": "反义：“幸福”与“悲惨”相对，指生活美满、没有痛苦。", "聪明": "无反义关系：“聪明”描述智力，与“悲惨”所指的遭遇没有相对关系。", "清楚": "无反义关系：“清楚”与“模糊”相对，与“悲惨”无关。", "美丽": "无反义关系：“美丽”与“丑陋”相对，不与“悲惨”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89109, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸福", "is_correct": true, "explanation": "反义：“幸福”与“悲惨”相对，指生活美满、没有痛苦。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：“安静”与“吵闹”相对，与“悲惨”无关。"}, {"text": "硬", "is_correct": false, "explanation": "无反义关系：“硬”与“软”相对，不用于描述处境。"}, {"text": "冷", "is_correct": false, "explanation": "无反义关系：“冷”与“热”相对，不与“悲惨”相对。"}], "correct_answer": "幸福", "explanations": {"幸福": "反义：“幸福”与“悲惨”相对，指生活美满、没有痛苦。", "安静": "无反义关系：“安静”与“吵闹”相对，与“悲惨”无关。", "硬": "无反义关系：“硬”与“软”相对，不用于描述处境。", "冷": "无反义关系：“冷”与“热”相对，不与“悲惨”相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89109, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "悲惨是说一个人遇到很难过、很苦的事。", "primary_collocate": null, "pronunciation": "bēi cǎn", "ipa": "pei̯˥ tsʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他今天遇到了很悲惨的事。", "target_word": "悲惨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个小女孩的生活很悲惨。", "target_word": "悲惨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人住，过得很悲惨。", "target_word": "悲惨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我听了他悲惨的故事，心里很难过。", "target_word": "悲惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写了一个人悲惨的一生。", "target_word": "悲惨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说自己小时候很悲惨。", "target_word": "悲惨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他丢了工作，又生了病，真悲惨。", "target_word": "悲惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老人一个人生活，日子过得很悲惨。", "target_word": "悲惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友有一段悲惨的过去。", "target_word": "悲惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起他，我的生活不算悲惨。", "target_word": "悲惨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "悲惨的", "label": "定语形式"}, {"form": "悲惨地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "人遇到很难过很苦的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85c957fe-973b-4a12-846e-5e73e5065e34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89109, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悲惨", "is_correct": true, "explanation": "正确。悲惨形容遇到的事痛苦不幸，与“很”和“的事”搭配。"}, {"text": "灵巧", "is_correct": false, "explanation": "搭配：“灵巧”形容手脚或动作灵活，不修饰“事”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材，不能用来形容事情。"}, {"text": "细长", "is_correct": false, "explanation": "语义：“细长”描述形状，与遇到的事情无关。"}], "explanations": {"悲惨": "正确。悲惨形容遇到的事痛苦不幸，与“很”和“的事”搭配。", "灵巧": "搭配：“灵巧”形容手脚或动作灵活，不修饰“事”。", "高大": "体貌：“高大”形容人或物的身材，不能用来形容事情。", "细长": "语义：“细长”描述形状，与遇到的事情无关。"}, "sentence_index": 0, "correct_answer": "悲惨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张照片的光线很悲惨。", "explanation": "悲惨形容遭遇或处境，不能用来形容光线，这里应该说“柔和”或“昏暗”。"}, {"text": "这首歌的节奏很悲惨。", "explanation": "悲惨形容人的遭遇或处境，不能用来形容节奏，这里应该说“欢快”或“缓慢”。"}, {"text": "这块蛋糕的味道很悲惨。", "explanation": "悲惨形容人的遭遇或处境，不能用来形容食物的味道，这里应该说“甜”或“香”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89109, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悲惨", "is_correct": true, "explanation": "正确。悲惨形容遭遇痛苦不幸，与前面的“丢了工作”和“生了病”相呼应。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”用于外貌或事物美观，与丢工作、生病的处境不符。"}, {"text": "结实", "is_correct": false, "explanation": "体貌：“结实”形容身体强壮，与生病的处境相反。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”描述形状，与这句话描述的遭遇无关。"}], "explanations": {"悲惨": "正确。悲惨形容遭遇痛苦不幸，与前面的“丢了工作”和“生了病”相呼应。", "漂亮": "语义：“漂亮”用于外貌或事物美观，与丢工作、生病的处境不符。", "结实": "体貌：“结实”形容身体强壮，与生病的处境相反。", "圆": "语义：“圆”描述形状，与这句话描述的遭遇无关。"}, "sentence_index": 6, "correct_answer": "悲惨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服穿起来很悲惨。", "explanation": "悲惨形容遭遇或处境，不能用来形容衣服的样子，这里应该说“好看”或“合身”。"}, {"text": "这只杯子的重量很悲惨。", "explanation": "这里应该用〈沉〉。悲惨指遭遇痛苦不幸，不能用来形容物体的轻重，描述杯子分量大应说“沉”。"}, {"text": "这个箱子的大小很悲惨。", "explanation": "这里应该用〈大〉或〈小〉。悲惨指遭遇痛苦不幸，不能用来形容箱子的尺寸，描述箱子的大小应说“大”或“小”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她遇到了一件悲惨地事情。", "corrected_sentence": "她遇到了一件悲惨的事情。", "error_description": "错误：“悲惨地事情”。修饰名词要用“的”，“地”用于动词前作状语，正确应为“悲惨的事情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个人的处境很悲惨很。", "corrected_sentence": "这个人的处境很悲惨。", "error_description": "错误：“很悲惨很”。句末多出一个程度副词“很”，“很”只能放在形容词前面，正确应为“很悲惨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89110, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸福", "is_correct": true, "explanation": "反义：“幸福”与“悲惨”相对，指生活美满、没有痛苦。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”描述智力，与“悲惨”所指的处境遭遇没有相对关系。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：“安静”与“吵闹”相对，与“悲惨”无关。"}, {"text": "美丽", "is_correct": false, "explanation": "无反义关系：“美丽”与“丑陋”相对，不与“悲惨”相对。"}], "correct_answer": "幸福", "explanations": {"幸福": "反义：“幸福”与“悲惨”相对，指生活美满、没有痛苦。", "聪明": "无反义关系：“聪明”描述智力，与“悲惨”所指的处境遭遇没有相对关系。", "安静": "无反义关系：“安静”与“吵闹”相对，与“悲惨”无关。", "美丽": "无反义关系：“美丽”与“丑陋”相对，不与“悲惨”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89110, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幸福", "is_correct": true, "explanation": "反义：“幸福”与“悲惨”相对，指生活美满、没有痛苦。"}, {"text": "硬", "is_correct": false, "explanation": "无反义关系：“硬”与“软”相对，不用于描述处境。"}, {"text": "清楚", "is_correct": false, "explanation": "无反义关系：“清楚”与“模糊”相对，与“悲惨”无关。"}, {"text": "冷", "is_correct": false, "explanation": "无反义关系：“冷”与“热”相对，不与“悲惨”相对。"}], "correct_answer": "幸福", "explanations": {"幸福": "反义：“幸福”与“悲惨”相对，指生活美满、没有痛苦。", "硬": "无反义关系：“硬”与“软”相对，不用于描述处境。", "清楚": "无反义关系：“清楚”与“模糊”相对，与“悲惨”无关。", "冷": "无反义关系：“冷”与“热”相对，不与“悲惨”相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89110, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "处境或遭遇痛苦不幸，令人同情。", "primary_collocate": null, "pronunciation": "bēi cǎn", "ipa": "pei̯˥ tsʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个孩子的童年非常悲惨。", "target_word": "悲惨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争给人们带来了悲惨的生活。", "target_word": "悲惨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的命运很悲惨，大家都很同情他。", "target_word": "悲惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里讲了一个悲惨的故事。", "target_word": "悲惨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那场地震后的情景十分悲惨。", "target_word": "悲惨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人晚年过得很悲惨。", "target_word": "悲惨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她小时候的遭遇太悲惨了。", "target_word": "悲惨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个悲惨的消息让大家都哭了。", "target_word": "悲惨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他讲起了自己悲惨的经历。", "target_word": "悲惨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洪水过后，村子里的样子悲惨极了。", "target_word": "悲惨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "悲惨的", "label": "定语形式"}, {"form": "悲惨地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "处境遭遇痛苦不幸，令人同情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85c957fe-973b-4a12-846e-5e73e5065e34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悲惨", "is_correct": true, "explanation": "正确。悲惨形容童年遭遇痛苦不幸，与“非常”和“童年”搭配。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的智力，不能修饰“童年”这样的时期。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人的身材，不能用来描述童年的处境。"}, {"text": "红", "is_correct": false, "explanation": "语义：颜色词无法描述童年的处境，与句子语义不符。"}], "explanations": {"悲惨": "正确。悲惨形容童年遭遇痛苦不幸，与“非常”和“童年”搭配。", "聪明": "搭配：“聪明”形容人的智力，不能修饰“童年”这样的时期。", "高大": "体貌：“高大”形容人的身材，不能用来描述童年的处境。", "红": "语义：颜色词无法描述童年的处境，与句子语义不符。"}, "sentence_index": 0, "correct_answer": "悲惨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盒巧克力的味道很悲惨。", "explanation": "这里应该用〈苦涩〉。悲惨指遭遇痛苦不幸，不用来形容食物的味道，味道应说“苦涩”或“香甜”。"}, {"text": "这件毛衣穿着很悲惨。", "explanation": "悲惨指处境遭遇痛苦不幸，不能用来形容衣服穿着的感觉，这里应该说“暖和”或“舒服”。"}, {"text": "这条河的水很悲惨。", "explanation": "悲惨指处境遭遇痛苦不幸，不能用来形容河水，这里应该说“清”或“深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悲惨", "is_correct": true, "explanation": "正确。悲惨形容遭遇痛苦不幸，与“遭遇”和“太……了”搭配。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”用于外貌或事物美观，不能用来形容遭遇。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”形容心情，不修饰“遭遇”。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人的体型，不能用来描述遭遇。"}], "explanations": {"悲惨": "正确。悲惨形容遭遇痛苦不幸，与“遭遇”和“太……了”搭配。", "漂亮": "语义：“漂亮”用于外貌或事物美观，不能用来形容遭遇。", "高兴": "搭配：“高兴”形容心情，不修饰“遭遇”。", "胖": "体貌：“胖”形容人的体型，不能用来描述遭遇。"}, "sentence_index": 6, "correct_answer": "悲惨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的颜色很悲惨。", "explanation": "悲惨形容遭遇或处境，不能用来形容电脑的颜色，这里应该说“鲜艳”或“暗淡”。"}, {"text": "这条裙子的长度很悲惨。", "explanation": "这里应该用〈长〉。悲惨指处境遭遇痛苦不幸，不能用来形容裙子的长短。"}, {"text": "这座楼的高度很悲惨。", "explanation": "这里应该用〈高〉。悲惨指遭遇痛苦不幸，不能用来形容建筑的高矮，描述楼的高度应说“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那家人的生活很悲惨地。", "corrected_sentence": "那家人的生活很悲惨。", "error_description": "错误：“很悲惨地”。“悲惨”作谓语时不加“地”，“地”只用于动词前作状语，正确应为“很悲惨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的遭遇很悲惨很。", "corrected_sentence": "她的遭遇很悲惨。", "error_description": "错误：“很悲惨很”。句末多出一个程度副词“很”，“很”只能放在形容词前面，正确应为“很悲惨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4dcf72d-db4b-4b77-9bf1-636ec87bbfee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
