INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89112, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "成年女性。", "primary_collocate": null, "pronunciation": "nǚ zǐ", "ipa": "ny˨˩˦ tsɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "那位女子在车站等车。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个女子今年二十五岁了。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一位年轻女子走进了商店。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一名很有礼貌的女子。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆里坐着一位女子在看书。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有个女子在唱歌。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个女子手里拿着一把伞。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问了这位女子几个问题。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个穿红衣服的女子坐在窗边。", "target_word": "女子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女子在医院工作。", "target_word": "女子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "女子学校", "label": "复合"}, {"form": "女子足球", "label": "复合"}], "register": "书面", "sense_fingerprint": "成年女性；指人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07800451-dd71-4009-8d4c-1927c61a756d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女子", "is_correct": true, "explanation": "女子：成年女性，指“那位”女人，符合在车站等车的情境。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头没有腿，不会在车站等车。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：雕像是固定的艺术品，不会在车站等车。"}, {"text": "天使", "is_correct": false, "explanation": "语义：天使不需要在车站等车，与日常情境相矛盾。"}], "explanations": {"女子": "女子：成年女性，指“那位”女人，符合在车站等车的情境。", "石头": "体貌：石头没有腿，不会在车站等车。", "雕像": "语义：雕像是固定的艺术品，不会在车站等车。", "天使": "语义：天使不需要在车站等车，与日常情境相矛盾。"}, "sentence_index": 0, "correct_answer": "女子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹妹才五岁，是个可爱的女子。", "explanation": "这里应该用〈女孩〉。女子指成年女性，五岁的孩子应说女孩。"}, {"text": "门口站着一只女子。", "explanation": "这里应该用〈位〉或〈个〉。“只”用于动物或成对的东西，指人不用“只”。"}, {"text": "各位女子，欢迎光临本店。", "explanation": "这里应该用〈女士〉。称呼一群人时用“各位女士”，“女子”不作敬称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女子", "is_correct": true, "explanation": "女子：成年女性，与“手里拿着一把伞”的人物相符。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头没有手，形体上不能拿着伞。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是固定的建筑，不会手里拿伞。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有手，不能拿着伞。"}], "explanations": {"女子": "女子：成年女性，与“手里拿着一把伞”的人物相符。", "石头": "体貌：石头没有手，形体上不能拿着伞。", "房子": "语义：房子是固定的建筑，不会手里拿伞。", "桌子": "语义：桌子没有手，不能拿着伞。"}, "sentence_index": 6, "correct_answer": "女子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位女子才三个月大，很可爱。", "explanation": "这里应该用〈女婴〉。女子指长大的女人，三个月大的孩子应说女婴。"}, {"text": "这是我的女子，她今年十岁。", "explanation": "这里应该用〈女儿〉。女子不能用来指自己的女儿。"}, {"text": "我的女子很温柔。", "explanation": "这里应该用〈女朋友〉。女子指成年女性，不用来指自己的恋人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只女子走进了办公室。", "corrected_sentence": "那位女子走进了办公室。", "error_description": "量词错误：指人的“女子”应用量词“位”或“个”，不用“只”（“只”用于动物）。应说“那位女子”，不说“那只女子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位年轻的女子的坐在窗边。", "corrected_sentence": "一位年轻的女子坐在窗边。", "error_description": "多余的“的”：“年轻的女子”后不应再加“的”，应说“一位年轻的女子坐在窗边”，不说“一位年轻的女子的坐在窗边”（“女子的”成了名词性短语，句子没有谓语）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6934fd-af88-42ee-8f05-f584150832bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89113, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真诚", "is_correct": true, "explanation": "正确：真诚与虚伪意思相反，指心里真实、不做作。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：懒惰指不愿做事，与虚伪不构成反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：聪明指头脑灵活，与虚伪不构成反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：高兴指心情好，与虚伪不构成反义关系。"}], "correct_answer": "真诚", "explanations": {"真诚": "正确：真诚与虚伪意思相反，指心里真实、不做作。", "懒惰": "语义：懒惰指不愿做事，与虚伪不构成反义关系。", "聪明": "语义：聪明指头脑灵活，与虚伪不构成反义关系。", "高兴": "语义：高兴指心情好，与虚伪不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89113, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真诚", "is_correct": true, "explanation": "正确：真诚与虚伪意思相反，指心里真实、不做作。"}, {"text": "粗心", "is_correct": false, "explanation": "语义：粗心指做事不仔细，与虚伪不构成反义关系。"}, {"text": "勤劳", "is_correct": false, "explanation": "语义：勤劳指努力干活，与虚伪不构成反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：高兴指心情好，与虚伪不构成反义关系。"}], "correct_answer": "真诚", "explanations": {"真诚": "正确：真诚与虚伪意思相反，指心里真实、不做作。", "粗心": "语义：粗心指做事不仔细，与虚伪不构成反义关系。", "勤劳": "语义：勤劳指努力干活，与虚伪不构成反义关系。", "高兴": "语义：高兴指心情好，与虚伪不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89113, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "虚伪是心里不是这样想，嘴上却说得很好听，不真心。", "primary_collocate": null, "pronunciation": "xū wěi", "ipa": "ɕy˥ weɪ˨˩", "syllable_count": 2, "sentences": [{"text": "他说话很虚伪，我不相信他。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑得很虚伪，心里并不高兴。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢虚伪的朋友。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴上夸我，其实很虚伪。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的话听起来太虚伪了。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别这么虚伪，说真话吧。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虚伪地对我说“欢迎你”。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的关心让我觉得虚伪。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得她的客气有点虚伪。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人不要虚伪，要说真话。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "虛偽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "嘴上说得好听但心里不真心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f47168-7536-44bc-86ea-bc74d4627e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89113, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虚伪", "is_correct": true, "explanation": "正确：虚伪指心里不真诚、嘴上说好听，与“我不相信他”相符。"}, {"text": "诚实", "is_correct": false, "explanation": "语义：诚实是说真话，与后句“我不相信他”矛盾。"}, {"text": "真诚", "is_correct": false, "explanation": "语义：真诚指心里真实，与后句的不信任矛盾。"}, {"text": "可靠", "is_correct": false, "explanation": "语义：可靠指值得信赖，与后句“我不相信他”矛盾。"}], "explanations": {"虚伪": "正确：虚伪指心里不真诚、嘴上说好听，与“我不相信他”相符。", "诚实": "语义：诚实是说真话，与后句“我不相信他”矛盾。", "真诚": "语义：真诚指心里真实，与后句的不信任矛盾。", "可靠": "语义：可靠指值得信赖，与后句“我不相信他”矛盾。"}, "sentence_index": 0, "correct_answer": "虚伪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告的数据很虚伪，不能用。", "explanation": "这里应该用〈虚假〉。虚伪指人心口不一，不用于形容数据；说数据不真实要用〈虚假〉。"}, {"text": "今天的天气很虚伪，一会儿晴一会儿阴。", "explanation": "虚伪指人心口不一，只形容人的品性，不能用来形容天气，这句与此义不符。"}, {"text": "他病得很虚伪。", "explanation": "这里应该用〈虚弱〉。虚弱指身体没有力气，虚伪说的是人的品性，与此义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虚伪", "is_correct": true, "explanation": "正确：“虚伪地”修饰“说”，表示心口不一地说话，符合句意。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：雪白是颜色，不能形容说话的样子。"}, {"text": "咸", "is_correct": false, "explanation": "语义：咸是味道，不能用来形容说话的样子。"}, {"text": "圆", "is_correct": false, "explanation": "语义：圆是形状，不能用来形容说话的样子。"}], "explanations": {"虚伪": "正确：“虚伪地”修饰“说”，表示心口不一地说话，符合句意。", "雪白": "语义：雪白是颜色，不能形容说话的样子。", "咸": "语义：咸是味道，不能用来形容说话的样子。", "圆": "语义：圆是形状，不能用来形容说话的样子。"}, "sentence_index": 6, "correct_answer": "虚伪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他工作很虚伪，每天很晚才回家。", "explanation": "这里应该用〈辛苦〉。虚伪形容人心口不一，不能形容工作的劳累；形容劳累要用〈辛苦〉。"}, {"text": "这块蛋糕很虚伪，甜得很。", "explanation": "虚伪只形容人的品性，不能形容食物的味道，这句与此义不符。"}, {"text": "他的脚很虚伪，走路很快。", "explanation": "虚伪只形容人的品性，不能形容身体部位，这句与此义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说地很虚伪，大家都不信他。", "corrected_sentence": "他说得很虚伪，大家都不信他。", "error_description": "补语标记错误：“说”后表示程度的补语应用“得”，不用“地”（“地”用于动词前）。正确说法：他说得很虚伪。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他虚伪对我笑。", "corrected_sentence": "他虚伪地对我笑。", "error_description": "结构错误：“虚伪”修饰动作“笑”时，中间要加“地”。正确说法：他虚伪地对我笑。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89114, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真诚", "is_correct": true, "explanation": "正确：真诚与虚伪意思相反，指心里真实、不做作。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：勇敢指不怕困难或危险，与虚伪不构成反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：聪明指头脑灵活，与虚伪不构成反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：高兴指心情好，与虚伪不构成反义关系。"}], "correct_answer": "真诚", "explanations": {"真诚": "正确：真诚与虚伪意思相反，指心里真实、不做作。", "勇敢": "语义：勇敢指不怕困难或危险，与虚伪不构成反义关系。", "聪明": "语义：聪明指头脑灵活，与虚伪不构成反义关系。", "高兴": "语义：高兴指心情好，与虚伪不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89114, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真诚", "is_correct": true, "explanation": "正确：真诚与虚伪意思相反，指心里真实、不做作。"}, {"text": "勤劳", "is_correct": false, "explanation": "语义：勤劳指努力干活，与虚伪不构成反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：勇敢指不怕困难或危险，与虚伪不构成反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "语义：安静指声音小或不吵闹，与虚伪不构成反义关系。"}], "correct_answer": "真诚", "explanations": {"真诚": "正确：真诚与虚伪意思相反，指心里真实、不做作。", "勤劳": "语义：勤劳指努力干活，与虚伪不构成反义关系。", "勇敢": "语义：勇敢指不怕困难或危险，与虚伪不构成反义关系。", "安静": "语义：安静指声音小或不吵闹，与虚伪不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89114, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不真诚，做作，表里不一。", "primary_collocate": null, "pronunciation": "xū wěi", "ipa": "ɕy˥ weɪ˨˩", "syllable_count": 2, "sentences": [{"text": "他表里不一，是一个虚伪的人。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的样子很虚伪，一点都不自然。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的热情太做作，也太虚伪。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在人前很好，背后却很虚伪。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虚伪的人常常说一套做一套。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我受不了他那种虚伪的样子。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影里的人物很虚伪。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的道歉听着很虚伪。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很真诚，一点也不虚伪。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板对客人笑，对员工却很虚伪。", "target_word": "虚伪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "虛偽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不真诚、做作、表里不一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f47168-7536-44bc-86ea-bc74d4627e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "虚伪", "is_correct": true, "explanation": "正确：虚伪指表里不一，与句中“表里不一”相符。"}, {"text": "正直", "is_correct": false, "explanation": "语义：正直指品行端正，与“表里不一”矛盾。"}, {"text": "坦率", "is_correct": false, "explanation": "语义：坦率指直爽、不掩饰，与“表里不一”矛盾。"}, {"text": "老实", "is_correct": false, "explanation": "语义：老实指诚实、不说假话，与“表里不一”矛盾。"}], "explanations": {"虚伪": "正确：虚伪指表里不一，与句中“表里不一”相符。", "正直": "语义：正直指品行端正，与“表里不一”矛盾。", "坦率": "语义：坦率指直爽、不掩饰，与“表里不一”矛盾。", "老实": "语义：老实指诚实、不说假话，与“表里不一”矛盾。"}, "sentence_index": 0, "correct_answer": "虚伪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做事很虚伪，常常丢三落四。", "explanation": "这里应该用〈粗心〉。虚伪指心口不一，不形容做事的疏忽；做事疏忽要用〈粗心〉。"}, {"text": "这块木头很虚伪，硬得很。", "explanation": "虚伪只形容人的品性，不能形容木头的硬度，这句与此义不符。"}, {"text": "他遇到危险很虚伪，没有慌张。", "explanation": "这里应该用〈冷静〉。虚伪形容心口不一，不形容遇事镇定；遇事镇定要用〈冷静〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "虚伪", "is_correct": true, "explanation": "正确：虚伪可以形容人物的品性，符合句意。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：潮湿指物体含水多，不能形容人物的品性。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：干燥指没有水分，不能形容人物的品性。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：“漆黑”形容颜色，不能形容人物的品性。"}], "explanations": {"虚伪": "正确：虚伪可以形容人物的品性，符合句意。", "潮湿": "语义：潮湿指物体含水多，不能形容人物的品性。", "干燥": "语义：干燥指没有水分，不能形容人物的品性。", "漆黑": "语义：“漆黑”形容颜色，不能形容人物的品性。"}, "sentence_index": 6, "correct_answer": "虚伪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的字很虚伪，每一笔都很认真。", "explanation": "虚伪形容人心口不一，不能用来形容写字的用心程度，这句与此义不符。"}, {"text": "这盘菜很虚伪，咸得很。", "explanation": "虚伪只形容人的品性，不能形容菜的咸淡，这句与此义不符。"}, {"text": "他的基础很虚伪，很牢固。", "explanation": "这里应该用〈扎实〉。虚伪形容人的品性，不形容基础的牢靠；形容牢靠要用〈扎实〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她装地很虚伪，大家都看出来了。", "corrected_sentence": "她装得很虚伪，大家都看出来了。", "error_description": "补语标记错误：“装”后表示程度的补语应用“得”，不用“地”。正确说法：她装得很虚伪。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说话说很虚伪，大家都不信他。", "corrected_sentence": "他说话说得很虚伪，大家都不信他。", "error_description": "补语错误：“虚伪”作“说”的补语时，中间要加“得”。正确说法：说得很虚伪。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f33fe20-a28c-4193-8c97-1b9a53e5453a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
