INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89115, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "等号是写成\"=\"的符号，表示两边一样大。", "primary_collocate": null, "pronunciation": "děng hào", "ipa": "təŋ˨˩ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "请在数字中间写一个等号。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等号两边的数一样大。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个等号。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二加三后面要写等号。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把等号写得太小了。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个等号的两条线要一样长。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明忘了写等号，答案不对。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题的等号在哪儿？", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个符号是等号，不是减号。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "键盘上的等号在数字旁边。", "target_word": "等号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "等號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "等号：写成=的符号，表示两边一样大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '477a65e0-38ea-45c0-b671-a699ad3bfba3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89115, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等号", "is_correct": true, "explanation": "等号：写在数字中间表示相等的符号，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是能在数字中间写下的符号，句意不通。"}, {"text": "句子", "is_correct": false, "explanation": "搭配：“数字中间”只能写符号，不能写“句子”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”是人，不能被“写”在数字中间。"}], "explanations": {"等号": "等号：写在数字中间表示相等的符号，符合句意。", "手机": "语义：手机不是能在数字中间写下的符号，句意不通。", "句子": "搭配：“数字中间”只能写符号，不能写“句子”。", "老师": "语义：“老师”是人，不能被“写”在数字中间。"}, "sentence_index": 0, "correct_answer": "等号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "七比四大，它们中间要写等号。", "explanation": "这里应该用〈大于号〉。等号表示两边相等，七比四大时应该用大于号“>”。"}, {"text": "二和三相加，中间要写等号。", "explanation": "这里应该用〈加号〉。两数相加，中间要写加号“+”，写等号就表示两边相等了。"}, {"text": "三比五小，它们中间要写等号。", "explanation": "这里应该用〈小于号〉。三比五小，应该用小于号“<”，等号表示相等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89115, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等号", "is_correct": true, "explanation": "等号：这里应该写的符号，漏写后答案就不对了，句意通顺。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不能用来“写”，句意不通。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“写”不能与“电视”搭配，应说“看电视”。"}, {"text": "水", "is_correct": false, "explanation": "语义：“水”不是可以写下的东西，句意不通。"}], "explanations": {"等号": "等号：这里应该写的符号，漏写后答案就不对了，句意通顺。", "面包": "语义：面包不能用来“写”，句意不通。", "电视": "搭配：“写”不能与“电视”搭配，应说“看电视”。", "水": "语义：“水”不是可以写下的东西，句意不通。"}, "sentence_index": 6, "correct_answer": "等号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "键盘上的一把等号在数字旁边。", "explanation": "这里应该用〈个〉。“把”多用于有柄或能握住的东西，等号是符号，不能用“把”。"}, {"text": "键盘上的一条等号在数字旁边。", "explanation": "这里应该用〈个〉。“条”多用于细长的东西，如鱼、裤子，等号不能用“条”。"}, {"text": "键盘上的一块等号在数字旁边。", "explanation": "这里应该用〈个〉。“块”多用于有块状形状的东西，等号是符号，不能用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在作业本上写了一只等号。", "corrected_sentence": "他在作业本上写了一个等号。", "error_description": "错误：量词“只”用错。等号是符号，应该用量词“个”，“只”多用于动物或成对物品中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (89115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "数学课上老师让我画一只等号。", "corrected_sentence": "数学课上老师让我画一个等号。", "error_description": "错误：量词“只”用错。等号是符号，应该用量词“个”，“只”多用于动物或成对物品中的一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522f02cd-8380-4d48-8fb8-ac4f9ce28e33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
